window.PK=window.PK||{};window.PK.peptides=[{"slug":"bpc-157","name":"BPC-157","synonyme":["Body Protection Compound 157","PL 14736"],"kategorie":"Regeneration","studienlage":"frühe klinische Studien","kurz":"Een synthetisch peptide dat voornamelijk in preklinische modellen van weefselregeneratie is bestudeerd.","kurz_en":"Een synthetisch peptide dat voornamelijk in preklinische modellen van weefselregeneratie is bestudeerd.","beschreibung":"BPC-157 is een synthetisch pentadecapeptide waarvan de sequentie is afgeleid van een beschermend eiwit dat in menselijke maagzuur wordt gevonden. Het is onder de meest bestudeerde peptiden in weefselregeneratieresearch, met een brede basis van dierstudies en een beperkt aantal kleine menselijke studies. Onderzoeksfocusgebieden omvatten pezen, ligamenten, de gastro-intestinale lining en wondgenezing.","beschreibung_en":"BPC-157 is een synthetisch pentadecapeptide waarvan de sequentie is afgeleid van een beschermend eiwit dat in menselijke maagzuur wordt gevonden. Het is onder de meest bestudeerde peptiden in weefselregeneratieresearch, met een brede basis van dierstudies en een beperkt aantal kleine menselijke studies. Onderzoeksfocusgebieden omvatten pezen, ligamenten, de gastro-intestinale lining en wondgenezing.","mechanismus":"In preklinische modellen is BPC-157 beschreven als betrokken bij angiogenese via de VEGFR2-AKT-eNOS route, wat nieuwe bloedvatvorming in beschadigd weefsel ondersteunt. Andere bestudeerde mechanismen omvatten de opregulatie van groeihormoonreceptoren, modulatie van ontstekingscytokinen en ondersteuning van celmigratie via de FAK-paxilline route. De exacte mechanismen bij mensen zijn nog niet volledig vastgesteld.","mechanismus_en":"In preklinische modellen is BPC-157 beschreven als betrokken bij angiogenese via de VEGFR2-AKT-eNOS route, wat nieuwe bloedvatvorming in beschadigd weefsel ondersteunt. Andere bestudeerde mechanismen omvatten de opregulatie van groeihormoonreceptoren, modulatie van ontstekingscytokinen en ondersteuning van celmigratie via de FAK-paxilline route. De exacte mechanismen bij mensen zijn nog niet volledig vastgesteld.","evidenz":[{"art":"preklinisch","kurz":"Een systematische review uit 2025 evalueerde literatuur van 1993 tot 2024 en omvatte 35 preklinische dierstudies over spier-, pezen-, ligament- en botletsel, die voornamelijk positieve genezingsresultaten beschreven.","kurz_en":"Een systematische review uit 2025 evalueerde literatuur van 1993 tot 2024 en omvatte 35 preklinische dierstudies over spier-, pezen-, ligament- en botletsel, die voornamelijk positieve genezingsresultaten beschreven.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"klinisch","kurz":"Dezelfde review identificeerde een retrospectieve klinische casusserie waarin 7 van de 12 patiënten pijnverlichting rapporteerden die langer duurde dan zes maanden na intra-articulaire knieinjecties.","kurz_en":"Dezelfde review identificeerde een retrospectieve klinische casusserie waarin 7 van de 12 patiënten pijnverlichting rapporteerden die langer duurde dan zes maanden na intra-articulaire knieinjecties.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"klinisch","kurz":"Een retrospectieve review van 16 patiënten met kniepijn beschreef significante verbetering bij 14 van hen tijdens een opvolgperiode van zes tot twaalf maanden. Er was geen controlegroep.","kurz_en":"Een retrospectieve review van 16 patiënten met kniepijn beschreef significante verbetering bij 14 van hen tijdens een opvolgperiode van zes tot twaalf maanden. Er was geen controlegroep.","quelle":"Lee & Padgett 2021, Altern Ther Health Med, PMID 34324435"}],"sicherheit":["Placebo-gecontroleerde menselijke veiligheidsgegevens zijn grotendeels afwezig, de meeste veiligheidsverklaringen zijn afkomstig uit dierlijke modellen.","Op mechanistisch niveau wordt besproken dat dezelfde routes die angiogenese en celproliferatie tijdens het herstel aansturen, theoretisch ook bestaande tumorgroei kunnen ondersteunen. Een causale link bij mensen is niet vastgesteld.","De beschikbare kleine menselijke studies rapporteerden geen ernstige bijwerkingen.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"sicherheit_en":["Placebo-gecontroleerde menselijke veiligheidsgegevens zijn grotendeels afwezig, de meeste veiligheidsverklaringen zijn afkomstig uit dierlijke modellen.","Op mechanistisch niveau wordt besproken dat dezelfde routes die angiogenese en celproliferatie tijdens het herstel aansturen, theoretisch ook bestaande tumorgroei kunnen ondersteunen. Een causale link bij mensen is niet vastgesteld.","De beschikbare kleine menselijke studies rapporteerden geen ernstige bijwerkingen.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"BPC-157 is niet toegelaten als geneesmiddel in Duitsland, de EU of de Verenigde Staten en is niet geclassificeerd als voedingsmiddel. Het wordt uitsluitend verkocht als chemische stof voor onderzoek.","rechtsstatus_en":"BPC-157 is niet toegelaten als geneesmiddel in Duitsland, de EU of de Verenigde Staten en is niet geclassificeerd als voedingsmiddel. Het wordt uitsluitend verkocht als chemische stof voor onderzoek.","typischeMg":[],"faq":[{"q":"Is BPC-157 een goedgekeurd medicijn?","a":"Nee. BPC-157 is niet goedgekeurd als medicijn in de EU of de Verenigde Staten. Het wordt commercieel alleen verkocht als een chemische stof voor onderzoek voor laboratoriumgebruik, niet voor menselijk gebruik.","q_en":"Is BPC-157 een goedgekeurd medicijn?","a_en":"Nee. BPC-157 is niet goedgekeurd als medicijn in de EU of de Verenigde Staten. Het wordt commercieel alleen verkocht als een chemische stof voor onderzoek voor laboratoriumgebruik, niet voor menselijk gebruik."},{"q":"Waar komt de BPC-157 sequentie vandaan?","a":"Het is afgeleid van een beschermend eiwit dat in menselijke maagzuur wordt gevonden, wat ook de oorsprong is van de naam Body Protection Compound.","q_en":"Waar komt de BPC-157 sequentie vandaan?","a_en":"Het is afgeleid van een beschermend eiwit dat in menselijke maagzuur wordt gevonden, wat ook de oorsprong is van de naam Body Protection Compound."},{"q":"Zijn er menselijke studies over BPC-157?","a":"Er zijn enkele kleine studies en casusseries met methodologische beperkingen, maar geen grote, placebo-gecontroleerde proeven. Het meeste bewijs komt van dierlijke modellen.","q_en":"Zijn er menselijke studies over BPC-157?","a_en":"Er zijn enkele kleine studies en casusseries met methodologische beperkingen, maar geen grote, placebo-gecontroleerde proeven. Het meeste bewijs komt van dierlijke modellen."}],"seo":{"title":"BPC-157: onderzoeksprofiel en bewijs","title_en":"BPC-157: onderzoeksprofiel en bewijs","description":"BPC-157 overzicht: oorsprong, mechanisme, bewijs en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext.","description_en":"BPC-157 overzicht: oorsprong, mechanisme, bewijs en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext."},"demo":false,"steckbrief":{"cas":"137525-51-0","molekulargewicht":"1419.5 g/mol","aminosaeuren":15,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":15,"quellen":["PubChem CID 9941957","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, commercieel standaard)"},"verwandt":["tb-500","ghk-cu","thymosin-alpha-1","pentadeca-arginate"]},{"slug":"pentadeca-arginate","name":"Pentadeca Arginate (PDA)","synonyme":["PDA","BPC-157 arginaatzout"],"kategorie":"Regeneration","studienlage":"präklinisch","kurz":"Een pentadecapeptide dat dezelfde aminozuursequentie deelt als BPC-157, aangeboden als een argininezout voor verbeterde oplosbaarheid en stabiliteit.","kurz_en":"Een pentadecapeptide dat dezelfde aminozuursequentie deelt als BPC-157, aangeboden als een argininezout voor verbeterde oplosbaarheid en stabiliteit.","beschreibung":"Pentadeca Arginate, vaak afgekort PDA, heeft dezelfde 15-aminozuursequentie als het bekende peptide BPC-157. Het verschil zit in het tegenion: in plaats van een acetaatzout, is de sequentie gebonden aan arginine, wat leveranciers beschrijven als verbetering van oplosbaarheid en houdbaarheid. Onafhankelijke studies die dit specifieke zoutvorm onderzoeken, zijn nog niet beschikbaar.","beschreibung_en":"Pentadeca Arginate, vaak afgekort PDA, heeft dezelfde 15-aminozuursequentie als het bekende peptide BPC-157. Het verschil zit in het tegenion: in plaats van een acetaatzout, is de sequentie gebonden aan arginine, wat leveranciers beschrijven als verbetering van oplosbaarheid en houdbaarheid. Onafhankelijke studies die dit specifieke zoutvorm onderzoeken, zijn nog niet beschikbaar.","mechanismus":"Aangezien de aminozuursequentie identiek is aan BPC-157, zijn de mechanismen die in preklinische modellen worden beschreven gebaseerd op dezelfde onderliggende structuur, inclusief betrokkenheid bij angiogenese via de VEGFR2-AKT-eNOS route en modulatie van inflammatoire processen. Of de argininebinding deze effecten verandert, versnelt of vertraagt, is niet onafhankelijk onderzocht. De exacte mechanismen bij mensen blijven onopgelost zelfs voor de moedersequentie zelf.","mechanismus_en":"Aangezien de aminozuursequentie identiek is aan BPC-157, zijn de mechanismen die in preklinische modellen worden beschreven gebaseerd op dezelfde onderliggende structuur, inclusief betrokkenheid bij angiogenese via de VEGFR2-AKT-eNOS route en modulatie van inflammatoire processen. Of de argininebinding deze effecten verandert, versnelt of vertraagt, is niet onafhankelijk onderzocht. De exacte mechanismen bij mensen blijven onopgelost zelfs voor de moedersequentie zelf.","evidenz":[{"art":"preklinisch","kurz":"Omdat Pentadeca Arginate zijn sequentie deelt met BPC-157, baseert het beschikbare bewijs zich op studies van de oudersequentie. Een systematische review uit 2025 evalueerde 35 pre-klinische dierstudies over spier, pees, ligament en botletsel, die voornamelijk positieve herstelresultaten beschreven.","kurz_en":"Omdat Pentadeca Arginate zijn sequentie deelt met BPC-157, baseert het beschikbare bewijs zich op studies van de oudersequentie. Een systematische review uit 2025 evalueerde 35 pre-klinische dierstudies over spier, pees, ligament en botletsel, die voornamelijk positieve herstelresultaten beschreven.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"preklinisch","kurz":"Een celstudie beschreef activatie en opregulatie van VEGFR2, een sleutelreceptor bij de vorming van bloedvaten, voor dezelfde sequentie, vergezeld van verhoogde endotheelbuisvorming in het laboratoriummodel.","kurz_en":"Een celstudie beschreef activatie en opregulatie van VEGFR2, een sleutelreceptor bij de vorming van bloedvaten, voor dezelfde sequentie, vergezeld van verhoogde endotheelbuisvorming in het laboratoriummodel.","quelle":"Hsieh et al. 2016, Journal of Molecular Medicine, PMID 27847966"}],"sicherheit":["Er bestaan geen onafhankelijke veiligheidsgegevens voor de argininezoutvorm zelf, een gerichte literatuurzoektocht leverde geen resultaten op.","Placebo-gecontroleerde menselijke gegevens ontbreken grotendeels voor de onderliggende sequentie, de meeste veiligheidsverklaringen zijn afkomstig uit dierlijke modellen.","Op mechanistisch niveau wordt besproken dat dezelfde routes die angiogenese en celproliferatie tijdens het herstel aansturen, theoretisch ook bestaande tumorgroei kunnen ondersteunen. Een causale link bij mensen is niet vastgesteld.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"sicherheit_en":["Er bestaan geen onafhankelijke veiligheidsgegevens voor de argininezoutvorm zelf, een gerichte literatuurzoektocht leverde geen resultaten op.","Placebo-gecontroleerde menselijke gegevens ontbreken grotendeels voor de onderliggende sequentie, de meeste veiligheidsverklaringen zijn afkomstig uit dierlijke modellen.","Op mechanistisch niveau wordt besproken dat dezelfde routes die angiogenese en celproliferatie tijdens het herstel aansturen, theoretisch ook bestaande tumorgroei kunnen ondersteunen. Een causale link bij mensen is niet vastgesteld.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Pentadeca Arginate is niet toegelaten als geneesmiddel in Duitsland, de EU of de Verenigde Staten en is niet geclassificeerd als voedingsmiddel. Het wordt uitsluitend verkocht als chemische stof voor onderzoek.","rechtsstatus_en":"Pentadeca Arginate is niet toegelaten als geneesmiddel in Duitsland, de EU of de Verenigde Staten en is niet geclassificeerd als voedingsmiddel. Het wordt uitsluitend verkocht als chemische stof voor onderzoek.","typischeMg":[],"faq":[{"q":"Is Pentadeca Arginate hetzelfde als BPC-157?","a":"De aminozuursequentie is identiek. Het verschil ligt in het tegenion: BPC-157 wordt meestal aangeboden als een acetaatzout, Pentadeca Arginate als een argininezout, wat leveranciers beschrijven als verbetering van de oplosbaarheid.","q_en":"Is Pentadeca Arginate hetzelfde als BPC-157?","a_en":"De aminozuursequentie is identiek. Het verschil ligt in het tegenion: BPC-157 wordt meestal aangeboden als een acetaatzout, Pentadeca Arginate als een argininezout, wat leveranciers beschrijven als verbetering van de oplosbaarheid."},{"q":"Bestaan er onafhankelijke studies over de argininezoutvorm?","a":"Nee, een gerichte literatuurzoektocht vond geen onafhankelijke studies over de argininezoutvorm zelf. Het beschikbare bewijs betreft de oudersequentie van BPC-157.","q_en":"Bestaan er onafhankelijke studies over de argininezoutvorm?","a_en":"Nee, een gerichte literatuurzoektocht vond geen onafhankelijke studies over de argininezoutvorm zelf. Het beschikbare bewijs betreft de oudersequentie van BPC-157."},{"q":"Is Pentadeca Arginate een goedgekeurd medicijn?","a":"Nee. Het is niet goedgekeurd in de EU of de Verenigde Staten en wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumgebruik.","q_en":"Is Pentadeca Arginate een goedgekeurd medicijn?","a_en":"Nee. Het is niet goedgekeurd in de EU of de Verenigde Staten en wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumgebruik."}],"seo":{"title":"Pentadeca Arginate (PDA): Onderzoeksprofiel & Bewijs","title_en":"Pentadeca Arginate (PDA): Onderzoeksprofiel & Bewijs","description":"Pentadeca Arginate overzicht: sequentie-identiteit met BPC-157, bewijs over de oudersequentie en veiligheidsprofiel, feitelijk gepresenteerd voor onderzoek.","description_en":"Pentadeca Arginate overzicht: sequentie-identiteit met BPC-157, bewijs over de oudersequentie en veiligheidsprofiel, feitelijk gepresenteerd voor onderzoek."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":null,"aminosaeuren":15,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":15,"quellen":["chemverify Katalog 14.09.2026 (CAS/Molekulargewicht dort nicht geführt, PubChem: kein Eintrag für Pentadeca Arginate)"]},"verwandt":["bpc-157","tb-500","ghk-cu"]},{"slug":"tb-500","name":"TB-500","synonyme":["Thymosine-bèta-4-fragment","TB4 Frag"],"kategorie":"Regeneration","studienlage":"präklinisch","kurz":"Een synthetisch fragment van het eigen eiwit van het lichaam thymosine beta-4, bestudeerd in pre-klinisch onderzoek naar celmigratie en weefselregeneratie.","kurz_en":"Een synthetisch fragment van het eigen eiwit van het lichaam thymosine beta-4, bestudeerd in pre-klinisch onderzoek naar celmigratie en weefselregeneratie.","beschreibung":"TB-500 is de synthetisch geproduceerde, zeven-aminozuur kernsequentie van het eigen eiwit van het lichaam thymosine beta-4. De meeste beschikbare gegevens, inclusief klinische studies, betreffen het volledige 43-aminozuur thymosine beta-4, niet het geïsoleerde TB-500 fragment zelf. Onderzoeksgebieden omvatten celmigratie, angiogenese en een mogelijke rol bij de activatie van haarfollikels.","beschreibung_en":"TB-500 is de synthetisch geproduceerde, zeven-aminozuur kernsequentie van het eigen eiwit van het lichaam thymosine beta-4. De meeste beschikbare gegevens, inclusief klinische studies, betreffen het volledige 43-aminozuur thymosine beta-4, niet het geïsoleerde TB-500 fragment zelf. Onderzoeksgebieden omvatten celmigratie, angiogenese en een mogelijke rol bij de activatie van haarfollikels.","mechanismus":"De bestudeerde kernsequentie bindt G-actine, een bouwsteen van het cytoskelet, waardoor de celbeweging binnen het weefsel wordt beïnvloed. In het volledige thymosine beta-4 eiwit zijn ook betrokkenheid bij angiogenese door verhoogde VEGF expressie en een ontstekingsregulerend effect via de NF-κB route beschreven. Of deze mechanismen volledig overgaan op het geïsoleerde TB-500 fragment niet wetenschappelijk vastgesteld is.","mechanismus_en":"De bestudeerde kernsequentie bindt G-actine, een bouwsteen van het cytoskelet, waardoor de celbeweging binnen het weefsel wordt beïnvloed. In het volledige thymosine beta-4 eiwit zijn ook betrokkenheid bij angiogenese door verhoogde VEGF expressie en een ontstekingsregulerend effect via de NF-κB route beschreven. Of deze mechanismen volledig overgaan op het geïsoleerde TB-500 fragment niet wetenschappelijk vastgesteld is.","evidenz":[{"art":"preklinisch","kurz":"Een studie in ratten en muizen beschreef dat de actieve sequentie van thymosine beta-4, die ook TB-500 vormt, de migratie van stamcellen binnen de haarzakje beïnvloedde.","kurz_en":"Een studie in ratten en muizen beschreef dat de actieve sequentie van thymosine beta-4, die ook TB-500 vormt, de migratie van stamcellen binnen de haarzakje beïnvloedde.","quelle":"Philp et al. 2004, FASEB Journal, PMID 14657002"},{"art":"klinisch","kurz":"Een gerandomiseerd, placebo-gecontroleerde klinische proef bij patiënten met ernstige droge ogen testte een oogdruppelformulering van het volledige thymosine beta-4 eiwit en beschreef verbeterde tekenen en symptomen vergeleken met placebo. De proef omvatte het volledige eiwit, niet het TB-500 fragment zelf.","kurz_en":"Een gerandomiseerd, placebo-gecontroleerde klinische proef bij patiënten met ernstige droge ogen testte een oogdruppelformulering van het volledige thymosine beta-4 eiwit en beschreef verbeterde tekenen en symptomen vergeleken met placebo. De proef omvatte het volledige eiwit, niet het TB-500 fragment zelf.","quelle":"Sosne et al. 2015, Cornea, PMID 25826322"}],"sicherheit":["Voor TB-500 als geïsoleerd fragment zijn er geen onafhankelijke gecontroleerde menselijke veiligheidsstudies beschikbaar.","Voor het volledige thymosine beta-4 eiwit hebben klinische studies voornamelijk milde en tijdelijke bijwerkingen beschreven.","Op mechanistisch niveau wordt een theoretische link tussen angiogenesebevorderende effecten en bestaande tumorgroei besproken, een causale verbinding is niet vastgesteld.","Thymosine beta-4 en gerelateerde fragmenten staan op de verbodenlijst van het World Anti-Doping Agency."],"sicherheit_en":["Voor TB-500 als geïsoleerd fragment zijn er geen onafhankelijke gecontroleerde menselijke veiligheidsstudies beschikbaar.","Voor het volledige thymosine beta-4 eiwit hebben klinische studies voornamelijk milde en tijdelijke bijwerkingen beschreven.","Op mechanistisch niveau wordt een theoretische link tussen angiogenesebevorderende effecten en bestaande tumorgroei besproken, een causale verbinding is niet vastgesteld.","Thymosine beta-4 en gerelateerde fragmenten staan op de verbodenlijst van het World Anti-Doping Agency."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"TB-500 is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, en het wordt uitsluitend verkocht als een chemische stof voor onderzoek. Het gerelateerde eiwit thymosine beta-4 is eveneens niet goedgekeurd als een losstaand medicijn.","rechtsstatus_en":"TB-500 is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, en het wordt uitsluitend verkocht als een chemische stof voor onderzoek. Het gerelateerde eiwit thymosine beta-4 is eveneens niet goedgekeurd als een losstaand medicijn.","typischeMg":[],"faq":[{"q":"Is TB-500 hetzelfde als thymosine beta-4?","a":"Nee. TB-500 is een synthetisch zeven-aminozuur fragment van de volledige 43-aminozuur thymosine beta-4 sequentie. De meeste klinische gegevens betreffen het volledige eiwit, niet het fragment.","q_en":"Is TB-500 hetzelfde als thymosine beta-4?","a_en":"Nee. TB-500 is een synthetisch zeven-aminozuur fragment van de volledige 43-aminozuur thymosine beta-4 sequentie. De meeste klinische gegevens betreffen het volledige eiwit, niet het fragment."},{"q":"Zijn er klinische studies over TB-500 zelf?","a":"Er zijn geen onafhankelijke gecontroleerde menselijke studies op het geïsoleerde TB-500 fragment beschikbaar. Beschikbare klinische gegevens komen van het volledige thymosine beta-4 eiwit.","q_en":"Zijn er klinische studies over TB-500 zelf?","a_en":"Er zijn geen onafhankelijke gecontroleerde menselijke studies op het geïsoleerde TB-500 fragment beschikbaar. Beschikbare klinische gegevens komen van het volledige thymosine beta-4 eiwit."},{"q":"Is TB-500 relevant voor antidopingregels?","a":"Thymosine beta-4 en gerelateerde fragmenten staan op de verbodenlijst van het World Anti-Doping Agency.","q_en":"Is TB-500 relevant voor antidopingregels?","a_en":"Thymosine beta-4 en gerelateerde fragmenten staan op de verbodenlijst van het World Anti-Doping Agency."}],"seo":{"title":"TB-500: onderzoeksprofiel en bewijs","title_en":"TB-500: onderzoeksprofiel en bewijs","description":"TB-500 overzicht: oorsprong uit thymosine beta-4, mechanisme, bewijs en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext.","description_en":"TB-500 overzicht: oorsprong uit thymosine beta-4, mechanisme, bewijs en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":"4963 g/mol","aminosaeuren":43,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":43,"quellen":["PubChem CID 45382195","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, commercieel standaard)"},"verwandt":["bpc-157","ghk-cu","thymosin-alpha-1","pentadeca-arginate"]},{"slug":"5-amino-1mq","name":"5-Amino-1MQ","synonyme":["5-Amino 1MQ","5A1MQ","NNMT-remmer"],"kategorie":"Stoffwechsel","studienlage":"präklinisch","kurz":"Een klein molecuul en selectieve remmer van het enzym nicotinamide N-methyltransferase (NNMT), tot op heden uitsluitend bestudeerd in preklinische dierlijke modellen gerelateerd aan vetmetabolisme.","kurz_en":"Een klein molecuul en selectieve remmer van het enzym nicotinamide N-methyltransferase (NNMT), tot op heden uitsluitend bestudeerd in preklinische dierlijke modellen gerelateerd aan vetmetabolisme.","beschreibung":"5-Amino-1MQ is geen peptide maar een klein molecuul, een selectieve, oraal biobeschikbare inhibitor van nicotinamide N-methyltransferase (NNMT). Het heeft een molecuulgewicht van 173,21 Da, en commercieel verkochte onderzoeksbatches hebben doorgaans een zuiverheid van minstens 98 procent. Het wordt gelist onder de metabolisme categorie omdat NNMT betrokken is bij energie metabolisme in vetweefsel en spier. Tot op heden zijn alleen pre-klinische gegevens uit knaagdiermodellen beschikbaar, en er zijn geen gecontroleerde menselijke studies bekend.","beschreibung_en":"5-Amino-1MQ is geen peptide maar een klein molecuul, een selectieve, oraal biobeschikbare inhibitor van nicotinamide N-methyltransferase (NNMT). Het heeft een molecuulgewicht van 173,21 Da, en commercieel verkochte onderzoeksbatches hebben doorgaans een zuiverheid van minstens 98 procent. Het wordt gelist onder de metabolisme categorie omdat NNMT betrokken is bij energie metabolisme in vetweefsel en spier. Tot op heden zijn alleen pre-klinische gegevens uit knaagdiermodellen beschikbaar, en er zijn geen gecontroleerde menselijke studies bekend.","mechanismus":"NNMT transfereert een methylgroep van S-adenosylmethionine (SAM) naar nicotinamide, een precursor van NAD+, waarbij 1-methylnicotinamide wordt gevormd. Deze reactie verbruikt zowel SAM als de NAD+ precursor nicotinamide. 5-Amino-1MQ remt dit enzym selectief, wat intracellulaire NAD+ en SAM niveaus in vet- en spiercellen in dierlijke modellen behield. In pre-klinisch onderzoek is dit gekoppeld aan verhoogde energieverbruik, verminderde adipocytenomvang en verbeterde regeneratieve capaciteit van spierweefsel.","mechanismus_en":"NNMT transfereert een methylgroep van S-adenosylmethionine (SAM) naar nicotinamide, een precursor van NAD+, waarbij 1-methylnicotinamide wordt gevormd. Deze reactie verbruikt zowel SAM als de NAD+ precursor nicotinamide. 5-Amino-1MQ remt dit enzym selectief, wat intracellulaire NAD+ en SAM niveaus in vet- en spiercellen in dierlijke modellen behield. In pre-klinisch onderzoek is dit gekoppeld aan verhoogde energieverbruik, verminderde adipocytenomvang en verbeterde regeneratieve capaciteit van spierweefsel.","evidenz":[{"art":"preklinisch","kurz":"In een muismodel met genetische knockdown van NNMT in vetweefsel werd bescherming tegen dieet-geïnduceerde obesitas waargenomen vergeleken met controledieren, samen met verhoogd energieverbruik.","kurz_en":"In een muismodel met genetische knockdown van NNMT in vetweefsel werd bescherming tegen dieet-geïnduceerde obesitas waargenomen vergeleken met controledieren, samen met verhoogd energieverbruik.","quelle":"Kraus D et al. 2014, Nature 508:258-262, PMID 24717514"},{"art":"preklinisch","kurz":"Bij dieet-geïnduceerde obese muizen verminderde elf dagen toediening van 5-Amino-1MQ het lichaamsgewicht, vetmassa en adipocytenomvang vergeleken met controledieren, zonder de voedselinname te veranderen.","kurz_en":"Bij dieet-geïnduceerde obese muizen verminderde elf dagen toediening van 5-Amino-1MQ het lichaamsgewicht, vetmassa en adipocytenomvang vergeleken met controledieren, zonder de voedselinname te veranderen.","quelle":"Neelakantan H et al. 2018, Biochemical Pharmacology, PMID 29155147"},{"art":"preklinisch","kurz":"Bij verouderde muizen werd een NNMT-inhibitor geassocieerd met reactivering van senescente spierstamcellen en verbeterde regeneratieve capaciteit van skeletspier na letsel.","kurz_en":"Bij verouderde muizen werd een NNMT-inhibitor geassocieerd met reactivering van senescente spierstamcellen en verbeterde regeneratieve capaciteit van skeletspier na letsel.","quelle":"Neelakantan H et al. 2019, Biochemical Pharmacology 163:481-492, PMID 30753815"},{"art":"preklinisch","kurz":"Het combineren van een caloriebeperkt dieet met 5-Amino-1MQ normaliseerde het lichaamsvetpercentage en gewicht sneller bij dieet-geïnduceerde obese muizen dan alleen een dieetverandering, terwijl ook de samenstelling van het darmmicrobioom werd veranderd.","kurz_en":"Het combineren van een caloriebeperkt dieet met 5-Amino-1MQ normaliseerde het lichaamsvetpercentage en gewicht sneller bij dieet-geïnduceerde obese muizen dan alleen een dieetverandering, terwijl ook de samenstelling van het darmmicrobioom werd veranderd.","quelle":"Scientific Reports 2022, PMID 35013352"}],"sicherheit":["In de studie van 2018 door Neelakantan et al. bij obese muizen veranderde de voedselinname niet onder 5-Amino-1MQ, wat in het dierlijke model een redelijke verdragsbaarheid over de studieperiode suggereert.","Er zijn geen gecontroleerde menselijke veiligheidsstudies op 5-Amino-1MQ bekend, alleen gegevens uit dierlijke modellen zijn beschikbaar.","Gestandaardiseerde pre-klinische toxicologiepakketten, zoals herhaalde meerweek toedieningsstudies in aanvullende soorten, zijn niet gepubliceerd voor 5-Amino-1MQ.","Interacties met andere stoffen of supplementen zijn niet systematisch onderzocht voor 5-Amino-1MQ."],"sicherheit_en":["In de studie van 2018 door Neelakantan et al. bij obese muizen veranderde de voedselinname niet onder 5-Amino-1MQ, wat in het dierlijke model een redelijke verdragsbaarheid over de studieperiode suggereert.","Er zijn geen gecontroleerde menselijke veiligheidsstudies op 5-Amino-1MQ bekend, alleen gegevens uit dierlijke modellen zijn beschikbaar.","Gestandaardiseerde pre-klinische toxicologiepakketten, zoals herhaalde meerweek toedieningsstudies in aanvullende soorten, zijn niet gepubliceerd voor 5-Amino-1MQ.","Interacties met andere stoffen of supplementen zijn niet systematisch onderzocht voor 5-Amino-1MQ."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"5-Amino-1MQ is niet goedgekeurd als medicijn in de EU of de Verenigde Staten en wordt uitsluitend verkocht als een chemische stof voor onderzoek. Er zijn geen menselijke goedkeuringsstudies bekend.","rechtsstatus_en":"5-Amino-1MQ is niet goedgekeurd als medicijn in de EU of de Verenigde Staten en wordt uitsluitend verkocht als een chemische stof voor onderzoek. Er zijn geen menselijke goedkeuringsstudies bekend.","typischeMg":[10,50],"faq":[{"q":"Is 5-Amino-1MQ een peptide?","a":"Nee. 5-Amino-1MQ is een kleine molecuul, geen peptide, en bestaat niet uit een aminozuurketen. Het wordt bestudeerd als een selectieve remmer van het NNMT enzym en wordt hier vermeld onder metabolisme gerelateerde verbindingen omdat het werkt op gerelateerde doelssystemen.","q_en":"Is 5-Amino-1MQ een peptide?","a_en":"Nee. 5-Amino-1MQ is een kleine molecuul, geen peptide, en bestaat niet uit een aminozuurketen. Het wordt bestudeerd als een selectieve remmer van het NNMT enzym en wordt hier vermeld onder metabolisme gerelateerde verbindingen omdat het werkt op gerelateerde doelssystemen."},{"q":"Zijn er menselijke studies over 5-Amino-1MQ?","a":"Nee, er zijn tot op heden geen gecontroleerde klinische studies bij mensen bekend. Alle gepubliceerde gegevens komen uit preklinisch onderzoek in muizen.","q_en":"Zijn er menselijke studies over 5-Amino-1MQ?","a_en":"Nee, er zijn tot op heden geen gecontroleerde klinische studies bij mensen bekend. Alle gepubliceerde gegevens komen uit preklinisch onderzoek in muizen."},{"q":"Waarom wordt NNMT bestudeerd in onderzoek?","a":"NNMT is een enzym actief in vetweefsel en spier dat nicotinamide afbreekt, een precursor van NAD+. Verhoogde NNMT niveaus zijn gekoppeld aan verminderde metabole activiteit in preklinische modellen, waardoor zijn remming wordt bestudeerd als een onderzoeksaanpak.","q_en":"Waarom wordt NNMT bestudeerd in onderzoek?","a_en":"NNMT is een enzym actief in vetweefsel en spier dat nicotinamide afbreekt, een precursor van NAD+. Verhoogde NNMT niveaus zijn gekoppeld aan verminderde metabole activiteit in preklinische modellen, waardoor zijn remming wordt bestudeerd als een onderzoeksaanpak."}],"seo":{"title":"5-Amino-1MQ: NNMT Remmer in Preklinisch Onderzoek","title_en":"5-Amino-1MQ: NNMT Remmer in Preklinisch Onderzoek","description":"5-Amino-1MQ overzicht: mechanisme, status preklinisch onderzoek en juridische status van de NNMT remmer, een kleine molecuul in plaats van een peptide.","description_en":"5-Amino-1MQ overzicht: mechanisme, status preklinisch onderzoek en juridische status van de NNMT remmer, een kleine molecuul in plaats van een peptide."},"demo":false,"steckbrief":{"cas":"685079-15-6","molekulargewicht":"159,21 g/mol","aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":null,"quellen":["PubChem CID 950107","chemverify Katalog 14.09.2026","kein Peptid, kleines Molekül ohne Aminosäuresequenz (NNMT-Inhibitor)"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["aod-9604","mots-c","tirzepatid"]},{"slug":"aod-9604","name":"AOD-9604","synonyme":["Anti-obesmiddel 9604","Tyr-hGH-fragment 177-191"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Een peptidefragment van menselijk groeihormoon (aminozuren 177-191) bestudeerd voor een vetreducerend effect zonder de groeibepalende effecten van het volledige hormoon.","kurz_en":"Een peptidefragment van menselijk groeihormoon (aminozuren 177-191) bestudeerd voor een vetreducerend effect zonder de groeibepalende effecten van het volledige hormoon.","beschreibung":"AOD-9604 is een synthetisch 16-aminozuurfragment van menselijk groeihormoon (sequentie Tyr-hGH177-191), oorspronkelijk ontwikkeld door Metabolic Pharmaceuticals in samenwerking met Monash University voor gewichtsregulatie. Het werd bestudeerd in zes gerandomiseerde, placebo-gecontroleerde menselijke proeven met meer dan 900 deelnemers voor zijn metabole effecten en veiligheid. Klinische ontwikkeling als obesitasmiddel werd in 2007 stopgezet nadat de grootste proef het primaire effectiviteitsdoel niet haalde.","beschreibung_en":"AOD-9604 is een synthetisch 16-aminozuurfragment van menselijk groeihormoon (sequentie Tyr-hGH177-191), oorspronkelijk ontwikkeld door Metabolic Pharmaceuticals in samenwerking met Monash University voor gewichtsregulatie. Het werd bestudeerd in zes gerandomiseerde, placebo-gecontroleerde menselijke proeven met meer dan 900 deelnemers voor zijn metabole effecten en veiligheid. Klinische ontwikkeling als obesitasmiddel werd in 2007 stopgezet nadat de grootste proef het primaire effectiviteitsdoel niet haalde.","mechanismus":"AOD-9604 omvat het lipolytische gebied (aminozuren 177-191) van het groeihormoonmolecuul, zonder het receptorbindende gebied verantwoordelijk voor de IGF-1 gemedieerde groei en metabole effecten van het volledige hGH. Preklinische modellen beschrijven een activatie van lipolyse via het boodschapper diacylglycerol en het enzym hormoongevoelige lipase, gemedieerd via de bèta-3 adrenerge receptor. In tegenstelling tot het volledige hGH beïnvloedde AOD-9604 IGF-1 niveaus of insulineresistentie niet in studies.","mechanismus_en":"AOD-9604 omvat het lipolytische gebied (aminozuren 177-191) van het groeihormoonmolecuul, zonder het receptorbindende gebied verantwoordelijk voor de IGF-1 gemedieerde groei en metabole effecten van het volledige hGH. Preklinische modellen beschrijven een activatie van lipolyse via het boodschapper diacylglycerol en het enzym hormoongevoelige lipase, gemedieerd via de bèta-3 adrenerge receptor. In tegenstelling tot het volledige hGH beïnvloedde AOD-9604 IGF-1 niveaus of insulineresistentie niet in studies.","evidenz":[{"art":"preklinisch","kurz":"In een preklinisch onderzoek bij obese Zucker ratten verminderde 19 dagen orale toediening van AOD-9604 de lichaamsgewichtsverhoging met meer dan 50 procent vergeleken met controlegroepen.","kurz_en":"In een preklinisch onderzoek bij obese Zucker ratten verminderde 19 dagen orale toediening van AOD-9604 de lichaamsgewichtsverhoging met meer dan 50 procent vergeleken met controlegroepen.","quelle":"Ng FM et al. 2000, Hormone Research 53(6):274-278, PMID 11146367"},{"art":"preklinisch","kurz":"Bij obese muizen verhoogde chronische toediening van AOD-9604 de vetoxidatie en lipolytische gevoeligheid via de beta-3 adrenerge receptorroute, vergelijkbaar met volledig hGH maar zonder invloed op insulinegevoeligheid.","kurz_en":"Bij obese muizen verhoogde chronische toediening van AOD-9604 de vetoxidatie en lipolytische gevoeligheid via de beta-3 adrenerge receptorroute, vergelijkbaar met volledig hGH maar zonder invloed op insulinegevoeligheid.","quelle":"Heffernan M et al. 2001, Endocrinology 142(12):5182-5189, PMID 11673763"},{"art":"klinisch","kurz":"In een gerandomiseerde, dubbelblinde, placebo-gecontroleerde multicenter studie bij 300 volwassenen met obesitas verloor de groep die 1 mg oraal dagelijks ontving gemiddeld 2,8 kg over 12 weken vergeleken met 0,8 kg onder placebo.","kurz_en":"In een gerandomiseerde, dubbelblinde, placebo-gecontroleerde multicenter studie bij 300 volwassenen met obesitas verloor de groep die 1 mg oraal dagelijks ontving gemiddeld 2,8 kg over 12 weken vergeleken met 0,8 kg onder placebo.","quelle":"Herd C et al. 2005, randomisierte Multicenter-Studie (Publikationsnachweis: ResearchGate ID 295313034 / University of Melbourne)"},{"art":"klinisch","kurz":"Een veiligheidsbeoordeling over zes gerandomiseerde, placebo-gecontroleerde menselijke proeven toonde geen toename in IGF-1 niveaus, geen ernstige bijwerkingen gerelateerd aan AOD-9604, en geen detecteerbare anti-AOD-9604 antilichamen.","kurz_en":"Een veiligheidsbeoordeling over zes gerandomiseerde, placebo-gecontroleerde menselijke proeven toonde geen toename in IGF-1 niveaus, geen ernstige bijwerkingen gerelateerd aan AOD-9604, en geen detecteerbare anti-AOD-9604 antilichamen.","quelle":"Stier H et al. 2013, Journal of Endocrinology and Metabolism 3(2), jofem.org"}],"sicherheit":["Over zes gerandomiseerde, placebo-gecontroleerde menselijke proeven traden er geen ernstige bijwerkingen gerelateerd aan AOD-9604 op, en gerapporteerde effecten waren minimaal en vluchtig.","In tegenstelling tot volledig hGH verhoogde AOD-9604 geen IGF-1 niveaus of beïnvloedde het de glucose-tolerantie in deze proeven.","Er werden geen antilichamen tegen AOD-9604 gedetecteerd in de proeven die immunogeniciteit testten.","De klinische ontwikkeling werd in 2007 stopgezet nadat de grotere fase 2b proef niet statistisch zijn primaire gewichtsverliesdoel bereikte ten opzichte van placebo, zonder dat er veiligheidzorgen als reden werden gerapporteerd.","Aangezien AOD-9604 nergens als medicijn is goedgekeurd, bestaat er geen officiële productinformatie over langetermijnveiligheid."],"sicherheit_en":["Over zes gerandomiseerde, placebo-gecontroleerde menselijke proeven traden er geen ernstige bijwerkingen gerelateerd aan AOD-9604 op, en gerapporteerde effecten waren minimaal en vluchtig.","In tegenstelling tot volledig hGH verhoogde AOD-9604 geen IGF-1 niveaus of beïnvloedde het de glucose-tolerantie in deze proeven.","Er werden geen antilichamen tegen AOD-9604 gedetecteerd in de proeven die immunogeniciteit testten.","De klinische ontwikkeling werd in 2007 stopgezet nadat de grotere fase 2b proef niet statistisch zijn primaire gewichtsverliesdoel bereikte ten opzichte van placebo, zonder dat er veiligheidzorgen als reden werden gerapporteerd.","Aangezien AOD-9604 nergens als medicijn is goedgekeurd, bestaat er geen officiële productinformatie over langetermijnveiligheid."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"AOD-9604 is niet goedgekeurd als medicijn in de EU of de Verenigde Staten. De klinische ontwikkeling als obesitasverbinding werd in 2007 stopgezet na een fase 2b proef. De stof wordt uitsluitend verkocht als een chemische stof voor onderzoek en staat op de WADA Verbodenlijst voor sport.","rechtsstatus_en":"AOD-9604 is niet goedgekeurd als medicijn in de EU of de Verenigde Staten. De klinische ontwikkeling als obesitasverbinding werd in 2007 stopgezet na een fase 2b proef. De stof wordt uitsluitend verkocht als een chemische stof voor onderzoek en staat op de WADA Verbodenlijst voor sport.","typischeMg":[2,5,10],"faq":[{"q":"Is AOD-9604 goedgekeurd als medicijn?","a":"Nee. AOD-9604 is onderzocht in zes klinische proeven, en de ontwikkeling als obesitasverbinding werd in 2007 stopgezet. Het is momenteel geen goedgekeurd medicijn en wordt alleen verkocht als een chemische stof voor onderzoek.","q_en":"Is AOD-9604 goedgekeurd als medicijn?","a_en":"Nee. AOD-9604 is onderzocht in zes klinische proeven, en de ontwikkeling als obesitasverbinding werd in 2007 stopgezet. Het is momenteel geen goedgekeurd medicijn en wordt alleen verkocht als een chemische stof voor onderzoek."},{"q":"Hoe verschilt AOD-9604 van volledig groeihormoon?","a":"AOD-9604 bevat alleen het lipolytische gebied van het hGH-molecuul (aminozuren 177-191), niet het gebied dat de IGF-1-gemedieerde groeieffecten triggert. In tegenstelling tot intact hGH toonde het geen effect op IGF-1 of insulinegevoeligheid in studies.","q_en":"Hoe verschilt AOD-9604 van volledig groeihormoon?","a_en":"AOD-9604 bevat alleen het lipolytische gebied van het hGH-molecuul (aminozuren 177-191), niet het gebied dat de IGF-1-gemedieerde groeieffecten triggert. In tegenstelling tot intact hGH toonde het geen effect op IGF-1 of insulinegevoeligheid in studies."},{"q":"Is AOD-9604 toegestaan in sport?","a":"Nee. AOD-9604 staat vermeld als een groeihormoonfragment op de WADA Verbodenlijst, en er is geen therapeutische gebruiksvrijstelling beschikbaar voor het.","q_en":"Is AOD-9604 toegestaan in sport?","a_en":"Nee. AOD-9604 staat vermeld als een groeihormoonfragment op de WADA Verbodenlijst, en er is geen therapeutische gebruiksvrijstelling beschikbaar voor het."}],"seo":{"title":"AOD-9604: hGH-fragment 177-191 in onderzoekscontext","title_en":"AOD-9604: hGH-fragment 177-191 in onderzoekscontext","description":"AOD-9604 overzicht: mechanisme, studiestatus en veiligheidsprofiel van het hGH fragment 177-191 bestudeerd in klinische proeven voor gewichtsregulatie.","description_en":"AOD-9604 overzicht: mechanisme, studiestatus en veiligheidsprofiel van het hGH fragment 177-191 bestudeerd in klinische proeven voor gewichtsregulatie."},"demo":false,"steckbrief":{"cas":"221231-10-3","molekulargewicht":"1815.1 g/mol","aminosaeuren":16,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":16,"quellen":["PubChem CID 71300630","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["tesamorelin","mots-c","5-amino-1mq"]},{"slug":"cagrilintid","name":"Cagrilintide","synonyme":["AM833","NN9838"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Een langwerkend analoog van het eigen hormoon amyline van het lichaam, bestudeerd in klinische proeven voor metabole en verzadigingsregulatie, alleen en in combinatie met semaglutide.","kurz_en":"Een langwerkend analoog van het eigen hormoon amyline van het lichaam, bestudeerd in klinische proeven voor metabole en verzadigingsregulatie, alleen en in combinatie met semaglutide.","beschreibung":"Cagrilintide is een langwerkend amyline analoog ontwikkeld door Novo Nordisk. Het wordt onderzocht zowel als een losstaand middel als in een vaste combinatie met het GLP-1-verbinding semaglutide, gepromoot onder de naam CagriSema, in fase 3 proeven. Tot op heden is cagrilintide niet goedgekeurd als losstaand medicijn in enig land.","beschreibung_en":"Cagrilintide is een langwerkend amyline analoog ontwikkeld door Novo Nordisk. Het wordt onderzocht zowel als een losstaand middel als in een vaste combinatie met het GLP-1-verbinding semaglutide, gepromoot onder de naam CagriSema, in fase 3 proeven. Tot op heden is cagrilintide niet goedgekeurd als losstaand medicijn in enig land.","mechanismus":"Cagrilintide bindt aan amyline receptoren in de hersenen, voornamelijk de AMY1 en AMY3 subtypes gevormd door de calcitonine receptor samen met accessoire RAMP eiwitten. Dit is gekoppeld aan vertraagde maaglediging, verminderde postprandiale glucagonafgifte en verzadigingssignaal in hersengebieden zoals de area postrema. Vetzuur lipidatie van de molecuul verlengt de duur van werking aanzienlijk in vergelijking met het natuurlijke hormoon amyline, waardoor een wekelijkse toediening in de proefomgeving mogelijk is.","mechanismus_en":"Cagrilintide bindt aan amyline receptoren in de hersenen, voornamelijk de AMY1 en AMY3 subtypes gevormd door de calcitonine receptor samen met accessoire RAMP eiwitten. Dit is gekoppeld aan vertraagde maaglediging, verminderde postprandiale glucagonafgifte en verzadigingssignaal in hersengebieden zoals de area postrema. Vetzuur lipidatie van de molecuul verlengt de duur van werking aanzienlijk in vergelijking met het natuurlijke hormoon amyline, waardoor een wekelijkse toediening in de proefomgeving mogelijk is.","evidenz":[{"art":"klinisch","kurz":"In een gerandomiseerde fase 2 proef waarbij verschillende hoeveelheden werden getest bij 706 volwassenen met overgewicht of obesitas, leidde cagrilintide alleen over 26 weken tot een gemiddelde lichaamsgewichtverlies van 10,8 procent bij de hoogste geteste hoeveelheid, vergeleken met ongeveer 3 procent onder placebo.","kurz_en":"In een gerandomiseerde fase 2 proef waarbij verschillende hoeveelheden werden getest bij 706 volwassenen met overgewicht of obesitas, leidde cagrilintide alleen over 26 weken tot een gemiddelde lichaamsgewichtverlies van 10,8 procent bij de hoogste geteste hoeveelheid, vergeleken met ongeveer 3 procent onder placebo.","quelle":"Lau DCW et al. 2021, The Lancet 398:2160-2172, PMID 34798060"},{"art":"klinisch","kurz":"In de fase 3 REDEFINE 1 proef bereikte de cagrilintide alleen arm met 2,4 mg wekelijks een lichaamsgewichtverlies van ongeveer 11,8 procent na 68 weken, vergeleken met 2,3 procent onder placebo.","kurz_en":"In de fase 3 REDEFINE 1 proef bereikte de cagrilintide alleen arm met 2,4 mg wekelijks een lichaamsgewichtverlies van ongeveer 11,8 procent na 68 weken, vergeleken met 2,3 procent onder placebo.","quelle":"Garvey WT et al. 2025, New England Journal of Medicine 393:625-638, PMID 40544433"},{"art":"preklinisch","kurz":"In een dieet-geïnduceerde obesitas-muismodel hing het lichaamsgewichtverlagende effect van cagrilintide af van de hersen amyline receptoren AMY1 en AMY3, en het effect was afwezig in receptor knockout dieren.","kurz_en":"In een dieet-geïnduceerde obesitas-muismodel hing het lichaamsgewichtverlagende effect van cagrilintide af van de hersen amyline receptoren AMY1 en AMY3, en het effect was afwezig in receptor knockout dieren.","quelle":"Carvas AO et al. 2025, eBioMedicine, PMID 40609154"},{"art":"preklinisch","kurz":"Structurele optimalisatie met vetzuur lipidatie gaf cagrilintide een aanzienlijk langere halfwaardetijd van ongeveer 159 tot 195 uur dan het eigen hormoon amyline van het lichaam, waardoor een wekelijkse toediening in de proefomgeving mogelijk is.","kurz_en":"Structurele optimalisatie met vetzuur lipidatie gaf cagrilintide een aanzienlijk langere halfwaardetijd van ongeveer 159 tot 195 uur dan het eigen hormoon amyline van het lichaam, waardoor een wekelijkse toediening in de proefomgeving mogelijk is.","quelle":"Kruse T et al. 2021, Journal of Medicinal Chemistry 64:11183-11194, PMID 34288673"}],"sicherheit":["In de gerandomiseerde fase 2 proef met cagrilintide als het enige middel, treden gastro-intestinale effecten op bij 41 tot 63 procent van de deelnemers, vergeleken met 32 procent onder placebo, meestal misselijkheid.","In de fase 1b combinatieproef met toenemende cagrilintide-hoeveelheden naast semaglutide werden gastro-intestinale effecten beschreven als de meest voorkomende categorie van bijwerkingen, met een over het algemeen beheersbaar veiligheidsprofiel.","Als amylinreceptoragonist is vertraagd maaglediging beschreven, een mechanisme dat ook bijdraagt aan gastro-intestinale effecten met GLP-1 verbindingen.","Aangezien cagrilintide niet goedgekeurd is als los medicijn overal, bestaat er geen officiële productinformatie over langetermijnveiligheid."],"sicherheit_en":["In de gerandomiseerde fase 2 proef met cagrilintide als het enige middel, treden gastro-intestinale effecten op bij 41 tot 63 procent van de deelnemers, vergeleken met 32 procent onder placebo, meestal misselijkheid.","In de fase 1b combinatieproef met toenemende cagrilintide-hoeveelheden naast semaglutide werden gastro-intestinale effecten beschreven als de meest voorkomende categorie van bijwerkingen, met een over het algemeen beheersbaar veiligheidsprofiel.","Als amylinreceptoragonist is vertraagd maaglediging beschreven, een mechanisme dat ook bijdraagt aan gastro-intestinale effecten met GLP-1 verbindingen.","Aangezien cagrilintide niet goedgekeurd is als los medicijn overal, bestaat er geen officiële productinformatie over langetermijnveiligheid."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Cagrilintide is momenteel in fase 3 proeven zowel als losse stof als in een vaste combinatie met semaglutide onder de naam CagriSema, en is nog niet goedgekeurd als medicijn in de EU of de Verenigde Staten. In december 2025 is een nieuw medicijnverzoek voor de CagriSema combinatie ingediend bij de US FDA, met een beslissing verwacht in 2026. Cagrilintide wordt uitsluitend verkocht als een chemische stof voor onderzoek.","rechtsstatus_en":"Cagrilintide is momenteel in fase 3 proeven zowel als losse stof als in een vaste combinatie met semaglutide onder de naam CagriSema, en is nog niet goedgekeurd als medicijn in de EU of de Verenigde Staten. In december 2025 is een nieuw medicijnverzoek voor de CagriSema combinatie ingediend bij de US FDA, met een beslissing verwacht in 2026. Cagrilintide wordt uitsluitend verkocht als een chemische stof voor onderzoek.","typischeMg":[5,10],"faq":[{"q":"Is cagrilintide al beschikbaar als medicijn?","a":"Nee. Cagrilintide wordt onderzocht als losse stof en in de CagriSema combinatie in fase 3 proeven. Een FDA goedkeuringsproces voor CagriSema is sinds december 2025 gaande. Cagrilintide is momenteel geen goedgekeurd medicijn.","q_en":"Is cagrilintide al beschikbaar als medicijn?","a_en":"Nee. Cagrilintide wordt onderzocht als losse stof en in de CagriSema combinatie in fase 3 proeven. Een FDA goedkeuringsproces voor CagriSema is sinds december 2025 gaande. Cagrilintide is momenteel geen goedgekeurd medicijn."},{"q":"Wat onderscheidt cagrilintide van semaglutide?","a":"Semaglutide werkt op de GLP-1 receptor, terwijl cagrilintide werkt op amylinreceptoren in de hersenen. Beide verbindingen worden ook onderzocht als een vaste combinatie genaamd CagriSema, die in proeven een grotere werking op lichaamsgewicht liet zien dan elke stof afzonderlijk.","q_en":"Wat onderscheidt cagrilintide van semaglutide?","a_en":"Semaglutide werkt op de GLP-1 receptor, terwijl cagrilintide werkt op amylinreceptoren in de hersenen. Beide verbindingen worden ook onderzocht als een vaste combinatie genaamd CagriSema, die in proeven een grotere werking op lichaamsgewicht liet zien dan elke stof afzonderlijk."},{"q":"Waar komt cagrilintide vandaan?","a":"Cagrilintide is ontwikkeld door het farmaceutische bedrijf Novo Nordisk, dat ook semaglutide heeft ontwikkeld. Het wordt in klinische proeven aangeduid met de korte benamingen AM833 en NN9838, inclusief het REDEFINE proevenprogramma.","q_en":"Waar komt cagrilintide vandaan?","a_en":"Cagrilintide is ontwikkeld door het farmaceutische bedrijf Novo Nordisk, dat ook semaglutide heeft ontwikkeld. Het wordt in klinische proeven aangeduid met de korte benamingen AM833 en NN9838, inclusief het REDEFINE proevenprogramma."}],"seo":{"title":"Cagrilintide: Amylin Analoog in Fase 3 Proeven","title_en":"Cagrilintide: Amylin Analoog in Fase 3 Proeven","description":"Cagrilintide overzicht: mechanisme, studiestatus en veiligheidsprofiel van het amylin analoog, onderzocht alleen en in de CagriSema combinatie.","description_en":"Cagrilintide overzicht: mechanisme, studiestatus en veiligheidsprofiel van het amylin analoog, onderzocht alleen en in de CagriSema combinatie."},"demo":false,"steckbrief":{"cas":"1415456-99-3","molekulargewicht":"4409 g/mol","aminosaeuren":37,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":37,"quellen":["PubChem CID 171397054","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["semaglutid","tirzepatid","retatrutid","survodutid"]},{"slug":"mots-c","name":"MOTS-c","synonyme":["Mitochondriaal Afgeleid Peptide MOTS-c","Mitochondriaal Open Reading Frame van de 12S rRNA Type-c"],"kategorie":"Stoffwechsel","studienlage":"frühe klinische Studien","kurz":"Een mitochondriaal gecodeerd peptide dat wordt onderzocht als inspanningsmimeticum in metabool onderzoek.","kurz_en":"Een mitochondriaal gecodeerd peptide dat wordt onderzocht als inspanningsmimeticum in metabool onderzoek.","beschreibung":"MOTS-c is een 16-aminozuurpeptide gecodeerd in het mitochondriale DNA in plaats van in de celkern. Het werd ontdekt in 2015 en wordt onderzocht als een endogeen signaalmolecuul dat in grotere hoeveelheden vrijkomt tijdens fysieke inspanning. Onderzoek richt zich op mogelijke effecten op insulinegevoeligheid, vetmetabolisme en cellulaire veroudering.","beschreibung_en":"MOTS-c is een 16-aminozuurpeptide gecodeerd in het mitochondriale DNA in plaats van in de celkern. Het werd ontdekt in 2015 en wordt onderzocht als een endogeen signaalmolecuul dat in grotere hoeveelheden vrijkomt tijdens fysieke inspanning. Onderzoek richt zich op mogelijke effecten op insulinegevoeligheid, vetmetabolisme en cellulaire veroudering.","mechanismus":"MOTS-c inhibeert de foliumcyclus van de cel, waardoor het boodschappermolecuul AICAR zich ophoopt en de centrale energie-sensor AMPK activeert. Deze route stimuleert, onder andere, glucoseopname in spiercellen en vetzuuroxidatie. Onder metabole stress gaat MOTS-c ook naar de celkern, waar het de expressie van genen beïnvloedt die betrokken zijn bij stressadaptatie.","mechanismus_en":"MOTS-c inhibeert de foliumcyclus van de cel, waardoor het boodschappermolecuul AICAR zich ophoopt en de centrale energie-sensor AMPK activeert. Deze route stimuleert, onder andere, glucoseopname in spiercellen en vetzuuroxidatie. Onder metabole stress gaat MOTS-c ook naar de celkern, waar het de expressie van genen beïnvloedt die betrokken zijn bij stressadaptatie.","evidenz":[{"art":"preklinisch","kurz":"In de oorspronkelijke beschrijving voorkwam MOTS-c het ontwikkelen van insulineresistentie bij muizen op een hoogvetdieet gedurende enkele weken en herstelde de insulinegevoeligheid van jonge dieren in oude muizen.","kurz_en":"In de oorspronkelijke beschrijving voorkwam MOTS-c het ontwikkelen van insulineresistentie bij muizen op een hoogvetdieet gedurende enkele weken en herstelde de insulinegevoeligheid van jonge dieren in oude muizen.","quelle":"Lee et al. 2015, Cell Metabolism 21(3):443-454"},{"art":"preklinisch","kurz":"Bij oudere muizen verlengde herhaalde toediening van MOTS-c over enkele weken de mediane levensduur met 5 tot 7 procent en verbeterde de uithoudingsvermogen, gripkracht en balans vergeleken met placebo.","kurz_en":"Bij oudere muizen verlengde herhaalde toediening van MOTS-c over enkele weken de mediane levensduur met 5 tot 7 procent en verbeterde de uithoudingsvermogen, gripkracht en balans vergeleken met placebo.","quelle":"Reynolds et al. 2021, Nature Communications, DOI 10.1038/s41467-020-20790-0"},{"art":"klinisch","kurz":"In een observationeel onderzoek van 20 fysiek actieve volwassenen correleerden serum MOTS-c niveaus positief met sprongkracht, maximale kracht en spiermassa van de benen, maar niet met maximale zuurstofopname.","kurz_en":"In een observationeel onderzoek van 20 fysiek actieve volwassenen correleerden serum MOTS-c niveaus positief met sprongkracht, maximale kracht en spiermassa van de benen, maar niet met maximale zuurstofopname.","quelle":"Domin et al. 2023, International Journal of Molecular Sciences"}],"sicherheit":["Gepubliceerde dierstudies tot zes maanden lieten geen relevante bijwerkingen zien.","Het meest voorkomende gerapporteerde effect is een lokale injectieplaatsreactie zoals branden en roodheid.","MOTS-c inhibeert de foliumcyclus; een mogelijke foliumtekort bij langere gebruik is tot nu toe alleen theoretisch beschreven.","Gecontroleerde menselijke interventietrials naar effectiviteit en veiligheid zijn nog niet beschikbaar."],"sicherheit_en":["Gepubliceerde dierstudies tot zes maanden lieten geen relevante bijwerkingen zien.","Het meest voorkomende gerapporteerde effect is een lokale injectieplaatsreactie zoals branden en roodheid.","MOTS-c inhibeert de foliumcyclus; een mogelijke foliumtekort bij langere gebruik is tot nu toe alleen theoretisch beschreven.","Gecontroleerde menselijke interventietrials naar effectiviteit en veiligheid zijn nog niet beschikbaar."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"MOTS-c is niet goedgekeurd als medicijn of voedingsproduct in de EU of de VS. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek en is niet bedoeld voor menselijk gebruik.","rechtsstatus_en":"MOTS-c is niet goedgekeurd als medicijn of voedingsproduct in de EU of de VS. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek en is niet bedoeld voor menselijk gebruik.","typischeMg":[5,10],"faq":[{"q":"Wat MOTS-c anders maakt dan andere peptiden","a":"MOTS-c is direct gecodeerd in mitochondriale DNA in plaats van in de celkern. Het werkt via de cellulaire energie-sensor AMPK en wordt daarom geclassificeerd als een inspanningsmimeticum.","q_en":"Wat MOTS-c anders maakt dan andere peptiden","a_en":"MOTS-c is direct gecodeerd in mitochondriale DNA in plaats van in de celkern. Het werkt via de cellulaire energie-sensor AMPK en wordt daarom geclassificeerd als een inspanningsmimeticum."},{"q":"Is MOTS-c een goedgekeurd medicijn","a":"Nee. MOTS-c is niet goedgekeurd als medicijn of voedingsproduct in de EU of de VS en wordt uitsluitend verkocht als een chemische stof voor onderzoek.","q_en":"Is MOTS-c een goedgekeurd medicijn","a_en":"Nee. MOTS-c is niet goedgekeurd als medicijn of voedingsproduct in de EU of de VS en wordt uitsluitend verkocht als een chemische stof voor onderzoek."},{"q":"Hoe robuust is de menselijke data over MOTS-c","a":"Beperkt tot nu toe. Het bewijs bestaat voornamelijk uit preklinische dierstudies en één menselijk observationeel onderzoek naar correlatie met spierkracht; gecontroleerde menselijke interventietrials ontbreken nog.","q_en":"Hoe robuust is de menselijke data over MOTS-c","a_en":"Beperkt tot nu toe. Het bewijs bestaat voornamelijk uit preklinische dierstudies en één menselijk observationeel onderzoek naar correlatie met spierkracht; gecontroleerde menselijke interventietrials ontbreken nog."}],"seo":{"title":"Onderzoeksoverzicht van MOTS-c","title_en":"Onderzoeksoverzicht van MOTS-c","description":"MOTS-c feitelijk uitgelegd: mitochondriale werkingsmechanisme, preklinische en klinische studiegegevens en de juridische status van het peptide.","description_en":"MOTS-c feitelijk uitgelegd: mitochondriale werkingsmechanisme, preklinische en klinische studiegegevens en de juridische status van het peptide."},"demo":false,"steckbrief":{"cas":"1627580-64-6","molekulargewicht":"2174.6 g/mol","aminosaeuren":16,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":16,"quellen":["PubChem CID 146675088","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["semaglutid","ss-31","aod-9604","5-amino-1mq"]},{"slug":"retatrutid","name":"Retatrutide","synonyme":["LY3437943"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Een peptide dat tegelijkertijd op GLP-1, GIP en glucagonreceptoren werkt, momenteel in gevorderde klinische proeven met betrekking tot metabole regulatie.","kurz_en":"Een peptide dat tegelijkertijd op GLP-1, GIP en glucagonreceptoren werkt, momenteel in gevorderde klinische proeven met betrekking tot metabole regulatie.","beschreibung":"Retatrutide is een zogeheten drievoudige agonist die gelijktijdig op drie metabole receptoren werkt: GLP-1, GIP en glucagon. Het bevindt zich momenteel in fase 3-onderzoek en is tot op heden in geen enkel land goedgekeurd als geneesmiddel.","beschreibung_en":"Retatrutide is een zogeheten drievoudige agonist die gelijktijdig op drie metabole receptoren werkt: GLP-1, GIP en glucagon. Het bevindt zich momenteel in fase 3-onderzoek en is tot op heden in geen enkel land goedgekeurd als geneesmiddel.","mechanismus":"Via de GLP-1 receptor zijn effecten op verzadigingsregulatie en vertraagde maaglediging beschreven. De GIP receptor is gekoppeld aan verhoogde insulinesecretie en een mogelijke buffering van gastro-intestinale effecten. De aanvullende werking op de glucagon receptor is geassocieerd met verhoogde hepatische energieverbranding en activatie van bruin vetweefsel.","mechanismus_en":"Via de GLP-1 receptor zijn effecten op verzadigingsregulatie en vertraagde maaglediging beschreven. De GIP receptor is gekoppeld aan verhoogde insulinesecretie en een mogelijke buffering van gastro-intestinale effecten. De aanvullende werking op de glucagon receptor is geassocieerd met verhoogde hepatische energieverbranding en activatie van bruin vetweefsel.","evidenz":[{"art":"klinisch","kurz":"In een gerandomiseerde fase 2 proef bij volwassenen met obesitas bereikten een merkbaar hoger percentage deelnemers op retatrutide relevante gewichtsafname na 48 weken vergeleken met placebo.","kurz_en":"In een gerandomiseerde fase 2 proef bij volwassenen met obesitas bereikten een merkbaar hoger percentage deelnemers op retatrutide relevante gewichtsafname na 48 weken vergeleken met placebo.","quelle":"Jastreboff AM et al. 2023, New England Journal of Medicine 389:514-526, PMID 37366315"},{"art":"klinisch","kurz":"In een substudy met deelnemers met gelijktijdige vetleverziekte werd een MRI-gemeten vermindering van vetinhoud in de lever die toenam met de toegediende hoeveelheid waargenomen na 24 weken.","kurz_en":"In een substudy met deelnemers met gelijktijdige vetleverziekte werd een MRI-gemeten vermindering van vetinhoud in de lever die toenam met de toegediende hoeveelheid waargenomen na 24 weken.","quelle":"Sanyal AJ et al. 2024, Nature Medicine"},{"art":"klinisch","kurz":"In een fase 2-studie bij mensen met type 2-diabetes verlaagde retatrutide de HbA1c-waarde meer dan het actieve vergelijkingsmiddel dulaglutide, naast een groter gewichtsverlies.","kurz_en":"In een fase 2-studie bij mensen met type 2-diabetes verlaagde retatrutide de HbA1c-waarde meer dan het actieve vergelijkingsmiddel dulaglutide, naast een groter gewichtsverlies.","quelle":"Rosenstock J et al. 2023, The Lancet 402:529-544, PMID 37385280"}],"sicherheit":["De meest voorkomend gerapporteerde effecten in proeven zijn gastro-intestinaal, waaronder misselijkheid en diarree, en nemen af gedurende de studies.","Bij de hogere hoeveelheid observeerden proeven een hoger uitvalpercentage vergeleken met placebo.","In een fase 3 proef rapporteerden sommige deelnemers in de groep met de hogere hoeveelheid dysesthesie (tintelingen of gevoelloosheid in de ledematen), die voornamelijk oploste gedurende de studie.","Aangezien retatrutide niet goedgekeurd is als medicijn in enig land, bestaat er geen officiële productinformatie over langetermijnveiligheid."],"sicherheit_en":["De meest voorkomend gerapporteerde effecten in proeven zijn gastro-intestinaal, waaronder misselijkheid en diarree, en nemen af gedurende de studies.","Bij de hogere hoeveelheid observeerden proeven een hoger uitvalpercentage vergeleken met placebo.","In een fase 3 proef rapporteerden sommige deelnemers in de groep met de hogere hoeveelheid dysesthesie (tintelingen of gevoelloosheid in de ledematen), die voornamelijk oploste gedurende de studie.","Aangezien retatrutide niet goedgekeurd is als medicijn in enig land, bestaat er geen officiële productinformatie over langetermijnveiligheid."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Retatrutide is momenteel in fase 3 proeven en is nog niet goedgekeurd als medicijn in de EU of de Verenigde Staten. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek.","rechtsstatus_en":"Retatrutide is momenteel in fase 3 proeven en is nog niet goedgekeurd als medicijn in de EU of de Verenigde Staten. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek.","typischeMg":[5,10,15],"faq":[{"q":"Is retatrutide al beschikbaar als medicijn?","a":"Nee. Retatrutide bevindt zich momenteel in fase 3-onderzoek; volgens de fabrikant wordt goedkeuring op zijn vroegst in 2027 verwacht. Het is momenteel geen goedgekeurd geneesmiddel.","q_en":"Is retatrutide al beschikbaar als medicijn?","a_en":"Nee. Retatrutide bevindt zich momenteel in fase 3-onderzoek; volgens de fabrikant wordt goedkeuring op zijn vroegst in 2027 verwacht. Het is momenteel geen goedgekeurd geneesmiddel."},{"q":"Wat onderscheidt retatrutide van semaglutide?","a":"Semaglutide werkt alleen op de GLP-1 receptor, terwijl retatrutide additioneel werkt op de GIP en glucagon receptoren. Klinische proeven toonden een groter effect op lichaamsgewicht en levervet als gevolg daarvan.","q_en":"Wat onderscheidt retatrutide van semaglutide?","a_en":"Semaglutide werkt alleen op de GLP-1 receptor, terwijl retatrutide additioneel werkt op de GIP en glucagon receptoren. Klinische proeven toonden een groter effect op lichaamsgewicht en levervet als gevolg daarvan."},{"q":"Waar komt retatrutide vandaan?","a":"Retatrutide is ontwikkeld door het farmaceutische bedrijf Eli Lilly en wordt onder de naam TRIUMPH in verschillende fase 3 proeven bestudeerd.","q_en":"Waar komt retatrutide vandaan?","a_en":"Retatrutide is ontwikkeld door het farmaceutische bedrijf Eli Lilly en wordt onder de naam TRIUMPH in verschillende fase 3 proeven bestudeerd."}],"seo":{"title":"Retatrutide: Triple Agonist in Fase 3 Proeven","title_en":"Retatrutide: Triple Agonist in Fase 3 Proeven","description":"Retatrutide overzicht: mechanisme, studiestatus en veiligheidsprofiel van de GLP-1/GIP/glucagon triple agonist in geavanceerde klinische proeven.","description_en":"Retatrutide overzicht: mechanisme, studiestatus en veiligheidsprofiel van de GLP-1/GIP/glucagon triple agonist in geavanceerde klinische proeven."},"demo":false,"steckbrief":{"cas":"2381989-03-1","molekulargewicht":"~4600 g/mol","aminosaeuren":39,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":"oplosbaar in steriele water of bacteriostatisch water","sequenzLaenge":39,"quellen":["chemverify Katalog 14.09.2026 (PubChem: kein Eintrag)"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit_en":"oplosbaar in steriele water of bacteriostatisch water"},"verwandt":["semaglutid","tirzepatid","cagrilintid","survodutid"]},{"slug":"semaglutid","name":"Semaglutide","synonyme":[],"kategorie":"Stoffwechsel","studienlage":"zugelassenes Arzneimittel","kurz":"Een GLP-1-receptoragonist, bekend als goedgekeurd geneesmiddel en hier opgenomen als onderzoeksstof voor metabole regulatie.","kurz_en":"Een GLP-1-receptoragonist, bekend als goedgekeurd geneesmiddel en hier opgenomen als onderzoeksstof voor metabole regulatie.","beschreibung":"Semaglutide is een GLP-1-receptoragonist die onder verschillende merknamen als geneesmiddel is goedgekeurd. Het is onderwerp van uitgebreid klinisch onderzoek naar de regulatie van metabolisme en verzadiging. De hier vermelde onderzoeksbatches zijn niet gelijk te stellen met goedgekeurde geneesmiddelen en zijn uitsluitend bedoeld voor laboratoriumgebruik.","beschreibung_en":"Semaglutide is een GLP-1-receptoragonist die onder verschillende merknamen als geneesmiddel is goedgekeurd. Het is onderwerp van uitgebreid klinisch onderzoek naar de regulatie van metabolisme en verzadiging. De hier vermelde onderzoeksbatches zijn niet gelijk te stellen met goedgekeurde geneesmiddelen en zijn uitsluitend bedoeld voor laboratoriumgebruik.","mechanismus":"Semaglutide activeert de GLP-1 receptor, die de hongerregulatie in de hypothalamus beïnvloedt, de maaglediging vertraagt en de insulineafgifte op een glucoseafhankelijke manier stimuleert. Deze glucoseafhankelijke werking wordt beschreven als de reden voor het lagere hypoglycemie risico in vergelijking met insuline.","mechanismus_en":"Semaglutide activeert de GLP-1 receptor, die de hongerregulatie in de hypothalamus beïnvloedt, de maaglediging vertraagt en de insulineafgifte op een glucoseafhankelijke manier stimuleert. Deze glucoseafhankelijke werking wordt beschreven als de reden voor het lagere hypoglycemie risico in vergelijking met insuline.","evidenz":[{"art":"klinisch","kurz":"In een gerandomiseerde studie met 1.961 volwassenen met overgewicht of obesitas leidde wekelijks semaglutide gedurende 68 weken tot een gemiddeld gewichtsverlies van 14,9 procent, tegenover 2,4 procent onder placebo.","kurz_en":"In een gerandomiseerde studie met 1.961 volwassenen met overgewicht of obesitas leidde wekelijks semaglutide gedurende 68 weken tot een gemiddeld gewichtsverlies van 14,9 procent, tegenover 2,4 procent onder placebo.","quelle":"Wilding JPH et al. 2021, New England Journal of Medicine, PMID 33567185"},{"art":"klinisch","kurz":"In een onderzoek naar cardiovasculaire uitkomsten bij 3.297 mensen met type 2-diabetes en een verhoogd cardiovasculair risico werd semaglutide geassocieerd met een 26 % lager aantal ernstige cardiovasculaire gebeurtenissen vergeleken met placebo.","kurz_en":"In een onderzoek naar cardiovasculaire uitkomsten bij 3.297 mensen met type 2-diabetes en een verhoogd cardiovasculair risico werd semaglutide geassocieerd met een 26 % lager aantal ernstige cardiovasculaire gebeurtenissen vergeleken met placebo.","quelle":"Marso SP et al. 2016, New England Journal of Medicine 375:1834-1844, PMID 27633186"}],"sicherheit":["Vaak gerapporteerde effecten zijn gastro-intestinaal, met name misselijkheid, diarree en braken, voornamelijk tijdelijk gedurende het gebruik.","Zeldzame gevallen besproken in de literatuur omvatten een mogelijke link met niet arteriitische anterieure ischemische optische neuropathie.","Volgens de productinformatie is gebruik contra-indiceerd bij personen met een persoonlijke of familiegeschiedenis van medullair schildcarcinoom."],"sicherheit_en":["Vaak gerapporteerde effecten zijn gastro-intestinaal, met name misselijkheid, diarree en braken, voornamelijk tijdelijk gedurende het gebruik.","Zeldzame gevallen besproken in de literatuur omvatten een mogelijke link met niet arteriitische anterieure ischemische optische neuropathie.","Volgens de productinformatie is gebruik contra-indiceerd bij personen met een persoonlijke of familiegeschiedenis van medullair schildcarcinoom."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Semaglutide is goedgekeurd als medicijn onder de namen Ozempic, Wegovy en Rybelsus in de EU en de Verenigde Staten voor de behandeling van type 2 diabetes en voor gewichtsbeheersing, en is alleen op recept verkrijgbaar. De hier beschreven onderzoeksbatches zijn niet equivalent aan de goedgekeurde eindproducten.","rechtsstatus_en":"Semaglutide is goedgekeurd als medicijn onder de namen Ozempic, Wegovy en Rybelsus in de EU en de Verenigde Staten voor de behandeling van type 2 diabetes en voor gewichtsbeheersing, en is alleen op recept verkrijgbaar. De hier beschreven onderzoeksbatches zijn niet equivalent aan de goedgekeurde eindproducten.","typischeMg":[2,5],"faq":[{"q":"Is semaglutide een goedgekeurd medicijn?","a":"Ja, semaglutide is goedgekeurd als receptplichtig geneesmiddel onder de namen Ozempic, Wegovy en Rybelsus. De hier beschreven stof is uitsluitend een onderzoeksbatch en geen afgewerkt farmaceutisch product.","q_en":"Is semaglutide een goedgekeurd medicijn?","a_en":"Ja, semaglutide is goedgekeurd als receptplichtig geneesmiddel onder de namen Ozempic, Wegovy en Rybelsus. De hier beschreven stof is uitsluitend een onderzoeksbatch en geen afgewerkt farmaceutisch product."},{"q":"Hoe verschilt semaglutide van retatrutide?","a":"Semaglutide werkt alleen op de GLP-1 receptor, terwijl retatrutide additioneel werkt op de GIP en glucagon receptoren. Retatrutide is ook nog in fase 3 proeven, terwijl semaglutide al goedgekeurd is.","q_en":"Hoe verschilt semaglutide van retatrutide?","a_en":"Semaglutide werkt alleen op de GLP-1 receptor, terwijl retatrutide additioneel werkt op de GIP en glucagon receptoren. Retatrutide is ook nog in fase 3 proeven, terwijl semaglutide al goedgekeurd is."},{"q":"Waarvoor wordt semaglutide gebruikt als medicijn?","a":"Als goedgekeurd geneesmiddel wordt semaglutide voorgeschreven bij type 2-diabetes en gewichtsbeheersing. Deze pagina beschrijft de stof uitsluitend als onderzoekschemicalie voor laboratoriumdoeleinden.","q_en":"Waarvoor wordt semaglutide gebruikt als medicijn?","a_en":"Als goedgekeurd geneesmiddel wordt semaglutide voorgeschreven bij type 2-diabetes en gewichtsbeheersing. Deze pagina beschrijft de stof uitsluitend als onderzoekschemicalie voor laboratoriumdoeleinden."}],"seo":{"title":"Semaglutide: GLP-1 Compound in een Onderzoekscontext","title_en":"Semaglutide: GLP-1 Compound in een Onderzoekscontext","description":"Semaglutide in één oogopslag: mechanisme, studiestatus, veiligheidsprofiel en wettelijk status van de goedgekeurde GLP-1 receptor agonist.","description_en":"Semaglutide in één oogopslag: mechanisme, studiestatus, veiligheidsprofiel en wettelijk status van de goedgekeurde GLP-1 receptor agonist."},"demo":false,"steckbrief":{"cas":"910463-68-2","molekulargewicht":"4114 g/mol","aminosaeuren":31,"halbwertszeit":"≈ 1 week (eliminatie, productinformatie Ozempic)","reinheitsstandard":"≥ 99 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":31,"quellen":["PubChem CID 56843331","DailyMed SPL OZEMPIC (Semaglutid), Novo Nordisk","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 1 week (eliminatie, productinformatie Ozempic)","reinheitsstandard_en":"≥ 99 % (HPLC, commercieel standaard)"},"verwandt":["tirzepatid","retatrutid","survodutid","cagrilintid"]},{"slug":"survodutid","name":"Survodutide","synonyme":["BI 456906"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Een peptide dat zowel op GLP-1 als glucagon receptoren tegelijkertijd werkt, momenteel in gevorderde klinische proeven met betrekking tot metabole regulatie.","kurz_en":"Een peptide dat zowel op GLP-1 als glucagon receptoren tegelijkertijd werkt, momenteel in gevorderde klinische proeven met betrekking tot metabole regulatie.","beschreibung":"Survodutide is een dubbele agonist op GLP-1 en glucagon receptoren, ontwikkeld door Boehringer Ingelheim in samenwerking met Zealand Pharma. Het wordt onderzocht in fase 3 proeven voor gewichtsregulatie bij obesitas evenals bij metabole disfunctie geassocieerde steatohepatitis (MASH), en is tot op heden niet goedgekeurd als medicijn in enig land.","beschreibung_en":"Survodutide is een dubbele agonist op GLP-1 en glucagon receptoren, ontwikkeld door Boehringer Ingelheim in samenwerking met Zealand Pharma. Het wordt onderzocht in fase 3 proeven voor gewichtsregulatie bij obesitas evenals bij metabole disfunctie geassocieerde steatohepatitis (MASH), en is tot op heden niet goedgekeurd als medicijn in enig land.","mechanismus":"Via de GLP-1 receptor zijn toename van verzadiging en vertraagde maaglediging beschreven. De additionele activatie van de glucagon receptor is gekoppeld aan verhoogde hepatische energieverbruik en een vermindering van de vetinhoud in de lever. Deze dubbele werking onderscheidt survodutide van pure GLP-1 agonisten.","mechanismus_en":"Via de GLP-1 receptor zijn toename van verzadiging en vertraagde maaglediging beschreven. De additionele activatie van de glucagon receptor is gekoppeld aan verhoogde hepatische energieverbruik en een vermindering van de vetinhoud in de lever. Deze dubbele werking onderscheidt survodutide van pure GLP-1 agonisten.","evidenz":[{"art":"klinisch","kurz":"In een gerandomiseerde fase 3 proef met 725 volwassenen met obesitas zonder diabetes leidde survodutide tot een gemiddeld gewichtsverlies van 12 tot 13 procent na 76 weken, vergeleken met 5 procent onder placebo.","kurz_en":"In een gerandomiseerde fase 3 proef met 725 volwassenen met obesitas zonder diabetes leidde survodutide tot een gemiddeld gewichtsverlies van 12 tot 13 procent na 76 weken, vergeleken met 5 procent onder placebo.","quelle":"Le Roux CW et al. 2026, New England Journal of Medicine, DOI 10.1056/NEJMoa2600751"},{"art":"klinisch","kurz":"In een gerandomiseerd fase 2 proef met 386 volwassenen met obesitas leidde survodutide tot een lichaamsgewichtverlies van tot 14,9 procent in de groep met de hoogste hoeveelheid na 46 weken, vergeleken met 2,8 procent onder placebo.","kurz_en":"In een gerandomiseerd fase 2 proef met 386 volwassenen met obesitas leidde survodutide tot een lichaamsgewichtverlies van tot 14,9 procent in de groep met de hoogste hoeveelheid na 46 weken, vergeleken met 2,8 procent onder placebo.","quelle":"le Roux CW et al. 2024, The Lancet Diabetes & Endocrinology 12:162-173, PMID 38330987"},{"art":"klinisch","kurz":"In een fase 2 proef met 293 personen met MASH en leverfibrose toonde tot 62 procent van de deelnemers op survodutide een histologische verbetering van MASH zonder verslechtering van de fibrose na 48 weken, vergeleken met 14 procent onder placebo.","kurz_en":"In een fase 2 proef met 293 personen met MASH en leverfibrose toonde tot 62 procent van de deelnemers op survodutide een histologische verbetering van MASH zonder verslechtering van de fibrose na 48 weken, vergeleken met 14 procent onder placebo.","quelle":"Sanyal AJ et al. 2024, New England Journal of Medicine, PMID 38847460"}],"sicherheit":["De meest gerapporteerde effecten in proeven zijn gastro-intestinaal, waaronder misselijkheid, diarree en braken, die veel vaker voorkomen onder survodutide dan onder placebo.","In de fase 3 obesitasproef werden gastro-intestinale symptomen gerapporteerd bij tot 90 procent van de deelnemers op survodutide versus 48 procent onder placebo, voornamelijk mild tot matig.","In de fase 2 MASH proef werden ernstige bijwerkingen geregistreerd bij 8 procent van de deelnemers op survodutide en 7 procent onder placebo.","Aangezien survodutide niet als medicijn is goedgekeurd op enige plek, bestaat er geen officiële productinformatie over langetermijnveiligheid."],"sicherheit_en":["De meest gerapporteerde effecten in proeven zijn gastro-intestinaal, waaronder misselijkheid, diarree en braken, die veel vaker voorkomen onder survodutide dan onder placebo.","In de fase 3 obesitasproef werden gastro-intestinale symptomen gerapporteerd bij tot 90 procent van de deelnemers op survodutide versus 48 procent onder placebo, voornamelijk mild tot matig.","In de fase 2 MASH proef werden ernstige bijwerkingen geregistreerd bij 8 procent van de deelnemers op survodutide en 7 procent onder placebo.","Aangezien survodutide niet als medicijn is goedgekeurd op enige plek, bestaat er geen officiële productinformatie over langetermijnveiligheid."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Survodutide bevindt zich momenteel in fase 3-onderzoek voor obesitas en MASH en is in de EU en de Verenigde Staten nog niet als geneesmiddel goedgekeurd. Volgens de fabrikant wordt FDA-goedkeuring op zijn vroegst in 2027 verwacht; het wordt uitsluitend als onderzoekschemicalie verkocht.","rechtsstatus_en":"Survodutide bevindt zich momenteel in fase 3-onderzoek voor obesitas en MASH en is in de EU en de Verenigde Staten nog niet als geneesmiddel goedgekeurd. Volgens de fabrikant wordt FDA-goedkeuring op zijn vroegst in 2027 verwacht; het wordt uitsluitend als onderzoekschemicalie verkocht.","typischeMg":[5,10,20],"faq":[{"q":"Is survodutide al beschikbaar als medicijn?","a":"Nee. Survodutide bevindt zich momenteel in fase 3-onderzoek; volgens de fabrikant wordt FDA-goedkeuring op zijn vroegst in 2027 verwacht. Het is momenteel geen goedgekeurd geneesmiddel.","q_en":"Is survodutide al beschikbaar als medicijn?","a_en":"Nee. Survodutide bevindt zich momenteel in fase 3-onderzoek; volgens de fabrikant wordt FDA-goedkeuring op zijn vroegst in 2027 verwacht. Het is momenteel geen goedgekeurd geneesmiddel."},{"q":"Wat onderscheidt survodutide van semaglutide?","a":"Semaglutide werkt alleen op de GLP-1 receptor, terwijl survodutide additioneel werkt op de glucagon receptor. Klinische proeven toonden aan dat deze dubbele werking ook de levervetinhoud vermindert naast het effect op lichaamsgewicht.","q_en":"Wat onderscheidt survodutide van semaglutide?","a_en":"Semaglutide werkt alleen op de GLP-1 receptor, terwijl survodutide additioneel werkt op de glucagon receptor. Klinische proeven toonden aan dat deze dubbele werking ook de levervetinhoud vermindert naast het effect op lichaamsgewicht."},{"q":"Waar komt survodutide vandaan?","a":"Survodutide is ontwikkeld door het farmaceutische bedrijf Boehringer Ingelheim en wordt onderzocht in verschillende fase 3 proeven onder de programma naam SYNCHRONIZE, gedeeltelijk in samenwerking met Zealand Pharma.","q_en":"Waar komt survodutide vandaan?","a_en":"Survodutide is ontwikkeld door het farmaceutische bedrijf Boehringer Ingelheim en wordt onderzocht in verschillende fase 3 proeven onder de programma naam SYNCHRONIZE, gedeeltelijk in samenwerking met Zealand Pharma."}],"seo":{"title":"Survodutide: Dubbele Agonist in Fase 3 Proeven","title_en":"Survodutide: Dubbele Agonist in Fase 3 Proeven","description":"Survodutide overzicht: mechanisme, studiestatus en veiligheidsprofiel van de GLP-1/glucagon dubbele agonist in geavanceerde klinische proeven.","description_en":"Survodutide overzicht: mechanisme, studiestatus en veiligheidsprofiel van de GLP-1/glucagon dubbele agonist in geavanceerde klinische proeven."},"demo":false,"steckbrief":{"cas":"2805997-46-8","molekulargewicht":"4232 g/mol","aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":null,"quellen":["PubChem CID 171378821","chemverify Katalog 14.09.2026 (Aminosäurenzahl/Reinheitsstandard dort nicht geführt)"]},"verwandt":["semaglutid","tirzepatid","retatrutid","cagrilintid"]},{"slug":"tirzepatid","name":"Tirzepatide","synonyme":["LY3298176"],"kategorie":"Stoffwechsel","studienlage":"zugelassenes Arzneimittel","kurz":"Een dubbele GIP/GLP-1 receptor agonist, bekend als een goedgekeurd medicijn en hier vermeld als een onderzoeksstof voor metabole regulatie.","kurz_en":"Een dubbele GIP/GLP-1 receptor agonist, bekend als een goedgekeurd medicijn en hier vermeld als een onderzoeksstof voor metabole regulatie.","beschreibung":"Tirzepatide is een dubbele GIP/GLP-1 receptor agonist goedgekeurd als medicijn onder de namen Mounjaro en Zepbound. Het is onderwerp van uitgebreid klinisch onderzoek naar metabole en gewichtsregulatie bij type 2 diabetes en obesitas. De onderzoeksbatches hier vermeld zijn niet equivalent aan goedgekeurde medicijnen en zijn bedoeld voor laboratoriumgebruik alleen.","beschreibung_en":"Tirzepatide is een dubbele GIP/GLP-1 receptor agonist goedgekeurd als medicijn onder de namen Mounjaro en Zepbound. Het is onderwerp van uitgebreid klinisch onderzoek naar metabole en gewichtsregulatie bij type 2 diabetes en obesitas. De onderzoeksbatches hier vermeld zijn niet equivalent aan goedgekeurde medicijnen en zijn bedoeld voor laboratoriumgebruik alleen.","mechanismus":"Tirzepatide activeert zowel de GIP als de GLP-1 receptor tegelijkertijd, waardoor het wordt omschreven als een dubbele agonist. Via de GLP-1 receptor zijn effecten op de verzadigingsregulatie in de hypothalamus, vertraagde maaglediging en glucoseafhankelijke insulineafgifte beschreven. Het aanvullende GIP receptorcomponent is gekoppeld aan verhoogde insulinesecretie en effecten op lipide metabolisme.","mechanismus_en":"Tirzepatide activeert zowel de GIP als de GLP-1 receptor tegelijkertijd, waardoor het wordt omschreven als een dubbele agonist. Via de GLP-1 receptor zijn effecten op de verzadigingsregulatie in de hypothalamus, vertraagde maaglediging en glucoseafhankelijke insulineafgifte beschreven. Het aanvullende GIP receptorcomponent is gekoppeld aan verhoogde insulinesecretie en effecten op lipide metabolisme.","evidenz":[{"art":"klinisch","kurz":"In een gerandomiseerd onderzoek met 2.539 volwassenen met obesitas of overgewicht leidde wekelijkse tirzepatide over 72 weken tot een gemiddelde gewichtsverlies van tot 20,9 procent (15 mg) versus 3,1 procent onder placebo.","kurz_en":"In een gerandomiseerd onderzoek met 2.539 volwassenen met obesitas of overgewicht leidde wekelijkse tirzepatide over 72 weken tot een gemiddelde gewichtsverlies van tot 20,9 procent (15 mg) versus 3,1 procent onder placebo.","quelle":"Jastreboff AM et al. 2022, New England Journal of Medicine, PMID 35658024"},{"art":"klinisch","kurz":"In een gerandomiseerd head-to-head onderzoek met 1.879 mensen met type 2 diabetes verlaagde tirzepatide de HbA1c met 2,09 tot 2,46 procentpunten en het lichaamsgewicht met 7,8 tot 12,4 kg na 40 weken, in elk geval meer dan semaglutide 1 mg.","kurz_en":"In een gerandomiseerd head-to-head onderzoek met 1.879 mensen met type 2 diabetes verlaagde tirzepatide de HbA1c met 2,09 tot 2,46 procentpunten en het lichaamsgewicht met 7,8 tot 12,4 kg na 40 weken, in elk geval meer dan semaglutide 1 mg.","quelle":"Frías JP et al. 2021, New England Journal of Medicine, PMID 34170647"}],"sicherheit":["De meest voorkomend gerapporteerde effecten zijn gastro-intestinaal, met name misselijkheid, braken en diarree, met een risico op uitdroging in uitgesproken gevallen.","Volgens de productinformatie is het gebruik contra-indiceerd bij personen met een persoonlijke of familiegeschiedenis van medullair medullair carcinoom of multiple endocriene neoplasie syndroom type 2.","Dierstudies op ratten toonden afhankelijkheid van hoeveelheid en blootstellingsduur voor schildklier C-cel tumoren, en of deze bevinding overdraagt naar mensen is niet vastgesteld volgens de productinformatie."],"sicherheit_en":["De meest voorkomend gerapporteerde effecten zijn gastro-intestinaal, met name misselijkheid, braken en diarree, met een risico op uitdroging in uitgesproken gevallen.","Volgens de productinformatie is het gebruik contra-indiceerd bij personen met een persoonlijke of familiegeschiedenis van medullair medullair carcinoom of multiple endocriene neoplasie syndroom type 2.","Dierstudies op ratten toonden afhankelijkheid van hoeveelheid en blootstellingsduur voor schildklier C-cel tumoren, en of deze bevinding overdraagt naar mensen is niet vastgesteld volgens de productinformatie."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Tirzepatide is goedgekeurd als medicijn onder de naam Mounjaro in de EU sinds september 2022 voor de behandeling van type 2 diabetes, en sinds eind 2023 ook voor gewichtsbeheer. In de Verenigde Staten is het goedgekeurd onder de naam Mounjaro voor de behandeling van type 2 diabetes en onder de naam Zepbound voor gewichtsbeheer, en is het alleen op recept verkrijgbaar in beide regio's. De onderzoeksbatches hier beschreven zijn niet equivalent aan de goedgekeurde eindproducten.","rechtsstatus_en":"Tirzepatide is goedgekeurd als medicijn onder de naam Mounjaro in de EU sinds september 2022 voor de behandeling van type 2 diabetes, en sinds eind 2023 ook voor gewichtsbeheer. In de Verenigde Staten is het goedgekeurd onder de naam Mounjaro voor de behandeling van type 2 diabetes en onder de naam Zepbound voor gewichtsbeheer, en is het alleen op recept verkrijgbaar in beide regio's. De onderzoeksbatches hier beschreven zijn niet equivalent aan de goedgekeurde eindproducten.","typischeMg":[10,30,60],"faq":[{"q":"Is tirzepatide een goedgekeurd medicijn?","a":"Ja, tirzepatide is goedgekeurd als voorgeschreven medicijn onder de namen Mounjaro en Zepbound. De hier beschreven stof is slechts een onderzoeksbatch, geen afgerond farmaceutisch product.","q_en":"Is tirzepatide een goedgekeurd medicijn?","a_en":"Ja, tirzepatide is goedgekeurd als voorgeschreven medicijn onder de namen Mounjaro en Zepbound. De hier beschreven stof is slechts een onderzoeksbatch, geen afgerond farmaceutisch product."},{"q":"Hoe verschilt tirzepatide van semaglutide?","a":"Semaglutide werkt alleen op de GLP-1 receptor, terwijl tirzepatide additioneel ook op de GIP receptor werkt. In een vergelijkende studie toonde tirzepatide grotere effecten op HbA1c en lichaamsgewicht dan semaglutide.","q_en":"Hoe verschilt tirzepatide van semaglutide?","a_en":"Semaglutide werkt alleen op de GLP-1 receptor, terwijl tirzepatide additioneel ook op de GIP receptor werkt. In een vergelijkende studie toonde tirzepatide grotere effecten op HbA1c en lichaamsgewicht dan semaglutide."},{"q":"Waar wordt tirzepatide voor gebruikt als medicijn?","a":"Als goedgekeurd medicijn wordt tirzepatide voorgeschreven voor type 2 diabetes en gewichtsbeheersing. Deze pagina beschrijft de stof uitsluitend als een chemische stof voor onderzoek voor laboratoriumdoeleinden.","q_en":"Waar wordt tirzepatide voor gebruikt als medicijn?","a_en":"Als goedgekeurd medicijn wordt tirzepatide voorgeschreven voor type 2 diabetes en gewichtsbeheersing. Deze pagina beschrijft de stof uitsluitend als een chemische stof voor onderzoek voor laboratoriumdoeleinden."}],"seo":{"title":"Tirzepatide: Overzicht Dubbele GIP/GLP-1 Combinatie","title_en":"Tirzepatide: Overzicht Dubbele GIP/GLP-1 Combinatie","description":"Tirzepatide op een rij: dubbele GIP/GLP-1 mechanisme, SURMOUNT en SURPASS studie bewijs, veiligheidsprofiel en juridische status van het verbinding.","description_en":"Tirzepatide op een rij: dubbele GIP/GLP-1 mechanisme, SURMOUNT en SURPASS studie bewijs, veiligheidsprofiel en juridische status van het verbinding."},"demo":false,"steckbrief":{"cas":"2023788-19-2","molekulargewicht":"4813 g/mol","aminosaeuren":39,"halbwertszeit":"≈ 5 dagen (eliminatie, Mounjaro informatie)","reinheitsstandard":"≥ 99 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":39,"quellen":["PubChem CID 166567236","DailyMed SPL MOUNJARO (Tirzepatid), Eli Lilly and Company","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 5 dagen (eliminatie, Mounjaro informatie)","reinheitsstandard_en":"≥ 99 % (HPLC, commercieel standaard)"},"verwandt":["semaglutid","retatrutid","cagrilintid","survodutid"]},{"slug":"cjc-1295","name":"CJC-1295","synonyme":["Mod GRF 1-29","Modified GRF (1-29)","CJC-1295 met DAC","DAC:GRF"],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Een synthetisch analoog van groeihormoon-afgeefhormoon, onderzocht in twee varianten met verschillende duur van werking.","kurz_en":"Een synthetisch analoog van groeihormoon-afgeefhormoon, onderzocht in twee varianten met verschillende duur van werking.","beschreibung":"CJC-1295 is een gestabiliseerd analoog van het eigen GHRH van het lichaam, onderzocht in de context van de groeihormoonas. Het bestaat in twee varianten: zonder DAC (Drug Affinity Complex), wat een korte duur van werking heeft, en met DAC, wat een substantieel verlengde duur bereikt door binding aan serumalbumine. Beschikbare menselijke gegevens komen voornamelijk uit vroege klinische onderzoeken bij gezonde volwassenen.","beschreibung_en":"CJC-1295 is een gestabiliseerd analoog van het eigen GHRH van het lichaam, onderzocht in de context van de groeihormoonas. Het bestaat in twee varianten: zonder DAC (Drug Affinity Complex), wat een korte duur van werking heeft, en met DAC, wat een substantieel verlengde duur bereikt door binding aan serumalbumine. Beschikbare menselijke gegevens komen voornamelijk uit vroege klinische onderzoeken bij gezonde volwassenen.","mechanismus":"CJC-1295 bindt aan de GHRH receptor op somatotrofe cellen in de hypofyse, wat de eigen pulserende afgifte van groeihormoon door het lichaam triggert. Zonder DAC wordt de molecuul binnen minuten afgebroken, wat een korte, uitgesproken hormoonpuls produceert. Met DAC bindt een chemische anker covalent aan albumine in het bloed, waardoor de duur van werking tot enkele dagen wordt verlengd, terwijl studies aangeven dat het pulserende afgiftepatroon behouden blijft.","mechanismus_en":"CJC-1295 bindt aan de GHRH receptor op somatotrofe cellen in de hypofyse, wat de eigen pulserende afgifte van groeihormoon door het lichaam triggert. Zonder DAC wordt de molecuul binnen minuten afgebroken, wat een korte, uitgesproken hormoonpuls produceert. Met DAC bindt een chemische anker covalent aan albumine in het bloed, waardoor de duur van werking tot enkele dagen wordt verlengd, terwijl studies aangeven dat het pulserende afgiftepatroon behouden blijft.","evidenz":[{"art":"klinisch","kurz":"Twee gerandomiseerde, placebo-gecontroleerde studies bij gezonde volwassenen met stapsgewijs toenemende hoeveelheden: een enkele injectie van CJC-1295 met DAC verhoogde groeihormoonniveaus voor enkele dagen en IGF-1 niveaus voor 9 tot 11 dagen.","kurz_en":"Twee gerandomiseerde, placebo-gecontroleerde studies bij gezonde volwassenen met stapsgewijs toenemende hoeveelheden: een enkele injectie van CJC-1295 met DAC verhoogde groeihormoonniveaus voor enkele dagen en IGF-1 niveaus voor 9 tot 11 dagen.","quelle":"Teichman et al. 2006, Journal of Clinical Endocrinology & Metabolism, PMID 16352683"},{"art":"klinisch","kurz":"Een follow-up analyse van dezelfde proefpersonen toonde aan dat pulserende groeihormoonafgifte behouden bleef zelfs onder de verlengde stimulatie door CJC-1295 met DAC.","kurz_en":"Een follow-up analyse van dezelfde proefpersonen toonde aan dat pulserende groeihormoonafgifte behouden bleef zelfs onder de verlengde stimulatie door CJC-1295 met DAC.","quelle":"Ionescu & Frohman 2006, Journal of Clinical Endocrinology & Metabolism, PMID 17018654"}],"sicherheit":["In de beschikbare studies werden voornamelijk milde, lokale reacties op de injectieplaats gerapporteerd.","Een fase 2 proef van CJC-1295 met DAC voor een ongerelateerde aandoening is gestaakt als voorzorg nadat een deelnemer overleed; een causaal verband met het peptide is niet vastgesteld.","De langetermijneffecten van een persistent verhoogd IGF-1 niveau bij mensen zijn niet volledig begrepen.","Langetermijngezondheidsgegevens bij mensen zijn nog niet beschikbaar."],"sicherheit_en":["In de beschikbare studies werden voornamelijk milde, lokale reacties op de injectieplaats gerapporteerd.","Een fase 2 proef van CJC-1295 met DAC voor een ongerelateerde aandoening is gestaakt als voorzorg nadat een deelnemer overleed; een causaal verband met het peptide is niet vastgesteld.","De langetermijneffecten van een persistent verhoogd IGF-1 niveau bij mensen zijn niet volledig begrepen.","Langetermijngezondheidsgegevens bij mensen zijn nog niet beschikbaar."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"CJC-1295 is niet goedgekeurd als medicijn in de EU of de VS. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek en is niet bedoeld voor menselijk gebruik.","rechtsstatus_en":"CJC-1295 is niet goedgekeurd als medicijn in de EU of de VS. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek en is niet bedoeld voor menselijk gebruik.","typischeMg":[2,5],"faq":[{"q":"Wat is het verschil tussen CJC-1295 met en zonder DAC","a":"Zonder DAC wordt het peptide binnen minuten afgebroken, wat een korte, uitgesproken hormoonpuls veroorzaakt. Met DAC bindt een chemische anker aan albumine in het bloed, waardoor de duur tot enkele dagen wordt verlengd, terwijl studies aangeven dat het pulserende afgiftepatroon behouden blijft.","q_en":"Wat is het verschil tussen CJC-1295 met en zonder DAC","a_en":"Zonder DAC wordt het peptide binnen minuten afgebroken, wat een korte, uitgesproken hormoonpuls veroorzaakt. Met DAC bindt een chemische anker aan albumine in het bloed, waardoor de duur tot enkele dagen wordt verlengd, terwijl studies aangeven dat het pulserende afgiftepatroon behouden blijft."},{"q":"Is CJC-1295 een goedgekeurd medicijn","a":"Nee. CJC-1295 is niet goedgekeurd als medicijn in de EU of de VS en wordt uitsluitend verkocht als chemische stof voor onderzoek voor laboratoriumgebruik.","q_en":"Is CJC-1295 een goedgekeurd medicijn","a_en":"Nee. CJC-1295 is niet goedgekeurd als medicijn in de EU of de VS en wordt uitsluitend verkocht als chemische stof voor onderzoek voor laboratoriumgebruik."},{"q":"Waar wordt CJC-1295 in onderzoek bestudeerd","a":"CJC-1295 wordt bestudeerd in de context van de groeihormoonas, met name met betrekking tot de eigen afgifte van groeihormoon door het lichaam en de resulterende IGF-1 productie in de lever.","q_en":"Waar wordt CJC-1295 in onderzoek bestudeerd","a_en":"CJC-1295 wordt bestudeerd in de context van de groeihormoonas, met name met betrekking tot de eigen afgifte van groeihormoon door het lichaam en de resulterende IGF-1 productie in de lever."}],"seo":{"title":"Onderzoeksoverzicht van CJC-1295","title_en":"Onderzoeksoverzicht van CJC-1295","description":"CJC-1295 feitelijk uitgelegd: werkingsmechanisme, het verschil met en zonder DAC, onderzoeksdata en de juridische status van dit GHRH-analoog.","description_en":"CJC-1295 feitelijk uitgelegd: werkingsmechanisme, het verschil met en zonder DAC, onderzoeksdata en de juridische status van dit GHRH-analoog."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":null,"aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":null,"quellen":["chemverify Katalog 14.09.2026 (Eintrag deckt CJC-1295 mit und ohne DAC generisch ab, CAS/Molekulargewicht nicht eindeutig einer Variante zuordenbar)"]},"verwandt":["ipamorelin","sermorelin","tesamorelin","igf-1-lr3"]},{"slug":"hexarelin","name":"Hexarelin","synonyme":[],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Een synthetisch hexapeptide uit de klasse van groeihormoon-afgeefpeptide, bestudeerd in vroeg klinisch onderzoek naar groeihormoonsecretie.","kurz_en":"Een synthetisch hexapeptide uit de klasse van groeihormoon-afgeefpeptide, bestudeerd in vroeg klinisch onderzoek naar groeihormoonsecretie.","beschreibung":"Hexarelin is een synthetisch hexapeptide uit de GHRP (growth hormone releasing peptide) klasse, voor het eerst farmacologisch beschreven in 1994. Het is bestudeerd in klinische proeven naar groeihormoonsecretie bij kinderen, volwassenen en ouderen, en afzonderlijk in preklinisch onderzoek naar cardiale effecten.","beschreibung_en":"Hexarelin is een synthetisch hexapeptide uit de GHRP (growth hormone releasing peptide) klasse, voor het eerst farmacologisch beschreven in 1994. Het is bestudeerd in klinische proeven naar groeihormoonsecretie bij kinderen, volwassenen en ouderen, en afzonderlijk in preklinisch onderzoek naar cardiale effecten.","mechanismus":"Hexarelin bindt aan de ghrelinreceptor (GHS-R1a) in de hypothalamus en de hypofyse, wat een pulserende afgifte van het eigen groeihormoon van het lichaam triggert. In tegenstelling tot meer selectieve peptiden in dezelfde klasse zoals ipamoreline, vertoonde hexarelin in studies een relevante aanvullende afgifte van ACTH en cortisol. Preklinisch onderzoek beschrijft ook groeihormoononafhankelijke binding aan cardiale GHS-R1a receptoren.","mechanismus_en":"Hexarelin bindt aan de ghrelinreceptor (GHS-R1a) in de hypothalamus en de hypofyse, wat een pulserende afgifte van het eigen groeihormoon van het lichaam triggert. In tegenstelling tot meer selectieve peptiden in dezelfde klasse zoals ipamoreline, vertoonde hexarelin in studies een relevante aanvullende afgifte van ACTH en cortisol. Preklinisch onderzoek beschrijft ook groeihormoononafhankelijke binding aan cardiale GHS-R1a receptoren.","evidenz":[{"art":"preklinisch","kurz":"In studies op pasgeboren en volwassen ratten veroorzaakte hexarelin een uitgesproken en langdurige groeihormoonafgifte, en was het effectiever dan het gerelateerde peptide GHRP-6 wanneer subcutaan toegediend.","kurz_en":"In studies op pasgeboren en volwassen ratten veroorzaakte hexarelin een uitgesproken en langdurige groeihormoonafgifte, en was het effectiever dan het gerelateerde peptide GHRP-6 wanneer subcutaan toegediend.","quelle":"Deghenghi R et al. 1994, Life Sciences, Bd. 54(18), S. 1321-1328, PMID 7910650"},{"art":"klinisch","kurz":"In een studie van 60 personen van 5 tot 81 jaar werd de groeihormoonrespons op hexarelin vergeleken bij prepubertaire en pubertaire kinderen, jongvolwassenen en oudere volwassenen, met een merkbaar zwakkere respons bij prepubertaire kinderen en oudere deelnemers.","kurz_en":"In een studie van 60 personen van 5 tot 81 jaar werd de groeihormoonrespons op hexarelin vergeleken bij prepubertaire en pubertaire kinderen, jongvolwassenen en oudere volwassenen, met een merkbaar zwakkere respons bij prepubertaire kinderen en oudere deelnemers.","quelle":"Arvat E et al. 1997, European Journal of Endocrinology, Bd. 137(6), PMID 9437229"},{"art":"klinisch","kurz":"In een studie van 15 gezonde mannen verhoogde hexarelin ACTH en cortisol, een effect dat werd versterkt door desmopressine (een vasopressine analog), wat wijst op vasopressine betrokkenheid bij dit bijwerking.","kurz_en":"In een studie van 15 gezonde mannen verhoogde hexarelin ACTH en cortisol, een effect dat werd versterkt door desmopressine (een vasopressine analog), wat wijst op vasopressine betrokkenheid bij dit bijwerking.","quelle":"Korbonits M et al. 1999, Journal of Clinical Endocrinology & Metabolism, Bd. 84(7), S. 2489-2495, PMID 10404825"},{"art":"preklinisch","kurz":"In een ratmodel toonde hexarelin beschermende effecten op het hart na ischemie-reperfusie die onafhankelijk waren van groeihormoonactiviteit en werden toegeschreven aan directe binding aan hartreceptoren.","kurz_en":"In een ratmodel toonde hexarelin beschermende effecten op het hart na ischemie-reperfusie die onafhankelijk waren van groeihormoonactiviteit en werden toegeschreven aan directe binding aan hartreceptoren.","quelle":"Locatelli V et al. 1999, Endocrinology, Bd. 140(9), S. 4024-4031, PMID 10465272"}],"sicherheit":["In klinische studies triggert hexarelin niet alleen groeihormoon maar ook een relevante afgifte van ACTH, cortisol en prolactine, een effect dat niet tot deze mate werd waargenomen met meer selectieve GHRPs zoals ipamoreline.","De groeihormoonrespons op hexarelin is merkbaar zwakker bij prepubertaire kinderen en oudere volwassenen dan bij adolescenten en jongvolwassenen.","Onafhankelijke langetermijnveiligheidsgegevens bij gezonde volwassenen buiten gecontroleerde kortetermijnstudies zijn niet beschikbaar.","Interacties met andere hormoonassen, met name de hypothalamus-hypofyse-bijnier as, zijn niet definitief onderzocht."],"sicherheit_en":["In klinische studies triggert hexarelin niet alleen groeihormoon maar ook een relevante afgifte van ACTH, cortisol en prolactine, een effect dat niet tot deze mate werd waargenomen met meer selectieve GHRPs zoals ipamoreline.","De groeihormoonrespons op hexarelin is merkbaar zwakker bij prepubertaire kinderen en oudere volwassenen dan bij adolescenten en jongvolwassenen.","Onafhankelijke langetermijnveiligheidsgegevens bij gezonde volwassenen buiten gecontroleerde kortetermijnstudies zijn niet beschikbaar.","Interacties met andere hormoonassen, met name de hypothalamus-hypofyse-bijnier as, zijn niet definitief onderzocht."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Hexarelin is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten en wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumdoeleinden.","rechtsstatus_en":"Hexarelin is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten en wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumdoeleinden.","typischeMg":[2,5],"faq":[{"q":"Verschilt hexarelin van ipamoreline","a":"Ja. Beide binden aan dezelfde ghrelinreceptor, maar hexarelin toonde aanvullend een relevante afgifte van ACTH en cortisol in studies, terwijl ipamoreline als selectiever wordt beschouwd voor de groeihormoonas alleen.","q_en":"Verschilt hexarelin van ipamoreline","a_en":"Ja. Beide binden aan dezelfde ghrelinreceptor, maar hexarelin toonde aanvullend een relevante afgifte van ACTH en cortisol in studies, terwijl ipamoreline als selectiever wordt beschouwd voor de groeihormoonas alleen."},{"q":"Is hexarelin onderzocht bij kinderen","a":"Hexarelin is gebruikt in klinische studies naar de secretie van groeihormoon bij kinderen in verschillende pubertaire stadia, binnen gecontroleerde onderzoeksprotocollen en niet als goedgekeurd medicijn.","q_en":"Is hexarelin onderzocht bij kinderen","a_en":"Hexarelin is gebruikt in klinische studies naar de secretie van groeihormoon bij kinderen in verschillende pubertaire stadia, binnen gecontroleerde onderzoeksprotocollen en niet als goedgekeurd medicijn."},{"q":"Is hexarelin een goedgekeurd medicijn","a":"Nee. Hexarelin is niet goedgekeurd als medicijn in de EU of de VS en wordt uitsluitend aangeboden als chemische stof voor onderzoek, niet voor menselijk gebruik.","q_en":"Is hexarelin een goedgekeurd medicijn","a_en":"Nee. Hexarelin is niet goedgekeurd als medicijn in de EU of de VS en wordt uitsluitend aangeboden als chemische stof voor onderzoek, niet voor menselijk gebruik."}],"seo":{"title":"Onderzoeksoverzicht van hexarelin","title_en":"Onderzoeksoverzicht van hexarelin","description":"Hexarelin feitelijk uitgelegd: werkingsmechanisme, studiegegevens over groeihormoon en ACTH/cortisol, veiligheidsprofiel en juridische status van dit GHRP-peptide.","description_en":"Hexarelin feitelijk uitgelegd: werkingsmechanisme, studiegegevens over groeihormoon en ACTH/cortisol, veiligheidsprofiel en juridische status van dit GHRP-peptide."},"demo":false,"steckbrief":{"cas":"140703-51-1","molekulargewicht":"887,0 g/mol","aminosaeuren":6,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":6,"quellen":["PubChem CID 6918297","chemverify Katalog 14.09.2026"]},"verwandt":["ipamorelin","cjc-1295","sermorelin","igf-1-lr3"]},{"slug":"igf-1-lr3","name":"IGF-1 LR3","synonyme":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"kategorie":"Wachstumshormon-Achse","studienlage":"präklinisch","kurz":"Een genetisch verlengde analoge van IGF-1 met 83 aminozuren, onderzocht in dierlijke modellen voor groeieffecten en vermeld als een dopingsubstantie in competitieve sport.","kurz_en":"Een genetisch verlengde analoge van IGF-1 met 83 aminozuren, onderzocht in dierlijke modellen voor groeieffecten en vermeld als een dopingsubstantie in competitieve sport.","beschreibung":"IGF-1 LR3 is een recombinante analoog van het natuurlijk voorkomende insulineachtige groeifactor 1, oorspronkelijk ontwikkeld voor celkweekonderzoek. Het draagt extra aminozuren aan het N-terminus en een veranderde positie 3, wat ervoor zorgt dat het grotendeels niet kan binden aan IGF-bindende eiwitten. Het wordt voornamelijk bestudeerd in dierlijke modellen van orgaan- en celgroei, maar buiten onderzoek wordt het ook wijdverbreid gebruikt voor vermeende prestatieverbetering zonder solide menselijke gegevens.","beschreibung_en":"IGF-1 LR3 is een recombinante analoog van het natuurlijk voorkomende insulineachtige groeifactor 1, oorspronkelijk ontwikkeld voor celkweekonderzoek. Het draagt extra aminozuren aan het N-terminus en een veranderde positie 3, wat ervoor zorgt dat het grotendeels niet kan binden aan IGF-bindende eiwitten. Het wordt voornamelijk bestudeerd in dierlijke modellen van orgaan- en celgroei, maar buiten onderzoek wordt het ook wijdverbreid gebruikt voor vermeende prestatieverbetering zonder solide menselijke gegevens.","mechanismus":"Omdat het slecht bindt aan IGF-bindende eiwitten, blijft een groter deel van IGF-1 LR3 vrij beschikbaar en activeert de IGF-1 receptor sterker en langer dan het native IGF-1. In preklinische modellen wordt dit beschreven als het stimuleren van verhoogde celproliferatie via de ERK en PI3K/Akt signaleringsroutes. Tegelijkertijd wordt de onderdrukking van endogene IGF-1 productie en IGF-bindende eiwitniveaus gerapporteerd.","mechanismus_en":"Omdat het slecht bindt aan IGF-bindende eiwitten, blijft een groter deel van IGF-1 LR3 vrij beschikbaar en activeert de IGF-1 receptor sterker en langer dan het native IGF-1. In preklinische modellen wordt dit beschreven als het stimuleren van verhoogde celproliferatie via de ERK en PI3K/Akt signaleringsroutes. Tegelijkertijd wordt de onderdrukking van endogene IGF-1 productie en IGF-bindende eiwitniveaus gerapporteerd.","evidenz":[{"art":"preklinisch","kurz":"Een infusiestudie bij cavia’s beschreef verhoogde orgaangroei onder lang R3 IGF-1, terwijl de plasmalevels van endogeen IGF-1, IGF-2 en IGF-bindende eiwitten afnamen.","kurz_en":"Een infusiestudie bij cavia’s beschreef verhoogde orgaangroei onder lang R3 IGF-1, terwijl de plasmalevels van endogeen IGF-1, IGF-2 en IGF-bindende eiwitten afnamen.","quelle":"Conlon et al. 1995, Journal of Endocrinology, PMID 7561636"},{"art":"preklinisch","kurz":"Een celstudie in foetale schapen cardiomyocyten gebruikte IGF-1 LR3 als een stabiele receptorstimulus en beschreef celproliferatie gemedieerd door de ERK en PI3K routes.","kurz_en":"Een celstudie in foetale schapen cardiomyocyten gebruikte IGF-1 LR3 als een stabiele receptorstimulus en beschreef celproliferatie gemedieerd door de ERK en PI3K routes.","quelle":"Sundgren et al. 2003, American Journal of Physiology, PMID 12947030"},{"art":"klinisch","kurz":"Een review uit 2026 beschreef een aanzienlijke kloof tussen de klinische bewijslast voor groeihormoon-as peptiden zoals IGF-1 LR3 en hun wijdverbreide zelftoediening buiten medisch toezicht.","kurz_en":"Een review uit 2026 beschreef een aanzienlijke kloof tussen de klinische bewijslast voor groeihormoon-as peptiden zoals IGF-1 LR3 en hun wijdverbreide zelftoediening buiten medisch toezicht.","quelle":"Dominikowski et al. 2026, Frontiers in Endocrinology, PMID 42395176"}],"sicherheit":["Gecontroleerde menselijke veiligheidsstudies op IGF-1 LR3 ontbreken, het beschikbare bewijs komt uit cel- en dierlijke modellen.","Dierlijke modellen beschrijven de onderdrukking van de eigen IGF-1-as van het lichaam, waarvan de gevolgen niet in mensen zijn bestudeerd.","Ongecontroleerde verhoging van IGF-1 activiteit wordt in de literatuur besproken als een theoretisch risicofactor voor ongewenste cel- en weefselgroei, een causale link bij mensen is niet vastgesteld.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"sicherheit_en":["Gecontroleerde menselijke veiligheidsstudies op IGF-1 LR3 ontbreken, het beschikbare bewijs komt uit cel- en dierlijke modellen.","Dierlijke modellen beschrijven de onderdrukking van de eigen IGF-1-as van het lichaam, waarvan de gevolgen niet in mensen zijn bestudeerd.","Ongecontroleerde verhoging van IGF-1 activiteit wordt in de literatuur besproken als een theoretisch risicofactor voor ongewenste cel- en weefselgroei, een causale link bij mensen is niet vastgesteld.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"IGF-1 LR3 is niet toegelaten als geneesmiddel in Duitsland, de EU of de Verenigde Staten en is niet geclassificeerd als voedingsmiddel. Het wordt uitsluitend verkocht als chemische stof voor onderzoek. In de georganiseerde sport is het te allen tijde verboden als groeifactor in categorie S2 volgens de WADA-dopinglijst.","rechtsstatus_en":"IGF-1 LR3 is niet toegelaten als geneesmiddel in Duitsland, de EU of de Verenigde Staten en is niet geclassificeerd als voedingsmiddel. Het wordt uitsluitend verkocht als chemische stof voor onderzoek. In de georganiseerde sport is het te allen tijde verboden als groeifactor in categorie S2 volgens de WADA-dopinglijst.","typischeMg":[],"faq":[{"q":"Wat onderscheidt IGF-1 LR3 van natuurlijk IGF-1?","a":"IGF-1 LR3 draagt extra aminozuren aan het N-terminus en een veranderde positie 3, wat betekent dat het nauwelijks bindt aan IGF-bindende eiwitten en daarom langer en sterker werkt op de receptor dan het native IGF-1.","q_en":"Wat onderscheidt IGF-1 LR3 van natuurlijk IGF-1?","a_en":"IGF-1 LR3 draagt extra aminozuren aan het N-terminus en een veranderde positie 3, wat betekent dat het nauwelijks bindt aan IGF-bindende eiwitten en daarom langer en sterker werkt op de receptor dan het native IGF-1."},{"q":"Is IGF-1 LR3 toegestaan in sport?","a":"Nee, het wordt als groeifactor op de WADA Verbodenlijst (categorie S2) vermeld en is het altijd verboden in georganiseerde sport.","q_en":"Is IGF-1 LR3 toegestaan in sport?","a_en":"Nee, het wordt als groeifactor op de WADA Verbodenlijst (categorie S2) vermeld en is het altijd verboden in georganiseerde sport."},{"q":"Zijn er menselijke studies over IGF-1 LR3?","a":"Gecontroleerde menselijke studies zijn niet beschikbaar, het bestaande bewijs komt uit cel en dierlijke modellen, een review uit 2026 wijst op deze bewijskloof.","q_en":"Zijn er menselijke studies over IGF-1 LR3?","a_en":"Gecontroleerde menselijke studies zijn niet beschikbaar, het bestaande bewijs komt uit cel en dierlijke modellen, een review uit 2026 wijst op deze bewijskloof."}],"seo":{"title":"IGF-1 LR3: onderzoeksprofiel en bewijs","title_en":"IGF-1 LR3: onderzoeksprofiel en bewijs","description":"IGF-1 LR3 overzicht: structuur, pre-klinisch bewijs, dopingstatus in sport (WADA S2) en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext.","description_en":"IGF-1 LR3 overzicht: structuur, pre-klinisch bewijs, dopingstatus in sport (WADA S2) en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":"9111.4 g/mol","aminosaeuren":83,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":83,"quellen":["chemverify Katalog 14.09.2026 (PubChem: kein Eintrag für IGF-1 LR3, CAS dort nicht geführt)"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["hexarelin","cjc-1295","tesamorelin","sermorelin"]},{"slug":"ipamorelin","name":"Ipamoreline","synonyme":["NNC 26-0161"],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Een selectief pentapeptide uit de groeihormoon-afgeefpeptide klasse, onderzocht in vroeg klinisch onderzoek.","kurz_en":"Een selectief pentapeptide uit de groeihormoon-afgeefpeptide klasse, onderzocht in vroeg klinisch onderzoek.","beschreibung":"Ipamoreline is een synthetisch peptide bestaande uit vijf aminozuren dat het eigen boodschapperhormoon ghrelin van het lichaam nabootst. Het werd voor het eerst beschreven in 1998 als het eerste selectieve lid van zijn medicijnklasse en is onderzocht in klinische proeven waaronder bij patiënten die herstellen na abdominale operaties. Voor toepassingen gerelateerd aan groeihormoon zijn er tot op heden geen gecontroleerde studies bij gezonde volwassenen beschikbaar.","beschreibung_en":"Ipamoreline is een synthetisch peptide bestaande uit vijf aminozuren dat het eigen boodschapperhormoon ghrelin van het lichaam nabootst. Het werd voor het eerst beschreven in 1998 als het eerste selectieve lid van zijn medicijnklasse en is onderzocht in klinische proeven waaronder bij patiënten die herstellen na abdominale operaties. Voor toepassingen gerelateerd aan groeihormoon zijn er tot op heden geen gecontroleerde studies bij gezonde volwassenen beschikbaar.","mechanismus":"Ipamoreline bindt selectief aan de ghrelinreceptor (GHS-R1A) in de hypothalamus en de hypofyseklier, waardoor het remmende effect van somatostatin wordt versoepeld. Dit leidt tot een pulserende afgifte van het eigen groeihormoon van het hypofyseklier. In tegenstelling tot oudere peptiden in dezelfde klasse, lieten studies geen relevant verhoging van ACTH, cortisol of prolactine zien met ipamoreline.","mechanismus_en":"Ipamoreline bindt selectief aan de ghrelinreceptor (GHS-R1A) in de hypothalamus en de hypofyseklier, waardoor het remmende effect van somatostatin wordt versoepeld. Dit leidt tot een pulserende afgifte van het eigen groeihormoon van het hypofyseklier. In tegenstelling tot oudere peptiden in dezelfde klasse, lieten studies geen relevant verhoging van ACTH, cortisol of prolactine zien met ipamoreline.","evidenz":[{"art":"preklinisch","kurz":"De oorspronkelijke beschrijving in een varkensmodel liet zien dat ipamoreline groeihormoon vrijgeeft zonder een relevant effect op ACTH, cortisol, prolactine, FSH of LH, in tegenstelling tot oudere peptiden in dezelfde klasse.","kurz_en":"De oorspronkelijke beschrijving in een varkensmodel liet zien dat ipamoreline groeihormoon vrijgeeft zonder een relevant effect op ACTH, cortisol, prolactine, FSH of LH, in tegenstelling tot oudere peptiden in dezelfde klasse.","quelle":"Raun et al. 1998, European Journal of Endocrinology, PMID 9849822"},{"art":"preklinisch","kurz":"In een ratmodel van postoperatieve darmparalyse versnelde ipamoreline het herstel van de darmfunctie na de operatie.","kurz_en":"In een ratmodel van postoperatieve darmparalyse versnelde ipamoreline het herstel van de darmfunctie na de operatie.","quelle":"Venkova et al. 2009, Journal of Pharmacology and Experimental Therapeutics, PMID 19289567"},{"art":"klinisch","kurz":"In een gerandomiseerde, placebo-gecontroleerde fase 2 proef met 117 patiënten na darmoperatie, verschilde het tijd tot de eerste getolereerde maaltijd statistisch niet tussen de ipamoreline en placebo groepen.","kurz_en":"In een gerandomiseerde, placebo-gecontroleerde fase 2 proef met 117 patiënten na darmoperatie, verschilde het tijd tot de eerste getolereerde maaltijd statistisch niet tussen de ipamoreline en placebo groepen.","quelle":"International Journal of Colorectal Disease 2014, DOI 10.1007/s00384-014-2030-8"}],"sicherheit":["In de grootste gecontroleerde proef tot nu toe waren de gerapporteerde bijwerkingen even frequent in de ipamoreline en placebo groepen.","De FDA stopte de klinische ontwikkeling van ipamoreline in 2023 nadat twee sterfgevallen in de studiepopulatie plaatsvonden; een causale link naar het peptide wordt wetenschappelijk betwist.","Lange termijn veiligheidsgegevens bij gezonde volwassenen zijn niet beschikbaar.","Interacties met andere hormoonassen zijn niet volledig onderzocht."],"sicherheit_en":["In de grootste gecontroleerde proef tot nu toe waren de gerapporteerde bijwerkingen even frequent in de ipamoreline en placebo groepen.","De FDA stopte de klinische ontwikkeling van ipamoreline in 2023 nadat twee sterfgevallen in de studiepopulatie plaatsvonden; een causale link naar het peptide wordt wetenschappelijk betwist.","Lange termijn veiligheidsgegevens bij gezonde volwassenen zijn niet beschikbaar.","Interacties met andere hormoonassen zijn niet volledig onderzocht."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Ipamoreline is niet goedgekeurd als medicijn in de EU of de VS. De FDA heeft verdere klinische ontwikkeling in 2023 gestopt. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek.","rechtsstatus_en":"Ipamoreline is niet goedgekeurd als medicijn in de EU of de VS. De FDA heeft verdere klinische ontwikkeling in 2023 gestopt. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek.","typischeMg":[2,5],"faq":[{"q":"Verhoogt ipamoreline cortisol zoals oudere peptiden in dezelfde klasse","a":"In de beschikbare studies vertoonde ipamoreline, in tegenstelling tot oudere peptiden zoals GHRP-6 of GHRP-2, geen relevant verhoging van ACTH of cortisol. Dit wordt beschouwd als zijn best wetenschappelijk gedocumenteerde onderscheidende kenmerk.","q_en":"Verhoogt ipamoreline cortisol zoals oudere peptiden in dezelfde klasse","a_en":"In de beschikbare studies vertoonde ipamoreline, in tegenstelling tot oudere peptiden zoals GHRP-6 of GHRP-2, geen relevant verhoging van ACTH of cortisol. Dit wordt beschouwd als zijn best wetenschappelijk gedocumenteerde onderscheidende kenmerk."},{"q":"Is ipamoreline een goedgekeurd medicijn","a":"Nee. De FDA heeft de klinische ontwikkeling van ipamoreline in 2023 gestopt. Het is niet goedgekeurd in de EU of de VS en wordt verkocht als een chemische stof voor onderzoek.","q_en":"Is ipamoreline een goedgekeurd medicijn","a_en":"Nee. De FDA heeft de klinische ontwikkeling van ipamoreline in 2023 gestopt. Het is niet goedgekeurd in de EU of de VS en wordt verkocht als een chemische stof voor onderzoek."},{"q":"Waarom is de ontwikkeling van ipamoreline gestopt","a":"Na twee overlijdensgevallen in een studiepopulatie van ernstig zieke patiënten na abdominale operatie, heeft de FDA de verdere ontwikkeling in 2023 gestopt. Een causale link met het peptide wordt wetenschappelijk betwist.","q_en":"Waarom is de ontwikkeling van ipamoreline gestopt","a_en":"Na twee overlijdensgevallen in een studiepopulatie van ernstig zieke patiënten na abdominale operatie, heeft de FDA de verdere ontwikkeling in 2023 gestopt. Een causale link met het peptide wordt wetenschappelijk betwist."}],"seo":{"title":"Onderzoeksoverzicht van ipamoreline","title_en":"Onderzoeksoverzicht van ipamoreline","description":"Ipamoreline feitelijk uitgelegd: selectief werkingsmechanisme, studiegegevens, veiligheidsprofiel en juridische status van dit ghreline mimet.","description_en":"Ipamoreline feitelijk uitgelegd: selectief werkingsmechanisme, studiegegevens, veiligheidsprofiel en juridische status van dit ghreline mimet."},"demo":false,"steckbrief":{"cas":"170851-70-4","molekulargewicht":"711,9 g/mol","aminosaeuren":5,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":5,"quellen":["PubChem CID 9831659","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, commercieel standaard)"},"verwandt":["cjc-1295","sermorelin","tesamorelin","hexarelin"]},{"slug":"sermorelin","name":"Sermoreline","synonyme":["GRF 1-29","GHRH(1-29)","Geref (historische merknaam)"],"kategorie":"Wachstumshormon-Achse","studienlage":"klinisch untersucht","kurz":"Een kortketenfragment van het eigen GHRH van het lichaam, historisch goedgekeurd als medicijn, wordt nu verkocht als onderzoeksstof.","kurz_en":"Een kortketenfragment van het eigen GHRH van het lichaam, historisch goedgekeurd als medicijn, wordt nu verkocht als onderzoeksstof.","beschreibung":"Sermoreline is het biologisch actieve fragment GHRH(1-29) van het lichaamseigen groeihormoon-afgevend hormoon. In de VS werd het in 1990 goedgekeurd als diagnostisch middel en in 1997 voor kleine gestalte door groeihormoontekort bij kinderen; de goedkeuring werd in 2008 om productieredenen ingetrokken. Vandaag wordt het buiten die historische goedkeuring als onderzoeksstof bestudeerd.","beschreibung_en":"Sermoreline is het biologisch actieve fragment GHRH(1-29) van het lichaamseigen groeihormoon-afgevend hormoon. In de VS werd het in 1990 goedgekeurd als diagnostisch middel en in 1997 voor kleine gestalte door groeihormoontekort bij kinderen; de goedkeuring werd in 2008 om productieredenen ingetrokken. Vandaag wordt het buiten die historische goedkeuring als onderzoeksstof bestudeerd.","mechanismus":"Sermoreline bindt aan de GHRH receptor op somatotrofe cellen in de hypofyse en activeert de adenylaatcyclase-cAMP cascade. Dit triggert de afgifte van het eigen groeihormoon van het lichaam in fysiologische pulsen. Vanwege zijn zeer korte halfwaardetijd van slechts enkele minuten is de resulterende hormoonpuls kort en matig.","mechanismus_en":"Sermoreline bindt aan de GHRH receptor op somatotrofe cellen in de hypofyse en activeert de adenylaatcyclase-cAMP cascade. Dit triggert de afgifte van het eigen groeihormoon van het lichaam in fysiologische pulsen. Vanwege zijn zeer korte halfwaardetijd van slechts enkele minuten is de resulterende hormoonpuls kort en matig.","evidenz":[{"art":"klinisch","kurz":"In een gerandomiseerd, placebo-gecontroleerd onderzoek bij oudere mannen en vrouwen verhoogde een GHRH(1-29)-analoog met Nle27-substitutie de groeihormoon- en IGF-1-niveaus over enkele maanden en verbeterde de vetvrije lichaamsmassa.","kurz_en":"In een gerandomiseerd, placebo-gecontroleerd onderzoek bij oudere mannen en vrouwen verhoogde een GHRH(1-29)-analoog met Nle27-substitutie de groeihormoon- en IGF-1-niveaus over enkele maanden en verbeterde de vetvrije lichaamsmassa.","quelle":"Khorram et al. 1997, Journal of Clinical Endocrinology & Metabolism, PMID 9141536"},{"art":"klinisch","kurz":"Een beoordeling van de beschikbare klinische gegevens bij kinderen met groeihormoontekort beschreef versnelde groeitempo over twaalf maanden bij de meeste onderzochte kinderen.","kurz_en":"Een beoordeling van de beschikbare klinische gegevens bij kinderen met groeihormoontekort beschreef versnelde groeitempo over twaalf maanden bij de meeste onderzochte kinderen.","quelle":"Prakash & Goa 1999, BioDrugs, PMID 18031173"}],"sicherheit":["De beschikbare studies rapporteerden voornamelijk milde, tijdelijke bijwerkingen.","De oorspronkelijke goedkeuring werd in 2008 ingetrokken om redenen van productie; er was geen veiligheidswaarschuwing achter deze beslissing.","Een mogelijke, inconsistent waargenomen stijging van LH en FSH wordt besproken in de literatuur.","Lange termijn veiligheidsgegevens bij gezonde volwassenen zijn niet beschikbaar."],"sicherheit_en":["De beschikbare studies rapporteerden voornamelijk milde, tijdelijke bijwerkingen.","De oorspronkelijke goedkeuring werd in 2008 ingetrokken om redenen van productie; er was geen veiligheidswaarschuwing achter deze beslissing.","Een mogelijke, inconsistent waargenomen stijging van LH en FSH wordt besproken in de literatuur.","Lange termijn veiligheidsgegevens bij gezonde volwassenen zijn niet beschikbaar."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Sermoreline werd in de VS van 1990 tot 2008 goedgekeurd als medicijn; de goedkeuring werd ingetrokken om redenen van productie. Het wordt momenteel niet als medicijn op de markt gebracht in de EU of de VS en wordt aangeboden als een chemische stof voor onderzoek.","rechtsstatus_en":"Sermoreline werd in de VS van 1990 tot 2008 goedgekeurd als medicijn; de goedkeuring werd ingetrokken om redenen van productie. Het wordt momenteel niet als medicijn op de markt gebracht in de EU of de VS en wordt aangeboden als een chemische stof voor onderzoek.","typischeMg":[5,10],"faq":[{"q":"Was sermoreline ooit een goedgekeurd medicijn","a":"Ja. Sermoreline werd in de VS van 1990 tot 2008 goedgekeurd, eerst als diagnostisch middel, later voor kleine gestalte bij kinderen door groeihormoontekort. De goedkeuring werd ingetrokken om redenen van productie, niet uit veiligheidsbezwaren.","q_en":"Was sermoreline ooit een goedgekeurd medicijn","a_en":"Ja. Sermoreline werd in de VS van 1990 tot 2008 goedgekeurd, eerst als diagnostisch middel, later voor kleine gestalte bij kinderen door groeihormoontekort. De goedkeuring werd ingetrokken om redenen van productie, niet uit veiligheidsbezwaren."},{"q":"Wat is het verschil tussen sermoreline en CJC-1295","a":"Beide zijn GHRH-analogen. Sermoreline bestaat uit de eerste 29 aminozuren van het eigen GHRH van het lichaam zonder verdere modificatie, terwijl CJC-1295 aanvullend gestabiliseerd is en daarom een langere halfwaardetijd heeft.","q_en":"Wat is het verschil tussen sermoreline en CJC-1295","a_en":"Beide zijn GHRH-analogen. Sermoreline bestaat uit de eerste 29 aminozuren van het eigen GHRH van het lichaam zonder verdere modificatie, terwijl CJC-1295 aanvullend gestabiliseerd is en daarom een langere halfwaardetijd heeft."},{"q":"Is sermoreline vandaag beschikbaar als medicijn","a":"Nee. Sinds de marktintrekking in 2008 is sermoreline niet langer beschikbaar als goedgekeurd medicijn in de EU of de VS en wordt het verkocht als een chemische stof voor onderzoek.","q_en":"Is sermoreline vandaag beschikbaar als medicijn","a_en":"Nee. Sinds de marktintrekking in 2008 is sermoreline niet langer beschikbaar als goedgekeurd medicijn in de EU of de VS en wordt het verkocht als een chemische stof voor onderzoek."}],"seo":{"title":"Onderzoeksoverzicht van sermoreline","title_en":"Onderzoeksoverzicht van sermoreline","description":"Sermoreline feitelijk uitgelegd: werkingsmechanisme, historische goedkeuring, onderzoeksdata en huidige juridische status van dit GHRH fragment.","description_en":"Sermoreline feitelijk uitgelegd: werkingsmechanisme, historische goedkeuring, onderzoeksdata en huidige juridische status van dit GHRH fragment."},"demo":false,"steckbrief":{"cas":"86168-78-7","molekulargewicht":"3357.9 g/mol","aminosaeuren":29,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":"oplosbaar in water en verdunde azijnzuur","sequenzLaenge":29,"quellen":["PubChem CID 16132413","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit_en":"oplosbaar in water en verdunde azijnzuur"},"verwandt":["cjc-1295","ipamorelin","tesamorelin","hexarelin"]},{"slug":"tesamorelin","name":"Tesamoreline","synonyme":["Egrifta","TH9507","Egrifta WR"],"kategorie":"Wachstumshormon-Achse","studienlage":"zugelassenes Arzneimittel","kurz":"Een gestabiliseerd GHRH-analoog, goedgekeurd in de VS als het medicijn Egrifta voor het verminderen van viscerale buikvet in HIV-geassocieerde lipodystrofie.","kurz_en":"Een gestabiliseerd GHRH-analoog, goedgekeurd in de VS als het medicijn Egrifta voor het verminderen van viscerale buikvet in HIV-geassocieerde lipodystrofie.","beschreibung":"Tesamoreline is een gestabiliseerd analoog van het volledige 44-aminozuur GHRH. Onder de merknaam Egrifta is het door de US FDA sinds 2010 goedgekeurd voor het verminderen van viscerale buikvet in HIV-geassocieerde lipodystrofie. Dit maakt het het enige peptide in zijn klasse met een afgeronde fase 3 goedkeuringsstudie bij meer dan 800 deelnemers.","beschreibung_en":"Tesamoreline is een gestabiliseerd analoog van het volledige 44-aminozuur GHRH. Onder de merknaam Egrifta is het door de US FDA sinds 2010 goedgekeurd voor het verminderen van viscerale buikvet in HIV-geassocieerde lipodystrofie. Dit maakt het het enige peptide in zijn klasse met een afgeronde fase 3 goedkeuringsstudie bij meer dan 800 deelnemers.","mechanismus":"Tesamoreline bindt aan de GHRH receptor op somatotrofe cellen in de hypofyse, stimuleert de pulserende afgifte van groeihormoon van het lichaam terwijl de somatostatin feedbacklus volledig intact blijft. Het vrijgegeven groeihormoon wordt omgezet in IGF-1 in de lever. Tesamoreline werkt ook relatief selectief op groeihormoonreceptoren in visceraal vetweefsel, waarbij daar hormoongevoelige lipase wordt geactiveerd.","mechanismus_en":"Tesamoreline bindt aan de GHRH receptor op somatotrofe cellen in de hypofyse, stimuleert de pulserende afgifte van groeihormoon van het lichaam terwijl de somatostatin feedbacklus volledig intact blijft. Het vrijgegeven groeihormoon wordt omgezet in IGF-1 in de lever. Tesamoreline werkt ook relatief selectief op groeihormoonreceptoren in visceraal vetweefsel, waarbij daar hormoongevoelige lipase wordt geactiveerd.","evidenz":[{"art":"klinisch","kurz":"In een gerandomiseerde, placebo-gecontroleerde fase 3 studie bij mensen met HIV-geassocieerde vetherverdeling verminderde tesamoreline het viscerale vetweefsel significant meer dan placebo over 26 weken en verhoogde IGF-1 niveaus.","kurz_en":"In een gerandomiseerde, placebo-gecontroleerde fase 3 studie bij mensen met HIV-geassocieerde vetherverdeling verminderde tesamoreline het viscerale vetweefsel significant meer dan placebo over 26 weken en verhoogde IGF-1 niveaus.","quelle":"Falutz et al. 2007, New England Journal of Medicine, PMID 18057338"},{"art":"klinisch","kurz":"Een verdere gerandomiseerde studie bij HIV patiënten met buikvetaccumulatie bevestigde de vermindering van visceraal vetweefsel en toonde aanvullend een afname van levervet.","kurz_en":"Een verdere gerandomiseerde studie bij HIV patiënten met buikvetaccumulatie bevestigde de vermindering van visceraal vetweefsel en toonde aanvullend een afname van levervet.","quelle":"Stanley et al. 2014, JAMA, PMID 25038357"}],"sicherheit":["Het meest voorkomende bijwerking dat in studies werd gerapporteerd was gewrichtspijn bij een deel van de deelnemers.","Vochtretentie in de extremiteiten werd waargenomen bij een kleiner deel van de deelnemers, minder vaak dan bij groeihormoon.","Bloedglucose steeg licht en tijdelijk gemiddeld in studies.","Volgens de productinformatie wordt tesamoreline als contra-indicatie beschouwd bij actieve tumorziekte, hypofyse tumor, zwangerschap of diabetische retinopathie."],"sicherheit_en":["Het meest voorkomende bijwerking dat in studies werd gerapporteerd was gewrichtspijn bij een deel van de deelnemers.","Vochtretentie in de extremiteiten werd waargenomen bij een kleiner deel van de deelnemers, minder vaak dan bij groeihormoon.","Bloedglucose steeg licht en tijdelijk gemiddeld in studies.","Volgens de productinformatie wordt tesamoreline als contra-indicatie beschouwd bij actieve tumorziekte, hypofyse tumor, zwangerschap of diabetische retinopathie."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Tesamoreline is in de VS goedgekeurd onder de merknaam Egrifta sinds 2010 voor een specifieke indicatie in HIV-geassocieerde lipodystrofie. Het is niet goedgekeurd in de EU of Zwitserland, en in de Duitse sprekende landen is het niet praktisch beschikbaar. Buiten de goedgekeurde indicatie wordt elk gebruik als off-label beschouwd.","rechtsstatus_en":"Tesamoreline is in de VS goedgekeurd onder de merknaam Egrifta sinds 2010 voor een specifieke indicatie in HIV-geassocieerde lipodystrofie. Het is niet goedgekeurd in de EU of Zwitserland, en in de Duitse sprekende landen is het niet praktisch beschikbaar. Buiten de goedgekeurde indicatie wordt elk gebruik als off-label beschouwd.","typischeMg":[2,5],"faq":[{"q":"Is tesamoreline een goedgekeurd medicijn","a":"Ja, onder de naam Egrifta sinds 2010 in de VS, maar alleen voor een specifieke indicatie: vermindering van visceraal buikvet in HIV-geassocieerde lipodystrofie. Er is geen goedkeuring in de EU.","q_en":"Is tesamoreline een goedgekeurd medicijn","a_en":"Ja, onder de naam Egrifta sinds 2010 in de VS, maar alleen voor een specifieke indicatie: vermindering van visceraal buikvet in HIV-geassocieerde lipodystrofie. Er is geen goedkeuring in de EU."},{"q":"Bouwt tesamoreline spieren op","a":"Studies tonen een toename van de vetvrije lichaamsmassa, maar een relevant deel hiervan bestaat uit water en bindweefsel. Opmerkelijke spiergroei zonder aanvullende androgenreceptorstimulatie is niet wetenschappelijk gedocumenteerd.","q_en":"Bouwt tesamoreline spieren op","a_en":"Studies tonen een toename van de vetvrije lichaamsmassa, maar een relevant deel hiervan bestaat uit water en bindweefsel. Opmerkelijke spiergroei zonder aanvullende androgenreceptorstimulatie is niet wetenschappelijk gedocumenteerd."},{"q":"Hoe verschilt tesamoreline van andere GHRH-analogen","a":"Tesamoreline is het enige GHRH-analoog met een afgeronde fase 3 goedkeuringsstudie bij meer dan 800 deelnemers en een actieve regelgevende goedkeuring in de VS. sermoreline en CJC-1295 hebben deze status niet bereikt.","q_en":"Hoe verschilt tesamoreline van andere GHRH-analogen","a_en":"Tesamoreline is het enige GHRH-analoog met een afgeronde fase 3 goedkeuringsstudie bij meer dan 800 deelnemers en een actieve regelgevende goedkeuring in de VS. sermoreline en CJC-1295 hebben deze status niet bereikt."}],"seo":{"title":"Onderzoeksoverzicht van tesamoreline","title_en":"Onderzoeksoverzicht van tesamoreline","description":"Tesamoreline (Egrifta) feitelijk uitgelegd: goedkeuringsstatus, werkingsmechanisme, klinische studiegegevens en juridische status buiten de VS.","description_en":"Tesamoreline (Egrifta) feitelijk uitgelegd: goedkeuringsstatus, werkingsmechanisme, klinische studiegegevens en juridische status buiten de VS."},"demo":false,"steckbrief":{"cas":"218949-48-5","molekulargewicht":"5136 g/mol","aminosaeuren":44,"halbwertszeit":"≈ 8 minuten (eliminatie, Egrifta SV productinformatie)","reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":44,"quellen":["PubChem CID 16137828","DailyMed SPL EGRIFTA SV (Tesamorelin), Theratechnologies","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 8 minuten (eliminatie, Egrifta SV productinformatie)","reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["cjc-1295","ipamorelin","sermorelin","igf-1-lr3"]},{"slug":"ghk-cu","name":"GHK-Cu","synonyme":["Glycyl-L-histidyl-L-lysine koper","Koper tripeptide-1"],"kategorie":"Haut & Kosmetik","studienlage":"frühe klinische Studien","kurz":"Een natuurlijk voorkomend koperbindend tripeptide, het meest uitgebreid bestudeerd in huidonderzoek, met aanvullende pre-klinische gegevens over andere weefsels.","kurz_en":"Een natuurlijk voorkomend koperbindend tripeptide, het meest uitgebreid bestudeerd in huidonderzoek, met aanvullende pre-klinische gegevens over andere weefsels.","beschreibung":"GHK-Cu is een drie-aminozuur tripeptide dat natuurlijk voorkomt in het lichaam en een koperion stabiel bindt. Het wordt voornamelijk bestudeerd in cosmetische en dermatologische onderzoek naar collageenvorming en huidvernieuwing. Verder kijken pre-klinisch onderzoek naar mogelijke effecten op ontstekingsprocessen en genexpressie in verschillende weefselmodellen.","beschreibung_en":"GHK-Cu is een drie-aminozuur tripeptide dat natuurlijk voorkomt in het lichaam en een koperion stabiel bindt. Het wordt voornamelijk bestudeerd in cosmetische en dermatologische onderzoek naar collageenvorming en huidvernieuwing. Verder kijken pre-klinisch onderzoek naar mogelijke effecten op ontstekingsprocessen en genexpressie in verschillende weefselmodellen.","mechanismus":"In huidcellen is GHK-Cu beschreven als het verhogen van collageen en elastine synthese en het activeren van fibroblasten, de cellen die bindweefsel opbouwen. In pre-klinische genexpressiemodellen toonde GHK-Cu een contextafhankelijke regulatie van talloze genen die verbonden zijn met weefselherstel, oxidatieve stress en ontsteking. Het omvang van de overdracht van deze genexpressie-effecten naar levende mensen is onderwerp van lopend onderzoek.","mechanismus_en":"In huidcellen is GHK-Cu beschreven als het verhogen van collageen en elastine synthese en het activeren van fibroblasten, de cellen die bindweefsel opbouwen. In pre-klinische genexpressiemodellen toonde GHK-Cu een contextafhankelijke regulatie van talloze genen die verbonden zijn met weefselherstel, oxidatieve stress en ontsteking. Het omvang van de overdracht van deze genexpressie-effecten naar levende mensen is onderwerp van lopend onderzoek.","evidenz":[{"art":"klinisch","kurz":"Een twaalf weken durende toepassingsstudie bij vrouwen met zichtbare tekenen van huidveroudering beschreef een toename van de huid dikte, verminderde rimpeldiepte en een biopsiebevestigde toename van huidcelactiviteit onder een GHK-Cu crème, vergeleken met de baseline.","kurz_en":"Een twaalf weken durende toepassingsstudie bij vrouwen met zichtbare tekenen van huidveroudering beschreef een toename van de huid dikte, verminderde rimpeldiepte en een biopsiebevestigde toename van huidcelactiviteit onder een GHK-Cu crème, vergeleken met de baseline.","quelle":"Finkley et al. 2005, in: Cosmeceuticals and Active Cosmetics: Drugs vs. Cosmetics"},{"art":"preklinisch","kurz":"Een studie in een muismodel van colitis ulcerosa beschreef GHK-Cu dat de intestinale barrièrefunctie ondersteunt via de SIRT1/STAT3-route en ontstekingssignaalmoleculen vermindert.","kurz_en":"Een studie in een muismodel van colitis ulcerosa beschreef GHK-Cu dat de intestinale barrièrefunctie ondersteunt via de SIRT1/STAT3-route en ontstekingssignaalmoleculen vermindert.","quelle":"Mao et al. 2025, Frontiers in Pharmacology, PMID 40672369"}],"sicherheit":["De beschikbare topische studies beschreven geen relevante veiligheidszorgen.","GHK-Cu bevat gebonden koper, bij typische cosmetische concentraties is dit niet geassocieerd met koperoverbelasting.","Voor injecteerbare, systemische toepassing zijn er geen placebo-gecontroleerde menselijke veiligheidsstudies beschikbaar.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"sicherheit_en":["De beschikbare topische studies beschreven geen relevante veiligheidszorgen.","GHK-Cu bevat gebonden koper, bij typische cosmetische concentraties is dit niet geassocieerd met koperoverbelasting.","Voor injecteerbare, systemische toepassing zijn er geen placebo-gecontroleerde menselijke veiligheidsstudies beschikbaar.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"In cosmetische formuleringen wordt koper tripeptide-1 als cosmetisch ingrediënt in de Verenigde Staten vermeld. In de EU en Duitsland bevindt de injecteerbare onderzoeksvorm zich in een juridisch grijs gebied en is het niet goedgekeurd als medicijn.","rechtsstatus_en":"In cosmetische formuleringen wordt koper tripeptide-1 als cosmetisch ingrediënt in de Verenigde Staten vermeld. In de EU en Duitsland bevindt de injecteerbare onderzoeksvorm zich in een juridisch grijs gebied en is het niet goedgekeurd als medicijn.","typischeMg":[],"faq":[{"q":"Is GHK-Cu goedgekeurd in cosmetica?","a":"In de Verenigde Staten wordt koper tripeptide-1 vermeld als cosmetisch ingrediënt. De EU heeft geen vergelijkbare losse goedkeuring, hoewel cosmetische producten wijdverspreid verkocht worden.","q_en":"Is GHK-Cu goedgekeurd in cosmetica?","a_en":"In de Verenigde Staten wordt koper tripeptide-1 vermeld als cosmetisch ingrediënt. De EU heeft geen vergelijkbare losse goedkeuring, hoewel cosmetische producten wijdverspreid verkocht worden."},{"q":"Waar is het sterkste bewijs voor GHK-Cu?","a":"De meest robuuste menselijke gegevens komen uit topische huidstudies. Systemische, injecteerbare toepassing berust voornamelijk op pre-klinische dierlijke en celmodellen.","q_en":"Waar is het sterkste bewijs voor GHK-Cu?","a_en":"De meest robuuste menselijke gegevens komen uit topische huidstudies. Systemische, injecteerbare toepassing berust voornamelijk op pre-klinische dierlijke en celmodellen."},{"q":"Is het koper in GHK-Cu een veiligheidsrisico?","a":"Bij typische cosmetische concentraties wordt dit niet beschreven als een relevant risico. De literatuur beschouwt kopertekort waarschijnlijker dan overbelasting.","q_en":"Is het koper in GHK-Cu een veiligheidsrisico?","a_en":"Bij typische cosmetische concentraties wordt dit niet beschreven als een relevant risico. De literatuur beschouwt kopertekort waarschijnlijker dan overbelasting."}],"seo":{"title":"GHK-Cu: onderzoeksprofiel en bewijs","title_en":"GHK-Cu: onderzoeksprofiel en bewijs","description":"GHK-Cu overzicht: koper tripeptide, mechanisme, huidonderzoek en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext.","description_en":"GHK-Cu overzicht: koper tripeptide, mechanisme, huidonderzoek en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext."},"demo":false,"steckbrief":{"cas":"89030-95-5","molekulargewicht":"402,92 g/mol","aminosaeuren":3,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard, blauwe poeder)","loeslichkeit":null,"sequenzLaenge":3,"quellen":["PubChem CID 71587328","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard, blauwe poeder)"},"verwandt":["bpc-157","tb-500","pentadeca-arginate"]},{"slug":"dihexa","name":"Dihexa","synonyme":["PNB-0408","N-Hexanoyl-Tyr-Ile-(6)aminohexanamide"],"kategorie":"Kognition","studienlage":"präklinisch","kurz":"Een synthetisch angiotensine IV analoog bestudeerd in preklinische ratmodellen van geheugenfunctie, zonder gepubliceerde menselijke gegevens tot op heden.","kurz_en":"Een synthetisch angiotensine IV analoog bestudeerd in preklinische ratmodellen van geheugenfunctie, zonder gepubliceerde menselijke gegevens tot op heden.","beschreibung":"Dihexa is een synthetische peptidomimetiek afgeleid van het eigen angiotensine IV van het lichaam, ontwikkeld in het onderzoeksgroep van Joseph Harding aan Washington State University. Tot op heden is het uitsluitend bestudeerd in preklinische modellen, voornamelijk ratten, in verband met leer- en geheugenprestaties. Er bestaan geen gepubliceerde menselijke studies voor dihexa, dus het veiligheidsprofiel bij mensen is niet onderzocht.","beschreibung_en":"Dihexa is een synthetische peptidomimetiek afgeleid van het eigen angiotensine IV van het lichaam, ontwikkeld in het onderzoeksgroep van Joseph Harding aan Washington State University. Tot op heden is het uitsluitend bestudeerd in preklinische modellen, voornamelijk ratten, in verband met leer- en geheugenprestaties. Er bestaan geen gepubliceerde menselijke studies voor dihexa, dus het veiligheidsprofiel bij mensen is niet onderzocht.","mechanismus":"Dihexa wordt beschreven als een metabolisch gestabiliseerd analoog van angiotensine IV dat oraal beschikbaar is en de bloed-hersenbarrière kan passeren. In tegenstelling tot het eigen angiotensine IV van het lichaam, wordt het in celmodellen gerapporteerd dat het direct bindt aan de hepatocyten groeifactor receptor c-Met, waardoor het wordt voorgesteld dat het dendritische groei en synaptogenese kan triggeren. Deel van het werk dat oorspronkelijk deze mechanismen ondersteunde, is ingetrokken in 2025 vanwege bevestigde beeldmanipulatie, dus het precieze werkingsmechanisme kan niet als wetenschappelijk vastgesteld worden beschouwd.","mechanismus_en":"Dihexa wordt beschreven als een metabolisch gestabiliseerd analoog van angiotensine IV dat oraal beschikbaar is en de bloed-hersenbarrière kan passeren. In tegenstelling tot het eigen angiotensine IV van het lichaam, wordt het in celmodellen gerapporteerd dat het direct bindt aan de hepatocyten groeifactor receptor c-Met, waardoor het wordt voorgesteld dat het dendritische groei en synaptogenese kan triggeren. Deel van het werk dat oorspronkelijk deze mechanismen ondersteunde, is ingetrokken in 2025 vanwege bevestigde beeldmanipulatie, dus het precieze werkingsmechanisme kan niet als wetenschappelijk vastgesteld worden beschouwd.","evidenz":[{"art":"preklinisch","kurz":"In ratten herstelde oraal toegediend dihexa (2 mg/kg) geheugenuitval veroorzaakt door scopolamine in de Morris water maze test en verbeterde het leren bij dieren van 24 maanden.","kurz_en":"In ratten herstelde oraal toegediend dihexa (2 mg/kg) geheugenuitval veroorzaakt door scopolamine in de Morris water maze test en verbeterde het leren bij dieren van 24 maanden.","quelle":"McCoy AT et al. 2013, Journal of Pharmacology and Experimental Therapeutics, PMID 23055539 (This paper has carried an Expression of Concern from the publisher since 2021 over possible image manipulation, no retraction)"},{"art":"preklinisch","kurz":"In een ratmodel van 3-nitropropionzuur-geïnduceerde Huntington-achtige symptomen vertoonde PNB-0408 (dihexa) geen significante verbetering in motorische of neuropathologische eindpunten vergeleken met controledieren.","kurz_en":"In een ratmodel van 3-nitropropionzuur-geïnduceerde Huntington-achtige symptomen vertoonde PNB-0408 (dihexa) geen significante verbetering in motorische of neuropathologische eindpunten vergeleken met controledieren.","quelle":"Wells RG et al. 2024, Journal of Huntington's Disease, Bd. 13, Nr. 1, S. 55-66, PMID 38489193"}],"sicherheit":["Er bestaan geen gepubliceerde menselijke studies voor dihexa, en het veiligheidsprofiel bij mensen is niet onderzocht.","Alle gepubliceerde gegevens tot op heden komen uit dierlijke modellen, voornamelijk ratten, met observatieperiodes van slechts enkele weken.","Een studie uit 2013 over metabolisch gestabiliseerde angiotensine IV analogen heeft sinds 2021 een redactionele Expression of Concern gehad over mogelijke beeldmanipulatie, zonder dat het artikel is ingetrokken.","Een artikel uit 2014 over het onderliggende HGF/c-Met mechanisme is formeel ingetrokken in 2025 nadat een onderzoek gefabriceerde en gemanipuleerde figuren bevestigde.","Lange termijn veiligheidsgegevens, inclusief uit dierstudies, zijn nog niet beschikbaar."],"sicherheit_en":["Er bestaan geen gepubliceerde menselijke studies voor dihexa, en het veiligheidsprofiel bij mensen is niet onderzocht.","Alle gepubliceerde gegevens tot op heden komen uit dierlijke modellen, voornamelijk ratten, met observatieperiodes van slechts enkele weken.","Een studie uit 2013 over metabolisch gestabiliseerde angiotensine IV analogen heeft sinds 2021 een redactionele Expression of Concern gehad over mogelijke beeldmanipulatie, zonder dat het artikel is ingetrokken.","Een artikel uit 2014 over het onderliggende HGF/c-Met mechanisme is formeel ingetrokken in 2025 nadat een onderzoek gefabriceerde en gemanipuleerde figuren bevestigde.","Lange termijn veiligheidsgegevens, inclusief uit dierstudies, zijn nog niet beschikbaar."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Dihexa is nooit in een klinisch goedkeuringsproces voor menselijk gebruik gegaan en is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumgebruik.","rechtsstatus_en":"Dihexa is nooit in een klinisch goedkeuringsproces voor menselijk gebruik gegaan en is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumgebruik.","typischeMg":[],"faq":[{"q":"Zijn er menselijke studies over dihexa","a":"Nee. Alle gepubliceerde gegevens over dihexa tot op heden komen uit dierlijke modellen, voornamelijk ratten. Een veiligheidsprofiel voor menselijk gebruik is niet onderzocht, dus er bestaan noch tolerantie- noch effectiviteitsgegevens bij mensen.","q_en":"Zijn er menselijke studies over dihexa","a_en":"Nee. Alle gepubliceerde gegevens over dihexa tot op heden komen uit dierlijke modellen, voornamelijk ratten. Een veiligheidsprofiel voor menselijk gebruik is niet onderzocht, dus er bestaan noch tolerantie- noch effectiviteitsgegevens bij mensen."},{"q":"Hoe wordt het werkingsmechanisme van dihexa uitgelegd","a":"Dihexa wordt gerapporteerd te binden aan de hepatocyten groeifactor receptor c-Met, een pathway die voorgesteld wordt om synaptogenese in celmodellen te triggeren. Deel van het werk dat dit mechanisme oorspronkelijk ondersteunde is ingetrokken in 2025 vanwege vervalste gegevens.","q_en":"Hoe wordt het werkingsmechanisme van dihexa uitgelegd","a_en":"Dihexa wordt gerapporteerd te binden aan de hepatocyten groeifactor receptor c-Met, een pathway die voorgesteld wordt om synaptogenese in celmodellen te triggeren. Deel van het werk dat dit mechanisme oorspronkelijk ondersteunde is ingetrokken in 2025 vanwege vervalste gegevens."},{"q":"Is dihexa een goedgekeurd medicijn","a":"Nee. Dihexa is nooit een klinisch goedkeuringsproces voor menselijk gebruik ingegaan en is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek.","q_en":"Is dihexa een goedgekeurd medicijn","a_en":"Nee. Dihexa is nooit een klinisch goedkeuringsproces voor menselijk gebruik ingegaan en is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek."}],"seo":{"title":"Dihexa: Onderzoekstatus van het Angiotensine IV Analoog","title_en":"Dihexa: Onderzoekstatus van het Angiotensine IV Analoog","description":"Dihexa feitelijk uitgelegd: oorsprong, werkingsmechanisme, status van preklinische studies en open veiligheidsvragen rond dit onderzoek peptide.","description_en":"Dihexa feitelijk uitgelegd: oorsprong, werkingsmechanisme, status van preklinische studies en open veiligheidsvragen rond dit onderzoek peptide."},"demo":false,"steckbrief":{"cas":"1401708-83-5","molekulargewicht":"504,7 g/mol","aminosaeuren":2,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":2,"quellen":["PubChem CID 129010512","chemverify Katalog 14.09.2026"]},"verwandt":["semax","selank","dsip"]},{"slug":"dsip","name":"DSIP","synonyme":["Delta-slaapinducerend peptide","Delta-slaappeptide"],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Een van de langst bestudeerde neuropeptiden, oorspronkelijk geïsoleerd als een slaapinducerend boodschapper uit de hersenen van slapende konijnen, met een inconsistent geheel van onderzoek tot op heden.","kurz_en":"Een van de langst bestudeerde neuropeptiden, oorspronkelijk geïsoleerd als een slaapinducerend boodschapper uit de hersenen van slapende konijnen, met een inconsistent geheel van onderzoek tot op heden.","beschreibung":"DSIP (delta slaapinducerend peptide) is een nonapeptide dat voor het eerst werd geïsoleerd in 1977 door Schoenenberger en Monnier uit het veneuze hersenbloed van slapende konijnen en benoemd vanwege zijn vermogen om delta-golf EEG-activiteit in dat diermodel te triggeren. Gedurende de daaropvolgende decennia werd het in talloze menselijke proeven over slaap, de stressas en hormoonregulatie bestudeerd. Het oorspronkelijk beschreven slaapbevorderende effect is niet betrouwbaar gereproduceerd in onafhankelijke, strengere studies.","beschreibung_en":"DSIP (delta slaapinducerend peptide) is een nonapeptide dat voor het eerst werd geïsoleerd in 1977 door Schoenenberger en Monnier uit het veneuze hersenbloed van slapende konijnen en benoemd vanwege zijn vermogen om delta-golf EEG-activiteit in dat diermodel te triggeren. Gedurende de daaropvolgende decennia werd het in talloze menselijke proeven over slaap, de stressas en hormoonregulatie bestudeerd. Het oorspronkelijk beschreven slaapbevorderende effect is niet betrouwbaar gereproduceerd in onafhankelijke, strengere studies.","mechanismus":"Het precieze werkingsmechanisme van DSIP blijft onopgelost ondanks decennia van onderzoek. Voorgestelde betrokkenheid omvat een rol in de regulering van de hypothalamus-hypofyse-bijnier as en interacties met GABAerge en opioïde signaalroutes. Er is tot op heden geen specifiek, duidelijk geïdentificeerd receptor voor DSIP beschreven, wat de interpretatie van zijn effecten bemoeilijkt.","mechanismus_en":"Het precieze werkingsmechanisme van DSIP blijft onopgelost ondanks decennia van onderzoek. Voorgestelde betrokkenheid omvat een rol in de regulering van de hypothalamus-hypofyse-bijnier as en interacties met GABAerge en opioïde signaalroutes. Er is tot op heden geen specifiek, duidelijk geïdentificeerd receptor voor DSIP beschreven, wat de interpretatie van zijn effecten bemoeilijkt.","evidenz":[{"art":"preklinisch","kurz":"De oorspronkelijke isolatie uit het hersenbloed van slapende konijnen identificeerde de nonapeptide sequentie en toonde een toename van delta-golf EEG-activiteit in het diermodel na intraventriculaire toediening.","kurz_en":"De oorspronkelijke isolatie uit het hersenbloed van slapende konijnen identificeerde de nonapeptide sequentie en toonde een toename van delta-golf EEG-activiteit in het diermodel na intraventriculaire toediening.","quelle":"Schoenenberger GA, Monnier M 1977, Proceedings of the National Academy of Sciences, Bd. 74(3), S. 1282-1286, PMID 265572"},{"art":"klinisch","kurz":"In een dubbelblind crossover studie bij patiënten met chronische insomnie met polysomnografisch monitoren over vier nachten was de slaapverbetering onder DSIP minimaal vergeleken met placebo.","kurz_en":"In een dubbelblind crossover studie bij patiënten met chronische insomnie met polysomnografisch monitoren over vier nachten was de slaapverbetering onder DSIP minimaal vergeleken met placebo.","quelle":"Monti JM et al. 1987, International Journal of Clinical Pharmacology Research, Bd. 7(2), S. 105-110, PMID 3583493"},{"art":"klinisch","kurz":"Een overzicht dat drie decennia menselijk en dierlijk onderzoek samenvat, concludeert dat het oorspronkelijk postuleerde slaapinducerende effect van DSIP niet consistent bevestigd kon worden in onafhankelijke studies.","kurz_en":"Een overzicht dat drie decennia menselijk en dierlijk onderzoek samenvat, concludeert dat het oorspronkelijk postuleerde slaapinducerende effect van DSIP niet consistent bevestigd kon worden in onafhankelijke studies.","quelle":"Kovalzon VM, Strekalova TV 2006, Journal of Neurochemistry, Bd. 97(2), S. 303-309, PMID 16539679"},{"art":"preklinisch","kurz":"Een preklinische studie uit 2024 onderzocht een DSIP fusiepeptide in een muismodel van farmacologisch geïnduceerde insomnie en beschreef effecten op neurotransmitterniveaus zoals serotonine en dopamine.","kurz_en":"Een preklinische studie uit 2024 onderzocht een DSIP fusiepeptide in een muismodel van farmacologisch geïnduceerde insomnie en beschreef effecten op neurotransmitterniveaus zoals serotonine en dopamine.","quelle":"Mu X et al. 2024, Frontiers in Pharmacology, Bd. 15, Artikel 1439536, PMID 39444618"}],"sicherheit":["Het slaapbevorderende effect beschreven in oudere menselijke studies wordt, volgens de huidige literatuur over reviews, niet als betrouwbaar reproduceerbaar beschouwd.","Veel van de beschikbare menselijke studies dateren uit de jaren 1980 en tonen methodologische zwakheden zoals kleine steekproefgroottes en korte observatieperioden.","In een studie op gezonde vrijwilligers veranderde DSIP infusie de CRH gestimuleerde ACTH en cortisolsecretie niet meetbaar.","Onafhankelijk gereproduceerde, moderne langetermijn menselijke veiligheidsgegevens zijn niet beschikbaar."],"sicherheit_en":["Het slaapbevorderende effect beschreven in oudere menselijke studies wordt, volgens de huidige literatuur over reviews, niet als betrouwbaar reproduceerbaar beschouwd.","Veel van de beschikbare menselijke studies dateren uit de jaren 1980 en tonen methodologische zwakheden zoals kleine steekproefgroottes en korte observatieperioden.","In een studie op gezonde vrijwilligers veranderde DSIP infusie de CRH gestimuleerde ACTH en cortisolsecretie niet meetbaar.","Onafhankelijk gereproduceerde, moderne langetermijn menselijke veiligheidsgegevens zijn niet beschikbaar."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"DSIP is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, waar het uitsluitend wordt verkocht als een chemische stof voor onderzoek.","rechtsstatus_en":"DSIP is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, waar het uitsluitend wordt verkocht als een chemische stof voor onderzoek.","typischeMg":[5,10],"faq":[{"q":"Is het slaapbevorderende effect van DSIP bevestigd in studies","a":"Het bewijs is inconsistent. Vroege studies rapporteerden slaapbevorderende effecten, maar een review uit 2006 concludeerde dat dit effect niet consistent kon worden gereproduceerd in onafhankelijke studies.","q_en":"Is het slaapbevorderende effect van DSIP bevestigd in studies","a_en":"Het bewijs is inconsistent. Vroege studies rapporteerden slaapbevorderende effecten, maar een review uit 2006 concludeerde dat dit effect niet consistent kon worden gereproduceerd in onafhankelijke studies."},{"q":"Waar komt de naam DSIP vandaan","a":"DSIP staat voor delta sleep-inducing peptide. De naam verwijst terug naar de eerste beschrijving in 1977, toen het werd geïsoleerd uit het hersenbloed van slapende konijnen en delta-golf EEG activiteit in dat diermodel triggert.","q_en":"Waar komt de naam DSIP vandaan","a_en":"DSIP staat voor delta sleep-inducing peptide. De naam verwijst terug naar de eerste beschrijving in 1977, toen het werd geïsoleerd uit het hersenbloed van slapende konijnen en delta-golf EEG activiteit in dat diermodel triggert."},{"q":"Is DSIP legaal beschikbaar in Duitsland","a":"DSIP is niet goedgekeurd als medicijn in Duitsland of de EU. Het wordt uitsluitend aangeboden als chemische stof voor onderzoek voor laboratoriumdoeleinden, niet voor menselijk gebruik.","q_en":"Is DSIP legaal beschikbaar in Duitsland","a_en":"DSIP is niet goedgekeurd als medicijn in Duitsland of de EU. Het wordt uitsluitend aangeboden als chemische stof voor onderzoek voor laboratoriumdoeleinden, niet voor menselijk gebruik."}],"seo":{"title":"DSIP: Onderzoekspeptide met inconsistent bewijs","title_en":"DSIP: Onderzoekspeptide met inconsistent bewijs","description":"DSIP overzicht: oorsprong, mechanisme, studiestatus en veiligheidsprofiel van een van de langst bestudeerde slaapeptiden.","description_en":"DSIP overzicht: oorsprong, mechanisme, studiestatus en veiligheidsprofiel van een van de langst bestudeerde slaapeptiden."},"demo":false,"steckbrief":{"cas":"62568-57-4","molekulargewicht":"848,8 g/mol","aminosaeuren":9,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":9,"quellen":["PubChem CID 68816","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["selank","semax","dihexa"]},{"slug":"selank","name":"Selank","synonyme":[],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Een synthetisch heptapeptide analoog van het eigen tuftsin van het lichaam, bestudeerd in onderzoek naar angstregulatie en cognitieve functie.","kurz_en":"Een synthetisch heptapeptide analoog van het eigen tuftsin van het lichaam, bestudeerd in onderzoek naar angstregulatie en cognitieve functie.","beschreibung":"Selank is een heptapeptide afgeleid van het eigen tetrapeptide tuftsin van het lichaam, oorspronkelijk ontwikkeld in Rusland als een anxiolytisch middel. Onderzoek koppelt het aan angstregulerende en licht cognitieondersteunende effecten, zonder de sedatie die typisch is voor benzodiazepinen.","beschreibung_en":"Selank is een heptapeptide afgeleid van het eigen tetrapeptide tuftsin van het lichaam, oorspronkelijk ontwikkeld in Rusland als een anxiolytisch middel. Onderzoek koppelt het aan angstregulerende en licht cognitieondersteunende effecten, zonder de sedatie die typisch is voor benzodiazepinen.","mechanismus":"Selank wordt beschreven als het remmen van enkephalinases, de enzymen die de eigen enkephalines van het lichaam afbreken, waardoor hun niveaus langer hoog blijven. Het is ook gekoppeld aan modulatie van de GABA receptor op een bindingsplaats die afwijkt van benzodiazepinen, en aan indirecte effecten op het dopamine systeem via de enkephalinroute.","mechanismus_en":"Selank wordt beschreven als het remmen van enkephalinases, de enzymen die de eigen enkephalines van het lichaam afbreken, waardoor hun niveaus langer hoog blijven. Het is ook gekoppeld aan modulatie van de GABA receptor op een bindingsplaats die afwijkt van benzodiazepinen, en aan indirecte effecten op het dopamine systeem via de enkephalinroute.","evidenz":[{"art":"klinisch","kurz":"Een gerandomiseerd onderzoek bij 62 personen met algemene angststoornis of neurasthenie vergelijkt het anxiolytische effect van selank met medazepam, met aanvullend waargenomen verbeteringen in energie en concentratie zonder sedatie.","kurz_en":"Een gerandomiseerd onderzoek bij 62 personen met algemene angststoornis of neurasthenie vergelijkt het anxiolytische effect van selank met medazepam, met aanvullend waargenomen verbeteringen in energie en concentratie zonder sedatie.","quelle":"Zozulya AA et al. 2008, Bjulleten Eksperimentalnoj Biologii i Mediciny, PMID 18454096"},{"art":"klinisch","kurz":"In een fMRI-studie met 52 gezonde deelnemers was de toediening van selank geassocieerd met veranderde functionele connectiviteit tussen de rechteramygdala en de rechter temporale cortex, meetbaar al vanaf 5 minuten na toediening.","kurz_en":"In een fMRI-studie met 52 gezonde deelnemers was de toediening van selank geassocieerd met veranderde functionele connectiviteit tussen de rechteramygdala en de rechter temporale cortex, meetbaar al vanaf 5 minuten na toediening.","quelle":"Panikratova KR et al. 2020, Doklady Biological Sciences, Bd. 490, S. 9-11"}],"sicherheit":["Beschikbare onderzoeksliteratuur beschrijft milde, transiënte effecten zoals neussirritatie bij intranasale toediening.","Gezamenlijk gebruik met benzodiazepinen wordt in de literatuur besproken vanwege mogelijke wederzijdse receptorinteractie.","Robuuste langetermijnveiligheidsgegevens uit onafhankelijke studies uitgevoerd buiten Rusland zijn nog niet beschikbaar."],"sicherheit_en":["Beschikbare onderzoeksliteratuur beschrijft milde, transiënte effecten zoals neussirritatie bij intranasale toediening.","Gezamenlijk gebruik met benzodiazepinen wordt in de literatuur besproken vanwege mogelijke wederzijdse receptorinteractie.","Robuuste langetermijnveiligheidsgegevens uit onafhankelijke studies uitgevoerd buiten Rusland zijn nog niet beschikbaar."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Selank is goedgekeurd als anxiolytikum in Rusland, maar is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, waar het uitsluitend wordt verkocht als een chemische stof voor onderzoek.","rechtsstatus_en":"Selank is goedgekeurd als anxiolytikum in Rusland, maar is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, waar het uitsluitend wordt verkocht als een chemische stof voor onderzoek.","typischeMg":[5,10],"faq":[{"q":"Is selank hetzelfde als een benzodiazepine?","a":"Nee. Beide werken op het GABA systeem op verschillende manieren. Selank bindt op een andere plaats en vertoonde geen sedatief of afhankelijkheidspotentieel in studies, in tegenstelling tot klassieke benzodiazepinen.","q_en":"Is selank hetzelfde als een benzodiazepine?","a_en":"Nee. Beide werken op het GABA systeem op verschillende manieren. Selank bindt op een andere plaats en vertoonde geen sedatief of afhankelijkheidspotentieel in studies, in tegenstelling tot klassieke benzodiazepinen."},{"q":"Waar komt selank vandaan?","a":"Selank is ontwikkeld bij de Russische Academie van Wetenschappen uit het eigen peptide tuftsin van het lichaam, met een stabiliserende toevoeging voor een langere duur in het lichaam.","q_en":"Waar komt selank vandaan?","a_en":"Selank is ontwikkeld bij de Russische Academie van Wetenschappen uit het eigen peptide tuftsin van het lichaam, met een stabiliserende toevoeging voor een langere duur in het lichaam."},{"q":"Is selank legaal verkrijgbaar in Duitsland?","a":"Selank is niet goedgekeurd als medicijn in Duitsland of de EU. Het wordt uitsluitend aangeboden als chemische stof voor onderzoek voor laboratoriumdoeleinden, niet voor menselijk gebruik.","q_en":"Is selank legaal verkrijgbaar in Duitsland?","a_en":"Selank is niet goedgekeurd als medicijn in Duitsland of de EU. Het wordt uitsluitend aangeboden als chemische stof voor onderzoek voor laboratoriumdoeleinden, niet voor menselijk gebruik."}],"seo":{"title":"Selank: Onderzoekspeptide voor Angstregulatie","title_en":"Selank: Onderzoekspeptide voor Angstregulatie","description":"Selank overzicht: oorsprong, mechanisme, onderzoeksstatus en veiligheidsprofiel van een onderzoekspeptide bestudeerd voor angstregulatie en cognitie.","description_en":"Selank overzicht: oorsprong, mechanisme, onderzoeksstatus en veiligheidsprofiel van een onderzoekspeptide bestudeerd voor angstregulatie en cognitie."},"demo":false,"steckbrief":{"cas":"129954-34-3","molekulargewicht":"751,9 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 11765600","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["semax","epitalon","dihexa"]},{"slug":"semax","name":"Semax","synonyme":[],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Een synthetisch ACTH-afgeleid heptapeptide, goedgekeurd in Rusland voor neuroprotectie en bestudeerd in onderzoek naar cognitie en stressadaptatie.","kurz_en":"Een synthetisch ACTH-afgeleid heptapeptide, goedgekeurd in Rusland voor neuroprotectie en bestudeerd in onderzoek naar cognitie en stressadaptatie.","beschreibung":"Semax is een heptapeptide afgeleid van het ACTH(4-10) fragment van het stresshormoon ACTH, goedgekeurd als medicijn voor ischemische beroerte in Rusland. Onderzoek onderzoekt het ook in relatie tot neuroplasticiteit en cognitieve functie, zonder de cortisol as te activeren.","beschreibung_en":"Semax is een heptapeptide afgeleid van het ACTH(4-10) fragment van het stresshormoon ACTH, goedgekeurd als medicijn voor ischemische beroerte in Rusland. Onderzoek onderzoekt het ook in relatie tot neuroplasticiteit en cognitieve functie, zonder de cortisol as te activeren.","mechanismus":"Semax wordt beschreven als het opreguleren van BDNF en zijn receptor TrkB, wat verbonden is met neuronale plasticiteit. Als ACTH-afgeleide bindt het ook aan melanocortine receptoren, wat dopamine, serotonine en noradrenaline niveaus kan beïnvloeden. Binding aan de mu-opioïde receptor, beschreven in 2025, is verbonden met antioxidanteffecten.","mechanismus_en":"Semax wordt beschreven als het opreguleren van BDNF en zijn receptor TrkB, wat verbonden is met neuronale plasticiteit. Als ACTH-afgeleide bindt het ook aan melanocortine receptoren, wat dopamine, serotonine en noradrenaline niveaus kan beïnvloeden. Binding aan de mu-opioïde receptor, beschreven in 2025, is verbonden met antioxidanteffecten.","evidenz":[{"art":"preklinisch","kurz":"In een ratstudie verhoogde één intranasale toediening van semax de hippocampus BDNF eiwitniveaus met 1,4-voud en TrkB fosforylering met 1,6-voud.","kurz_en":"In een ratstudie verhoogde één intranasale toediening van semax de hippocampus BDNF eiwitniveaus met 1,4-voud en TrkB fosforylering met 1,6-voud.","quelle":"PubMed ID 14556513"},{"art":"klinisch","kurz":"In dezelfde fMRI-studie met 52 gezonde deelnemers vertoonde semax ook veranderde functionele connectiviteit tussen de amygdala en de temporale cortex, met effecten die deels onderscheidbaar waren van selank.","kurz_en":"In dezelfde fMRI-studie met 52 gezonde deelnemers vertoonde semax ook veranderde functionele connectiviteit tussen de amygdala en de temporale cortex, met effecten die deels onderscheidbaar waren van selank.","quelle":"Panikratova KR et al. 2020, Doklady Biological Sciences, Bd. 490, S. 9-11"}],"sicherheit":["Dierstudies hebben tot nu toe geen ernstige toxische effecten gerapporteerd.","Een in vitro interactie met koperafhankelijke enzymen is beschreven, de klinische relevantie is nog niet vastgesteld.","Onafhankelijke Westerse langetermijn menselijke veiligheidsgegevens zijn nog niet beschikbaar."],"sicherheit_en":["Dierstudies hebben tot nu toe geen ernstige toxische effecten gerapporteerd.","Een in vitro interactie met koperafhankelijke enzymen is beschreven, de klinische relevantie is nog niet vastgesteld.","Onafhankelijke Westerse langetermijn menselijke veiligheidsgegevens zijn nog niet beschikbaar."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Semax is goedgekeurd als medicijn voor neuroprotectie in Rusland, maar is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, waar het uitsluitend wordt verkocht als een chemische stof voor onderzoek.","rechtsstatus_en":"Semax is goedgekeurd als medicijn voor neuroprotectie in Rusland, maar is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, waar het uitsluitend wordt verkocht als een chemische stof voor onderzoek.","typischeMg":[10,30],"faq":[{"q":"Werkt semax als een klassiek nootrope?","a":"Onderzoek verbindt semax voornamelijk aan neuroprotectieve en BDNF gerelateerde effecten, minder aan een acute focus effect zoals klassieke stimulerende middelen.","q_en":"Werkt semax als een klassiek nootrope?","a_en":"Onderzoek verbindt semax voornamelijk aan neuroprotectieve en BDNF gerelateerde effecten, minder aan een acute focus effect zoals klassieke stimulerende middelen."},{"q":"Is semax hetzelfde als selank?","a":"Nee, beide zijn gerelateerde Russische peptiden met verschillende oorsprongen. Semax is afgeleid van ACTH en is voornamelijk verbonden met neuroprotectie, selank van tuftsin en voornamelijk verbonden met angstregulatie.","q_en":"Is semax hetzelfde als selank?","a_en":"Nee, beide zijn gerelateerde Russische peptiden met verschillende oorsprongen. Semax is afgeleid van ACTH en is voornamelijk verbonden met neuroprotectie, selank van tuftsin en voornamelijk verbonden met angstregulatie."},{"q":"Is semax legaal verkrijgbaar in Duitsland?","a":"Semax is niet goedgekeurd als medicijn in Duitsland of de EU en wordt uitsluitend aangeboden als chemische stof voor onderzoek voor laboratoriumdoeleinden, niet voor menselijk gebruik.","q_en":"Is semax legaal verkrijgbaar in Duitsland?","a_en":"Semax is niet goedgekeurd als medicijn in Duitsland of de EU en wordt uitsluitend aangeboden als chemische stof voor onderzoek voor laboratoriumdoeleinden, niet voor menselijk gebruik."}],"seo":{"title":"Semax: ACTH Onderzoekspeptide voor Neuroprotectie","title_en":"Semax: ACTH Onderzoekspeptide voor Neuroprotectie","description":"Semax overzicht: oorsprong, mechanisme, studiestatus en veiligheidsprofiel van een onderzoekspeptide die wordt bestudeerd voor neuroprotectie en cognitie.","description_en":"Semax overzicht: oorsprong, mechanisme, studiestatus en veiligheidsprofiel van een onderzoekspeptide die wordt bestudeerd voor neuroprotectie en cognitie."},"demo":false,"steckbrief":{"cas":"80714-61-0","molekulargewicht":"813,9 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 9811102","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["selank","epitalon","dsip"]},{"slug":"kpv","name":"KPV","synonyme":["Lys-Pro-Val","alpha-MSH(11-13)"],"kategorie":"Immunsystem","studienlage":"präklinisch","kurz":"Een drie-aminozuurfragment van alpha-MSH, bestudeerd in dierlijke modellen voor ontstekingsremmende eigenschappen in de darm en op de huid.","kurz_en":"Een drie-aminozuurfragment van alpha-MSH, bestudeerd in dierlijke modellen voor ontstekingsremmende eigenschappen in de darm en op de huid.","beschreibung":"KPV is een tripeptide gemaakt van de aminozuren lysine, proline en valine, afgeleid van het C-terminale einde van het hormoon alpha-MSH. Het behoort tot de kleinste peptiden die worden bestudeerd in inflammatoire onderzoek, met een focus op dierlijke modellen van chronische inflammatoire darmziekte en huidontsteking. Menselijke studies zijn nog niet beschikbaar.","beschreibung_en":"KPV is een tripeptide gemaakt van de aminozuren lysine, proline en valine, afgeleid van het C-terminale einde van het hormoon alpha-MSH. Het behoort tot de kleinste peptiden die worden bestudeerd in inflammatoire onderzoek, met een focus op dierlijke modellen van chronische inflammatoire darmziekte en huidontsteking. Menselijke studies zijn nog niet beschikbaar.","mechanismus":"In preklinische modellen wordt een ontstekingsremmend effect beschreven dat onafhankelijk van de melanocortine receptor werkt en in plaats daarvan berust op opname in darmcellen via de peptide transporter PepT1. Daar wordt de inhibitie van NF-κB activatie beschreven, een centraal schakel in de inflammatoire respons. De exacte mechanismen bij mensen zijn niet bestudeerd.","mechanismus_en":"In preklinische modellen wordt een ontstekingsremmend effect beschreven dat onafhankelijk van de melanocortine receptor werkt en in plaats daarvan berust op opname in darmcellen via de peptide transporter PepT1. Daar wordt de inhibitie van NF-κB activatie beschreven, een centraal schakel in de inflammatoire respons. De exacte mechanismen bij mensen zijn niet bestudeerd.","evidenz":[{"art":"preklinisch","kurz":"Een studie in twee muizenmodellen van colitis beschreef een snellere herstel van het lichaamsgewicht en merkbaar verminderde inflammatoire infiltraten in het darmweefsel onder KPV vergeleken met onbehandelde dieren.","kurz_en":"Een studie in twee muizenmodellen van colitis beschreef een snellere herstel van het lichaamsgewicht en merkbaar verminderde inflammatoire infiltraten in het darmweefsel onder KPV vergeleken met onbehandelde dieren.","quelle":"Kannengiesser et al. 2008, Inflammatory Bowel Diseases, PMID 18092346"},{"art":"preklinisch","kurz":"Een studie toonde aan dat het ontstekingsremmende effect van KPV in het muizenmodel wordt gemedieerd door opname via de peptide transporter PepT1 in plaats van de melanocortine receptor.","kurz_en":"Een studie toonde aan dat het ontstekingsremmende effect van KPV in het muizenmodel wordt gemedieerd door opname via de peptide transporter PepT1 in plaats van de melanocortine receptor.","quelle":"Dalmasso et al. 2008, Gastroenterology, PMID 18061177"},{"art":"preklinisch","kurz":"Een studie met hyaluronic-zuur gefunctionaliseerde nanodeeltjes voor gerichte orale colonafgifte van KPV beschreef een significante vermindering van ontsteking bij muizen met colitis vergeleken met onbehandeld KPV.","kurz_en":"Een studie met hyaluronic-zuur gefunctionaliseerde nanodeeltjes voor gerichte orale colonafgifte van KPV beschreef een significante vermindering van ontsteking bij muizen met colitis vergeleken met onbehandeld KPV.","quelle":"Xiao et al. 2017, Molecular Therapy, PMID 28143741"}],"sicherheit":["Menselijke veiligheidsstudies op KPV zijn nog niet beschikbaar, al het bewijs komt uit cel- en dierlijke modellen.","Er zijn geen ernstige bijwerkingen gerapporteerd in de beschikbare dierstudies.","Interacties met andere stoffen zijn niet bestudeerd bij mensen.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"sicherheit_en":["Menselijke veiligheidsstudies op KPV zijn nog niet beschikbaar, al het bewijs komt uit cel- en dierlijke modellen.","Er zijn geen ernstige bijwerkingen gerapporteerd in de beschikbare dierstudies.","Interacties met andere stoffen zijn niet bestudeerd bij mensen.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"KPV is niet toegelaten als geneesmiddel in Duitsland, de EU of de Verenigde Staten en is niet geclassificeerd als voedingsmiddel. Het wordt uitsluitend verkocht als chemische stof voor onderzoek.","rechtsstatus_en":"KPV is niet toegelaten als geneesmiddel in Duitsland, de EU of de Verenigde Staten en is niet geclassificeerd als voedingsmiddel. Het wordt uitsluitend verkocht als chemische stof voor onderzoek.","typischeMg":[],"faq":[{"q":"Waar komt KPV vandaan?","a":"KPV is een fragment van het hormoon alpha-MSH, gemaakt van de drie aminozuren lysine, proline en valine.","q_en":"Waar komt KPV vandaan?","a_en":"KPV is een fragment van het hormoon alpha-MSH, gemaakt van de drie aminozuren lysine, proline en valine."},{"q":"Werkt KPV via de melanocortine receptor?","a":"Nee. In dierlijke modellen wordt het ontstekingsremmende effect beschreven onafhankelijk van de melanocortine receptor, in plaats daarvan berust het op de transporter PepT1.","q_en":"Werkt KPV via de melanocortine receptor?","a_en":"Nee. In dierlijke modellen wordt het ontstekingsremmende effect beschreven onafhankelijk van de melanocortine receptor, in plaats daarvan berust het op de transporter PepT1."},{"q":"Zijn er menselijke studies over KPV?","a":"Nee, tot op heden bestaan alleen cel- en dierstudies, voornamelijk over inflammatoire darmziekte.","q_en":"Zijn er menselijke studies over KPV?","a_en":"Nee, tot op heden bestaan alleen cel- en dierstudies, voornamelijk over inflammatoire darmziekte."}],"seo":{"title":"KPV: onderzoeksprofiel en bewijs","title_en":"KPV: onderzoeksprofiel en bewijs","description":"KPV overzicht: oorsprong uit alpha-MSH, mechanisme, preklinisch bewijs en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext.","description_en":"KPV overzicht: oorsprong uit alpha-MSH, mechanisme, preklinisch bewijs en veiligheidsprofiel, feitelijk gepresenteerd voor de onderzoekscontext."},"demo":false,"steckbrief":{"cas":"67727-97-3","molekulargewicht":"342,43 g/mol","aminosaeuren":3,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":3,"quellen":["PubChem CID 125672","chemverify Katalog 14.09.2026"]},"verwandt":["ll-37","thymosin-alpha-1","bpc-157"]},{"slug":"ll-37","name":"LL-37","synonyme":["Cathelicidin","hCAP18(134-170)","Mens Cathelicidin"],"kategorie":"Immunsystem","studienlage":"klinisch untersucht","kurz":"Een natuurlijk voorkomend antimicrobieel peptide bestaande uit 37 aminozuren dat de huid en slijmvliezen beschermt, onderzocht in klinische proeven voor wondgenezing.","kurz_en":"Een natuurlijk voorkomend antimicrobieel peptide bestaande uit 37 aminozuren dat de huid en slijmvliezen beschermt, onderzocht in klinische proeven voor wondgenezing.","beschreibung":"LL-37 is het enige bekende lid van de cathelicidine peptidefamilie bij mensen en wordt geproduceerd door immuuncellen evenals huid- en slijmvliezen als reactie op letsel of infectie. Het wordt gegenereerd door afsplitsing van het precursor eiwit hCAP18. Klinisch onderzoek heeft zich voornamelijk gericht op topische toepassing voor moeilijk te genezen wonden, zoals veneuze beenulcera en diabetische voetulcera.","beschreibung_en":"LL-37 is het enige bekende lid van de cathelicidine peptidefamilie bij mensen en wordt geproduceerd door immuuncellen evenals huid- en slijmvliezen als reactie op letsel of infectie. Het wordt gegenereerd door afsplitsing van het precursor eiwit hCAP18. Klinisch onderzoek heeft zich voornamelijk gericht op topische toepassing voor moeilijk te genezen wonden, zoals veneuze beenulcera en diabetische voetulcera.","mechanismus":"LL-37 dringt door de bacteriële celmembranen binnen en verstoort hun integriteit, wat een direct antimicrobieel effect tegen een breed scala aan pathogenen produceert. Aanvullende immunomodulerende effecten worden beschreven, waaronder de werving van immuuncellen naar de wondplaats en de promotie van angiogenese. Endogene productie kan worden versterkt door bepaalde stimuli zoals vitamine D-analogen.","mechanismus_en":"LL-37 dringt door de bacteriële celmembranen binnen en verstoort hun integriteit, wat een direct antimicrobieel effect tegen een breed scala aan pathogenen produceert. Aanvullende immunomodulerende effecten worden beschreven, waaronder de werving van immuuncellen naar de wondplaats en de promotie van angiogenese. Endogene productie kan worden versterkt door bepaalde stimuli zoals vitamine D-analogen.","evidenz":[{"art":"klinisch","kurz":"Een gerandomiseerde, placebo-gecontroleerde eerste-in-human proef bij 34 patiënten met moeilijk te genezen veneuze beenulcera beschreef een ongeveer 3- tot 6-voudig snellere genezingssnelheid onder de twee lagere LL-37 concentraties vergeleken met placebo.","kurz_en":"Een gerandomiseerde, placebo-gecontroleerde eerste-in-human proef bij 34 patiënten met moeilijk te genezen veneuze beenulcera beschreef een ongeveer 3- tot 6-voudig snellere genezingssnelheid onder de twee lagere LL-37 concentraties vergeleken met placebo.","quelle":"Grönberg et al. 2014, Wound Repair and Regeneration, PMID 25041740"},{"art":"klinisch","kurz":"Een gerandomiseerde dubbelblind proef bij patiënten met diabetische voetulcera onderzocht een LL-37-houdende crème en beschreef effecten op bacteriële kolonisatie, ontstekingsmarkers en genezingssnelheid vergeleken met placebo.","kurz_en":"Een gerandomiseerde dubbelblind proef bij patiënten met diabetische voetulcera onderzocht een LL-37-houdende crème en beschreef effecten op bacteriële kolonisatie, ontstekingsmarkers en genezingssnelheid vergeleken met placebo.","quelle":"Miranda et al. 2023, Archives of Dermatological Research, PMID 37480520"},{"art":"klinisch","kurz":"Een studie in de menselijke huid beschreef dat de endogene productie van hCAP18/LL-37 toeneemt na letsel en verder kan worden versterkt door topische toepassing van het vitamine D-analoog calcipotriol.","kurz_en":"Een studie in de menselijke huid beschreef dat de endogene productie van hCAP18/LL-37 toeneemt na letsel en verder kan worden versterkt door topische toepassing van het vitamine D-analoog calcipotriol.","quelle":"Heilborn et al. 2010, Experimental Dermatology, PMID 19878298"}],"sicherheit":["In de beschikbare gerandomiseerde proeven werd topische toepassing van LL-37 beschreven als veilig en goed verdragen, zonder ernstige bijwerkingen.","De studiepopulaties waren elk klein, grotere placebo-gecontroleerde proeven met meer deelnemers zijn nog in behandeling.","Systemische vormen van toepassing en langetermijn menselijke veiligheid zijn niet onderzocht tot een vergelijkbare mate als topische toepassing.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"sicherheit_en":["In de beschikbare gerandomiseerde proeven werd topische toepassing van LL-37 beschreven als veilig en goed verdragen, zonder ernstige bijwerkingen.","De studiepopulaties waren elk klein, grotere placebo-gecontroleerde proeven met meer deelnemers zijn nog in behandeling.","Systemische vormen van toepassing en langetermijn menselijke veiligheid zijn niet onderzocht tot een vergelijkbare mate als topische toepassing.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"LL-37 is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, en het wordt niet geclassificeerd als een voedingsmiddel. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek, klinische onderzoeksformuleringen van LL-37 zijn gekoppeld aan individuele studieprogramma's.","rechtsstatus_en":"LL-37 is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, en het wordt niet geclassificeerd als een voedingsmiddel. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek, klinische onderzoeksformuleringen van LL-37 zijn gekoppeld aan individuele studieprogramma's.","typischeMg":[],"faq":[{"q":"Is LL-37 een natuurlijk voorkomend menselijk peptide?","a":"Ja. Het is het enige bekende menselijke cathelicidine peptide en wordt geproduceerd door immuuncellen, huid- en slijmvliezen, vooral tijdens letsel of infectie.","q_en":"Is LL-37 een natuurlijk voorkomend menselijk peptide?","a_en":"Ja. Het is het enige bekende menselijke cathelicidine peptide en wordt geproduceerd door immuuncellen, huid- en slijmvliezen, vooral tijdens letsel of infectie."},{"q":"Zijn er klinische studies over LL-37?","a":"Ja, verschillende gerandomiseerde studies hebben de topische toepassing op moeilijk te genezen wonden zoals veneuze beenulcera en diabetische voetulcera onderzocht, met voornamelijk positieve veiligheidsresultaten.","q_en":"Zijn er klinische studies over LL-37?","a_en":"Ja, verschillende gerandomiseerde studies hebben de topische toepassing op moeilijk te genezen wonden zoals veneuze beenulcera en diabetische voetulcera onderzocht, met voornamelijk positieve veiligheidsresultaten."},{"q":"Werkt LL-37 alleen als antimicrobieel middel?","a":"Nee, naast zijn directe effect op bacteriële membranen worden immunomodulerende effecten zoals rekrutering van immuuncellen en bevordering van bloedvatvorming ook beschreven.","q_en":"Werkt LL-37 alleen als antimicrobieel middel?","a_en":"Nee, naast zijn directe effect op bacteriële membranen worden immunomodulerende effecten zoals rekrutering van immuuncellen en bevordering van bloedvatvorming ook beschreven."}],"seo":{"title":"LL-37: onderzoeksprofiel en bewijs","title_en":"LL-37: onderzoeksprofiel en bewijs","description":"LL-37 overzicht: natuurlijk voorkomend cathelicidine, mechanisme, klinisch bewijs op wondgenezing en veiligheidsprofiel in de onderzoekscontext.","description_en":"LL-37 overzicht: natuurlijk voorkomend cathelicidine, mechanisme, klinisch bewijs op wondgenezing en veiligheidsprofiel in de onderzoekscontext."},"demo":false,"steckbrief":{"cas":"154947-66-7","molekulargewicht":"4493 g/mol","aminosaeuren":37,"halbwertszeit":null,"reinheitsstandard":"≥ 95 % (HPLC, commercieel standaard)","loeslichkeit":"oplosbaar in water en DMSO","sequenzLaenge":37,"quellen":["PubChem CID 16198951","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 95 % (HPLC, commercieel standaard)","loeslichkeit_en":"oplosbaar in water en DMSO"},"verwandt":["kpv","thymosin-alpha-1","bpc-157"]},{"slug":"thymosin-alpha-1","name":"Thymosine alfa 1","synonyme":["Tα1","Zadaxin (merknaam)"],"kategorie":"Immunsystem","studienlage":"zugelassenes Arzneimittel","kurz":"Een natuurlijk voorkomend thymusafgeleid immuunpeptide, goedgekeurd als medicijn in meer dan 35 landen, hoewel het momenteel niet in Duitsland, Oostenrijk of Zwitserland beschikbaar is.","kurz_en":"Een natuurlijk voorkomend thymusafgeleid immuunpeptide, goedgekeurd als medicijn in meer dan 35 landen, hoewel het momenteel niet in Duitsland, Oostenrijk of Zwitserland beschikbaar is.","beschreibung":"Thymosine alfa 1 is een 28-aminozuurpeptide oorspronkelijk geïsoleerd uit de thymusklier, het centrale orgaan waar T-cellen rijpen. Het werkt als immuunmodulator en wordt gebruikt zowel in klinisch onderzoek als, onder de handelsnaam Zadaxin, als een goedgekeurd medicijn voor bepaalde immuuncondities. Onderzoeksgebieden omvatten chronische virale infecties, de immuunrespons op vaccinatie en een ondersteunende rol in oncologie.","beschreibung_en":"Thymosine alfa 1 is een 28-aminozuurpeptide oorspronkelijk geïsoleerd uit de thymusklier, het centrale orgaan waar T-cellen rijpen. Het werkt als immuunmodulator en wordt gebruikt zowel in klinisch onderzoek als, onder de handelsnaam Zadaxin, als een goedgekeurd medicijn voor bepaalde immuuncondities. Onderzoeksgebieden omvatten chronische virale infecties, de immuunrespons op vaccinatie en een ondersteunende rol in oncologie.","mechanismus":"Het effect wordt voornamelijk beschreven via Toll-like receptoren op immuuncellen, moleculaire herkenningsstructuren die reageren op pathogenen. Dit activeert paden zoals NF-κB en interferonproductie, waarbij zowel het aangeboren als het adaptieve immuunsysteem tegelijkertijd wordt betrokken. Beschreven effecten omvatten verhoogde activiteit van T-cellen en natuurlijke killercellen, evenals verbeterde antilichaamproductie.","mechanismus_en":"Het effect wordt voornamelijk beschreven via Toll-like receptoren op immuuncellen, moleculaire herkenningsstructuren die reageren op pathogenen. Dit activeert paden zoals NF-κB en interferonproductie, waarbij zowel het aangeboren als het adaptieve immuunsysteem tegelijkertijd wordt betrokken. Beschreven effecten omvatten verhoogde activiteit van T-cellen en natuurlijke killercellen, evenals verbeterde antilichaamproductie.","evidenz":[{"art":"klinisch","kurz":"Een retrospectieve review van 76 patiënten met ernstige COVID-19 in twee ziekenhuizen beschreef een lagere mortaliteit onder thymosine alfa 1 vergeleken met de onbehandelde groep, vergezeld van een herstel van T-celcounts.","kurz_en":"Een retrospectieve review van 76 patiënten met ernstige COVID-19 in twee ziekenhuizen beschreef een lagere mortaliteit onder thymosine alfa 1 vergeleken met de onbehandelde groep, vergezeld van een herstel van T-celcounts.","quelle":"Liu et al. 2020, Clinical Infectious Diseases"},{"art":"klinisch","kurz":"Een gerandomiseerde studie bij 42 patiënten met niet-kleincellige longkanker na bestraling beschreef een snellere normalisatie van T-celfunctie onder thymosine alfa 1 vergeleken met placebo, samen met een overlevingsvoordeel, het meest uitgesproken bij patiënten met kleinere tumoren.","kurz_en":"Een gerandomiseerde studie bij 42 patiënten met niet-kleincellige longkanker na bestraling beschreef een snellere normalisatie van T-celfunctie onder thymosine alfa 1 vergeleken met placebo, samen met een overlevingsvoordeel, het meest uitgesproken bij patiënten met kleinere tumoren.","quelle":"Schulof et al. 1985, Journal of Biological Response Modifiers, PMID 3998766"}],"sicherheit":["Grote veiligheidsdatabases die duizenden patiënten omvatten, beschrijven voornamelijk milde, tijdelijke reacties op de injectieplaats en lichte vermoeidheid.","Zeldzame rapporten omvatten allergische huidreacties en een tijdelijke opflakkering van bestaande auto-immuuncondities.","Gezamenlijk gebruik van immunosuppressieve medicatie wordt als contra-indicatie vermeld in de productinformatie, aangezien de effecten in tegengestelde richtingen werken.","De productinformatie adviseert voorzichtigheid bij actieve orgaantransplantatie en actieve auto-immuunziekte."],"sicherheit_en":["Grote veiligheidsdatabases die duizenden patiënten omvatten, beschrijven voornamelijk milde, tijdelijke reacties op de injectieplaats en lichte vermoeidheid.","Zeldzame rapporten omvatten allergische huidreacties en een tijdelijke opflakkering van bestaande auto-immuuncondities.","Gezamenlijk gebruik van immunosuppressieve medicatie wordt als contra-indicatie vermeld in de productinformatie, aangezien de effecten in tegengestelde richtingen werken.","De productinformatie adviseert voorzichtigheid bij actieve orgaantransplantatie en actieve auto-immuunziekte."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Onder de handelsnaam Zadaxin is thymosine alfa 1 goedgekeurd als medicijn voor de behandeling van bepaalde immuuncondities, waaronder hepatitis B en C, in meer dan 35 landen. Het is momenteel niet goedgekeurd in Duitsland, Oostenrijk of Zwitserland, waar de bronnen zich in een juridisch grijs gebied bevinden.","rechtsstatus_en":"Onder de handelsnaam Zadaxin is thymosine alfa 1 goedgekeurd als medicijn voor de behandeling van bepaalde immuuncondities, waaronder hepatitis B en C, in meer dan 35 landen. Het is momenteel niet goedgekeurd in Duitsland, Oostenrijk of Zwitserland, waar de bronnen zich in een juridisch grijs gebied bevinden.","typischeMg":[],"faq":[{"q":"Is thymosine alfa 1 een goedgekeurd medicijn?","a":"Ja, onder de handelsnaam Zadaxin in meer dan 35 landen, waaronder voor chronische hepatitis B en C. Er is momenteel geen goedkeuring in Duitsland, Oostenrijk of Zwitserland.","q_en":"Is thymosine alfa 1 een goedgekeurd medicijn?","a_en":"Ja, onder de handelsnaam Zadaxin in meer dan 35 landen, waaronder voor chronische hepatitis B en C. Er is momenteel geen goedkeuring in Duitsland, Oostenrijk of Zwitserland."},{"q":"Waar werkt thymosine alfa 1 in het immuunsysteem?","a":"Het werkt tegelijkertijd op het aangeboren en het adaptieve immuunsysteem, waaronder via verhoogde activiteit van T-cellen en natuurlijke killercellen, en verbeterde antilichaamvorming.","q_en":"Waar werkt thymosine alfa 1 in het immuunsysteem?","a_en":"Het werkt tegelijkertijd op het aangeboren en het adaptieve immuunsysteem, waaronder via verhoogde activiteit van T-cellen en natuurlijke killercellen, en verbeterde antilichaamvorming."},{"q":"Zijn er menselijke studies over thymosine alfa 1?","a":"Ja, vergeleken met veel andere peptiden is er een bredere basis van klinische studies, inclusief werk over ernstige virale infecties, een ondersteunende rol in de kankerzorg en vaccinrespons.","q_en":"Zijn er menselijke studies over thymosine alfa 1?","a_en":"Ja, vergeleken met veel andere peptiden is er een bredere basis van klinische studies, inclusief werk over ernstige virale infecties, een ondersteunende rol in de kankerzorg en vaccinrespons."}],"seo":{"title":"Thymosine alfa 1: onderzoeksprofiel en bewijs","title_en":"Thymosine alfa 1: onderzoeksprofiel en bewijs","description":"Thymosine alfa 1 overzicht: immuunmodulatie, internationale goedkeuringsstatus, klinisch bewijs en veiligheidsprofiel.","description_en":"Thymosine alfa 1 overzicht: immuunmodulatie, internationale goedkeuringsstatus, klinisch bewijs en veiligheidsprofiel."},"demo":false,"steckbrief":{"cas":"62304-98-7","molekulargewicht":"3108.3 g/mol","aminosaeuren":28,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":28,"quellen":["PubChem CID 16130571","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["bpc-157","tb-500","kpv","ll-37"]},{"slug":"epitalon","name":"Epitalon","synonyme":["Epithalon","AEDG-tetrapeptide"],"kategorie":"Sonstige","studienlage":"präklinisch","kurz":"Een synthetisch tetrapeptide, bestudeerd in verouderingsonderzoek als onderzoeksstof gerelateerd aan cellulaire veroudering.","kurz_en":"Een synthetisch tetrapeptide, bestudeerd in verouderingsonderzoek als onderzoeksstof gerelateerd aan cellulaire veroudering.","beschreibung":"Epitalon is een synthetisch tetrapeptide ontwikkeld door Vladimir Khavinson aan het Saint Petersburg Institute of Bioregulation and Gerontology. Het wordt bestudeerd in preklinisch onderzoek in verband met cellulaire veroudering en de regulatie van telomeraseactiviteit. Robuuste klinische gegevens bij mensen wachten nog.","beschreibung_en":"Epitalon is een synthetisch tetrapeptide ontwikkeld door Vladimir Khavinson aan het Saint Petersburg Institute of Bioregulation and Gerontology. Het wordt bestudeerd in preklinisch onderzoek in verband met cellulaire veroudering en de regulatie van telomeraseactiviteit. Robuuste klinische gegevens bij mensen wachten nog.","mechanismus":"Epitalon is beschreven als telomeraseactiviteit te verhogen in celculturen, wat geassocieerd werd met telomeerverlenging in vitro. Effecten op melatonineproductie en op immuunsysteemsignaalmoleculen zijn ook beschreven.","mechanismus_en":"Epitalon is beschreven als telomeraseactiviteit te verhogen in celculturen, wat geassocieerd werd met telomeerverlenging in vitro. Effecten op melatonineproductie en op immuunsysteemsignaalmoleculen zijn ook beschreven.","evidenz":[{"art":"preklinisch","kurz":"In celculturen van menselijke foetale fibroblasten induceerde epitalon expressie van de katalytische telomerase-subeenheid en meetbare telomeraseactiviteit, geassocieerd met telomeerverlenging.","kurz_en":"In celculturen van menselijke foetale fibroblasten induceerde epitalon expressie van de katalytische telomerase-subeenheid en meetbare telomeraseactiviteit, geassocieerd met telomeerverlenging.","quelle":"Khavinson VKh, Bondarev IE, Butyugov AA 2003, Bulletin of Experimental Biology and Medicine 135:590-592"},{"art":"preklinisch","kurz":"In dierlijke modellen zijn effecten van epitalon op melatonineafgifte en op immuunsysteemparameters beschreven, met gemengde resultaten over de levensduur afhankelijk van het gebruikte model en protocol.","kurz_en":"In dierlijke modellen zijn effecten van epitalon op melatonineafgifte en op immuunsysteemparameters beschreven, met gemengde resultaten over de levensduur afhankelijk van het gebruikte model en protocol.","quelle":"Khavinson VKh, Morozov VG 2003, Neuroendocrinology Letters"}],"sicherheit":["Preklinisch onderzoek heeft tot nu toe geen ernstige toxische effecten beschreven.","Gecontroleerde menselijke veiligheidsstudies die voldoen aan Westerse proefstandaarden zijn niet beschikbaar.","Er zijn geen robuuste gegevens over langdurig gebruik."],"sicherheit_en":["Preklinisch onderzoek heeft tot nu toe geen ernstige toxische effecten beschreven.","Gecontroleerde menselijke veiligheidsstudies die voldoen aan Westerse proefstandaarden zijn niet beschikbaar.","Er zijn geen robuuste gegevens over langdurig gebruik."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Epitalon is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, en wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumdoeleinden.","rechtsstatus_en":"Epitalon is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, en wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumdoeleinden.","typischeMg":[10,20],"faq":[{"q":"Is epitalon in mensen onderzocht?","a":"Beschikbare gegevens komen voornamelijk uit celculturen en dierlijke modellen. Gecontroleerde klinische studies in mensen die voldoen aan Westerse standaarden zijn nog niet beschikbaar.","q_en":"Is epitalon in mensen onderzocht?","a_en":"Beschikbare gegevens komen voornamelijk uit celculturen en dierlijke modellen. Gecontroleerde klinische studies in mensen die voldoen aan Westerse standaarden zijn nog niet beschikbaar."},{"q":"Wat heeft epitalon te maken met telomeer?","a":"Celcultuurstudies observeerden een toename van telomeraseactiviteit en telomeerverlenging. Of dit zich vertaalt naar het gehele organisme blijft open.","q_en":"Wat heeft epitalon te maken met telomeer?","a_en":"Celcultuurstudies observeerden een toename van telomeraseactiviteit en telomeerverlenging. Of dit zich vertaalt naar het gehele organisme blijft open."},{"q":"Is epitalon legaal verkrijgbaar in Duitsland?","a":"Epitalon is niet goedgekeurd als medicijn en wordt uitsluitend aangeboden als chemische stof voor onderzoek, niet voor menselijk gebruik.","q_en":"Is epitalon legaal verkrijgbaar in Duitsland?","a_en":"Epitalon is niet goedgekeurd als medicijn en wordt uitsluitend aangeboden als chemische stof voor onderzoek, niet voor menselijk gebruik."}],"seo":{"title":"Epitalon: Tetrapeptide in Verouderingsonderzoek","title_en":"Epitalon: Tetrapeptide in Verouderingsonderzoek","description":"Epitalon overzicht: mechanisme, status preklinisch onderzoek en veiligheidsprofiel van het Khavinson telomerase onderzoekspeptide.","description_en":"Epitalon overzicht: mechanisme, status preklinisch onderzoek en veiligheidsprofiel van het Khavinson telomerase onderzoekspeptide."},"demo":false,"steckbrief":{"cas":"307297-39-8","molekulargewicht":"390,35 g/mol","aminosaeuren":4,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":4,"quellen":["PubChem CID 219042","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["melanotan-2","selank","semax","dsip"]},{"slug":"kisspeptin","name":"Kisspeptine-10","synonyme":["Metastin (45-54)","KP-10"],"kategorie":"Sonstige","studienlage":"klinisch untersucht","kurz":"Het kortste bioactieve fragment van het eigen kisspeptine systeem van het lichaam, onderzocht in endocriene onderzoek naar de controle van de hypothalamus-hypofyse-gonadale as.","kurz_en":"Het kortste bioactieve fragment van het eigen kisspeptine systeem van het lichaam, onderzocht in endocriene onderzoek naar de controle van de hypothalamus-hypofyse-gonadale as.","beschreibung":"Kisspeptine-10 is het kortste fragment van het eigen peptide kisspeptine (metastine) van het lichaam dat volledige activiteit behoudt op de KISS1R receptor. In onderzoek wordt het gebruikt om de GnRH-afgifte direct te triggeren en om de hypothalamus-hypofyse-gonadale as te bestuderen in kwesties van puberteitontwikkeling, hypogonadisme en vruchtbaarheid. Grotere klinische proeven op eindpunten zoals oocytenmaturatie of seksuele prikkeling gebruiken meestal het langere natuurlijke isoforme kisspeptine-54, dat op dezelfde receptor werkt.","beschreibung_en":"Kisspeptine-10 is het kortste fragment van het eigen peptide kisspeptine (metastine) van het lichaam dat volledige activiteit behoudt op de KISS1R receptor. In onderzoek wordt het gebruikt om de GnRH-afgifte direct te triggeren en om de hypothalamus-hypofyse-gonadale as te bestuderen in kwesties van puberteitontwikkeling, hypogonadisme en vruchtbaarheid. Grotere klinische proeven op eindpunten zoals oocytenmaturatie of seksuele prikkeling gebruiken meestal het langere natuurlijke isoforme kisspeptine-54, dat op dezelfde receptor werkt.","mechanismus":"Kisspeptine-10 bindt aan de G-proteïne-gekoppelde receptor KISS1R (GPR54) op GnRH-neuronen in de hypothalamus. Via een Gq/11-gemedieerde signaalcascade die calciuminflux omvat, depolariseert het deze neuronen en triggert pulserende GnRH-afgifte, die stroomafwaarts de LH en FSH-secretie van de hypofyseklier reguleert. Bij mannen verhoogt een kisspeptine-10 bolus de LH-niveaus en de pulsfrequentie, met een sterkere werking bij hogere toegediende hoeveelheden. Aanhoudende of hoge frequentie receptorstimulatie kan daarentegen KISS1R desensibiliseren en de LH-respons verminderen.","mechanismus_en":"Kisspeptine-10 bindt aan de G-proteïne-gekoppelde receptor KISS1R (GPR54) op GnRH-neuronen in de hypothalamus. Via een Gq/11-gemedieerde signaalcascade die calciuminflux omvat, depolariseert het deze neuronen en triggert pulserende GnRH-afgifte, die stroomafwaarts de LH en FSH-secretie van de hypofyseklier reguleert. Bij mannen verhoogt een kisspeptine-10 bolus de LH-niveaus en de pulsfrequentie, met een sterkere werking bij hogere toegediende hoeveelheden. Aanhoudende of hoge frequentie receptorstimulatie kan daarentegen KISS1R desensibiliseren en de LH-respons verminderen.","evidenz":[{"art":"klinisch","kurz":"In een studie bij gezonde mannen verhoogde een intraveneuze kisspeptine-10 bolus de LH-niveaus met een toenemend effect bij hogere hoeveelheden, en een continue infusie met lage concentratie verhoogde bovendien de LH pulssnelheid.","kurz_en":"In een studie bij gezonde mannen verhoogde een intraveneuze kisspeptine-10 bolus de LH-niveaus met een toenemend effect bij hogere hoeveelheden, en een continue infusie met lage concentratie verhoogde bovendien de LH pulssnelheid.","quelle":"George JT et al. 2011, The Journal of Clinical Endocrinology & Metabolism, PMID 21632807"},{"art":"klinisch","kurz":"In een gerandomiseerde studie bij 60 vrouwen met een hoog risico op OHSS veroorzaakte een enkele injectie van het gerelateerde isoforme kisspeptine-54 oocytenmaturatie in 95 procent van de gevallen tijdens een IVF cyclus, zonder matige tot ernstige OHSS waargenomen te worden.","kurz_en":"In een gerandomiseerde studie bij 60 vrouwen met een hoog risico op OHSS veroorzaakte een enkele injectie van het gerelateerde isoforme kisspeptine-54 oocytenmaturatie in 95 procent van de gevallen tijdens een IVF cyclus, zonder matige tot ernstige OHSS waargenomen te worden.","quelle":"Jayasena CN et al. 2015, The Journal of Clinical Endocrinology & Metabolism, PMID 26192876"},{"art":"klinisch","kurz":"In een gerandomiseerde, placebo-gecontroleerde studie bij 32 mannen met hypoactieve seksuele verlangensstoornis verhoogde een enkele infusie van het isoforme kisspeptine-54 de seksuele hersenactiviteit en peniserectie tijdens het bekijken van erotische video's vergeleken met placebo.","kurz_en":"In een gerandomiseerde, placebo-gecontroleerde studie bij 32 mannen met hypoactieve seksuele verlangensstoornis verhoogde een enkele infusie van het isoforme kisspeptine-54 de seksuele hersenactiviteit en peniserectie tijdens het bekijken van erotische video's vergeleken met placebo.","quelle":"Mills EG et al. 2023, JAMA Network Open, PMID 36735255"}],"sicherheit":["Over gepubliceerde studies met meer dan 1.000 deelnemers in totaal zijn tot op heden geen ernstige bijwerkingen toegeschreven aan de stof gerapporteerd, met een bijwerkingenprofiel vergelijkbaar met placebo.","De meest voorkomend beschreven effecten waren milde, tijdelijke reacties zoals reacties op de injectieplaats, roodheid en milde hoofdpijn.","Aanhoudende of hogefrequente stimulatie van de KISS1R receptor kan leiden tot receptor desensitisatie en een verminderde LH respons (tachyfyse).","Robuuste langetermijnveiligheidsgegevens zijn nog niet beschikbaar, aangezien beschikbare studies voornamelijk kortetermijn, gecontroleerde toediening dekken."],"sicherheit_en":["Over gepubliceerde studies met meer dan 1.000 deelnemers in totaal zijn tot op heden geen ernstige bijwerkingen toegeschreven aan de stof gerapporteerd, met een bijwerkingenprofiel vergelijkbaar met placebo.","De meest voorkomend beschreven effecten waren milde, tijdelijke reacties zoals reacties op de injectieplaats, roodheid en milde hoofdpijn.","Aanhoudende of hogefrequente stimulatie van de KISS1R receptor kan leiden tot receptor desensitisatie en een verminderde LH respons (tachyfyse).","Robuuste langetermijnveiligheidsgegevens zijn nog niet beschikbaar, aangezien beschikbare studies voornamelijk kortetermijn, gecontroleerde toediening dekken."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Kisspeptine-10 is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumdoeleinden; klinische toepassingen zoals een IVF trigger of gebruik bij hypoactieve seksuele verlangensstoornis blijven onder experimentele onderzoeken.","rechtsstatus_en":"Kisspeptine-10 is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek voor laboratoriumdoeleinden; klinische toepassingen zoals een IVF trigger of gebruik bij hypoactieve seksuele verlangensstoornis blijven onder experimentele onderzoeken.","typischeMg":[5,10],"faq":[{"q":"Is kisspeptine-10 hetzelfde als het kisspeptine dat in klinische proeven is getest","a":"Niet helemaal. De meeste belangrijke klinische proeven over vruchtbaarheid of seksuele opwinding gebruikten het langere natuurlijke isoforme kisspeptine-54. Kisspeptine-10 is het kortste fragment met volledige receptoractiviteit en is voornamelijk bestudeerd in mechanistische onderzoek naar LH-afgifte bij mannen.","q_en":"Is kisspeptine-10 hetzelfde als het kisspeptine dat in klinische proeven is getest","a_en":"Niet helemaal. De meeste belangrijke klinische proeven over vruchtbaarheid of seksuele opwinding gebruikten het langere natuurlijke isoforme kisspeptine-54. Kisspeptine-10 is het kortste fragment met volledige receptoractiviteit en is voornamelijk bestudeerd in mechanistische onderzoek naar LH-afgifte bij mannen."},{"q":"Hoe werkt kisspeptine-10 in het lichaam","a":"Het bindt aan de KISS1R receptor op GnRH neuronen in de hypothalamus en triggert pulserende GnRH afgifte. Dit reguleert de LH en FSH secretie van de hypofyseklier en daarmee de centrale functies van de reproductieve as.","q_en":"Hoe werkt kisspeptine-10 in het lichaam","a_en":"Het bindt aan de KISS1R receptor op GnRH neuronen in de hypothalamus en triggert pulserende GnRH afgifte. Dit reguleert de LH en FSH secretie van de hypofyseklier en daarmee de centrale functies van de reproductieve as."},{"q":"Is kisspeptine-10 legaal verkrijgbaar in Duitsland","a":"Kisspeptine-10 is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Het wordt uitsluitend aangeboden als een chemische stof voor onderzoek voor laboratoriumdoeleinden, niet voor menselijk gebruik.","q_en":"Is kisspeptine-10 legaal verkrijgbaar in Duitsland","a_en":"Kisspeptine-10 is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Het wordt uitsluitend aangeboden als een chemische stof voor onderzoek voor laboratoriumdoeleinden, niet voor menselijk gebruik."}],"seo":{"title":"Kisspeptine-10: Onderzoekspeptide voor de hormoonas","title_en":"Kisspeptine-10: Onderzoekspeptide voor de hormoonas","description":"Kisspeptine-10 feitelijk uitgelegd: mechanisme op de KISS1R receptor, studiedata over GnRH en de hormoonas, en het veiligheidsprofiel van een onderzoekspeptide.","description_en":"Kisspeptine-10 feitelijk uitgelegd: mechanisme op de KISS1R receptor, studiedata over GnRH en de hormoonas, en het veiligheidsprofiel van een onderzoekspeptide."},"demo":false,"steckbrief":{"cas":"374675-21-5","molekulargewicht":"1302.4 g/mol","aminosaeuren":10,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":"oplosbaar in water en waterige buffers","sequenzLaenge":10,"quellen":["PubChem CID 25240297","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit_en":"oplosbaar in water en waterige buffers"},"verwandt":["pt-141","oxytocin"]},{"slug":"melanotan-2","name":"Melanotan II","synonyme":["MT-2","MT2"],"kategorie":"Sonstige","studienlage":"frühe klinische Studien","kurz":"Een synthetisch analoog van het eigen hormoon alpha-MSH van het lichaam, bestudeerd in vroege klinische proeven op pigmentatie en seksuele functie.","kurz_en":"Een synthetisch analoog van het eigen hormoon alpha-MSH van het lichaam, bestudeerd in vroege klinische proeven op pigmentatie en seksuele functie.","beschreibung":"Melanotan II is een synthetisch, cyclisch zeven-aminozuur peptide dat verschillende melanocortine receptoren in het lichaam bindt. Het werd in de jaren 1980 ontwikkeld aan de University of Arizona en is aanzienlijk krachtiger dan zijn natuurlijke tegenhanger, alpha-MSH. Onderzoeksgebieden omvatten een rol in huidpigmentatie evenals seksueel verlangen en opwinding.","beschreibung_en":"Melanotan II is een synthetisch, cyclisch zeven-aminozuur peptide dat verschillende melanocortine receptoren in het lichaam bindt. Het werd in de jaren 1980 ontwikkeld aan de University of Arizona en is aanzienlijk krachtiger dan zijn natuurlijke tegenhanger, alpha-MSH. Onderzoeksgebieden omvatten een rol in huidpigmentatie evenals seksueel verlangen en opwinding.","mechanismus":"Via de MC1R receptor op huidpigmentcellen activeert melanotan II eumelanineproductie die plaatsvindt onafhankelijk van UV-blootstelling. Via de MC4R receptor in het centrale zenuwstelsel wordt een effect op seksueel verlangen en opwinding beschreven, samen met een eetlustregulerend effect. Omdat melanotan II verschillende receptoren tegelijkertijd niet selectief activeert, is de interactie van deze effecten complexer dan bij de meer selectieve, gerelateerde verbindingen.","mechanismus_en":"Via de MC1R receptor op huidpigmentcellen activeert melanotan II eumelanineproductie die plaatsvindt onafhankelijk van UV-blootstelling. Via de MC4R receptor in het centrale zenuwstelsel wordt een effect op seksueel verlangen en opwinding beschreven, samen met een eetlustregulerend effect. Omdat melanotan II verschillende receptoren tegelijkertijd niet selectief activeert, is de interactie van deze effecten complexer dan bij de meer selectieve, gerelateerde verbindingen.","evidenz":[{"art":"klinisch","kurz":"Een fase 1 pilotstudie bij drie mannelijke vrijwilligers beschreef merkbare huidpigmentatie zonder UV-blootstelling na herhaalde subcutane injecties, vergezeld van misselijkheid, roodheid en spontane erecties als de meest voorkomende bijwerkingen.","kurz_en":"Een fase 1 pilotstudie bij drie mannelijke vrijwilligers beschreef merkbare huidpigmentatie zonder UV-blootstelling na herhaalde subcutane injecties, vergezeld van misselijkheid, roodheid en spontane erecties als de meest voorkomende bijwerkingen.","quelle":"Dorr et al. 1996, Life Sciences, PMID 8637402"},{"art":"klinisch","kurz":"Een dubbelblind, placebo-gecontroleerde crossoverstudie bij mannen met psychogene erectiele dysfunctie beschreef een erectie bij 8 van de 10 deelnemers na melanotan II injectie, met significant langere stijfheid dan onder placebo.","kurz_en":"Een dubbelblind, placebo-gecontroleerde crossoverstudie bij mannen met psychogene erectiele dysfunctie beschreef een erectie bij 8 van de 10 deelnemers na melanotan II injectie, met significant langere stijfheid dan onder placebo.","quelle":"Hadley et al. 1998, PMID 9679884"}],"sicherheit":["Vaak gerapporteerde acute effecten zijn misselijkheid en gezichtsroodheid, toegeschreven aan histamineafgifte.","Milde toenames in bloeddruk en polssnelheid zijn waargenomen.","Een medische noodgeval met een erectie die enkele uren duurt is gedocumenteerd als een zeldzame maar ernstige bijwerking.","Casuïstische meldingen beschrijven nieuwe of donkerder geworden moedervlekken, meestal in samenhang met gelijktijdige blootstelling aan uv-straling. Een oorzakelijk verband met huidkanker is niet vastgesteld."],"sicherheit_en":["Vaak gerapporteerde acute effecten zijn misselijkheid en gezichtsroodheid, toegeschreven aan histamineafgifte.","Milde toenames in bloeddruk en polssnelheid zijn waargenomen.","Een medische noodgeval met een erectie die enkele uren duurt is gedocumenteerd als een zeldzame maar ernstige bijwerking.","Casuïstische meldingen beschrijven nieuwe of donkerder geworden moedervlekken, meestal in samenhang met gelijktijdige blootstelling aan uv-straling. Een oorzakelijk verband met huidkanker is niet vastgesteld."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Melanotan II is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, en het wordt uitsluitend verkocht als een chemische stof voor onderzoek. Drie structureel gerelateerde melanocortine-medicijnen (afamelanotide, bremelanotide, setmelanotide) zijn goedgekeurd voor afzonderlijke, specifieke indicaties in de Verenigde Staten en in delen van de EU; melanotan II zelf behoort er niet tot.","rechtsstatus_en":"Melanotan II is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten, en het wordt uitsluitend verkocht als een chemische stof voor onderzoek. Drie structureel gerelateerde melanocortine-medicijnen (afamelanotide, bremelanotide, setmelanotide) zijn goedgekeurd voor afzonderlijke, specifieke indicaties in de Verenigde Staten en in delen van de EU; melanotan II zelf behoort er niet tot.","typischeMg":[],"faq":[{"q":"Is melanotan II goedgekeurd?","a":"Nee, melanotan II zelf is niet goedgekeurd in de EU of de Verenigde Staten. Het wordt alleen verkocht als een chemische stof voor onderzoek, terwijl drie gerelateerde verbindingen zijn goedgekeurd voor andere indicaties.","q_en":"Is melanotan II goedgekeurd?","a_en":"Nee, melanotan II zelf is niet goedgekeurd in de EU of de Verenigde Staten. Het wordt alleen verkocht als een chemische stof voor onderzoek, terwijl drie gerelateerde verbindingen zijn goedgekeurd voor andere indicaties."},{"q":"Werkt melanotan II alleen met zonlicht?","a":"Nee. Volgens studies vindt pigmentvorming onafhankelijk van UV-blootstelling plaats. UV-licht kan het effect verder versterken maar is niet vereist voor het.","q_en":"Werkt melanotan II alleen met zonlicht?","a_en":"Nee. Volgens studies vindt pigmentvorming onafhankelijk van UV-blootstelling plaats. UV-licht kan het effect verder versterken maar is niet vereist voor het."},{"q":"Welke bijwerkingen worden in studies beschreven?","a":"Meestal misselijkheid en een rood aangezicht (flushing). Minder vaak zijn bloeddrukverhogingen, een langdurige erectie als medisch noodgeval en veranderingen in moedervlekken beschreven.","q_en":"Welke bijwerkingen worden in studies beschreven?","a_en":"Meestal misselijkheid en een rood aangezicht (flushing). Minder vaak zijn bloeddrukverhogingen, een langdurige erectie als medisch noodgeval en veranderingen in moedervlekken beschreven."}],"seo":{"title":"Melanotan II: onderzoeksprofiel en bewijs","title_en":"Melanotan II: onderzoeksprofiel en bewijs","description":"Melanotan II overzicht: mechanisme, klinisch bewijs op pigmentatie en seksuele functie, en veiligheidsprofiel.","description_en":"Melanotan II overzicht: mechanisme, klinisch bewijs op pigmentatie en seksuele functie, en veiligheidsprofiel."},"demo":false,"steckbrief":{"cas":"121062-08-6","molekulargewicht":"1024.2 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 92432","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, commercieel standaard)"},"verwandt":["ghk-cu","epitalon","pt-141","kpv"]},{"slug":"oxytocin","name":"Oxytocine","synonyme":["OXT","Pitocin"],"kategorie":"Sonstige","studienlage":"zugelassenes Arzneimittel","kurz":"Een endogene nonapeptide hormoon, goedgekeurd als medicijn om bevalling te induceren en ook bestudeerd in onderzoek naar sociaal gedrag en hechting.","kurz_en":"Een endogene nonapeptide hormoon, goedgekeurd als medicijn om bevalling te induceren en ook bestudeerd in onderzoek naar sociaal gedrag en hechting.","beschreibung":"Oxytocine is een negen-aminozuurhormoon dat in de hypothalamus wordt geproduceerd en vrijgegeven via de hypofyseklier. Als medicijn, zoals Syntocinon of Pitocin, is het goedgekeurd om bevalling te induceren en postpartuma bloedingen te controleren. Oxytocine dat intranasaal wordt toegediend, wordt apart bestudeerd in basisonderzoek naar sociaal gedrag, vertrouwen en hechting.","beschreibung_en":"Oxytocine is een negen-aminozuurhormoon dat in de hypothalamus wordt geproduceerd en vrijgegeven via de hypofyseklier. Als medicijn, zoals Syntocinon of Pitocin, is het goedgekeurd om bevalling te induceren en postpartuma bloedingen te controleren. Oxytocine dat intranasaal wordt toegediend, wordt apart bestudeerd in basisonderzoek naar sociaal gedrag, vertrouwen en hechting.","mechanismus":"Oxytocine bindt aan de oxytocine receptor (OXTR), een Gq/11-proteïne-gekoppeld receptor op het spierweefsel van de baarmoeder en in verschillende hersengebieden. Receptorbinding activeert fosfolipase C en, via die, de afgifte van intracellulair calcium, wat de contractie van het spierweefsel van de baarmoeder aandrijft. Bij hogere concentraties werkt oxytocine ook op de structureel gerelateerde vasopressine V2 receptor, wat een antidiuretisch effect veroorzaakt.","mechanismus_en":"Oxytocine bindt aan de oxytocine receptor (OXTR), een Gq/11-proteïne-gekoppeld receptor op het spierweefsel van de baarmoeder en in verschillende hersengebieden. Receptorbinding activeert fosfolipase C en, via die, de afgifte van intracellulair calcium, wat de contractie van het spierweefsel van de baarmoeder aandrijft. Bij hogere concentraties werkt oxytocine ook op de structureel gerelateerde vasopressine V2 receptor, wat een antidiuretisch effect veroorzaakt.","evidenz":[{"art":"preklinisch","kurz":"In een prairievole diermodel induceerde centrale toediening van oxytocine partnervoorkeur bij vrouwtjes, terwijl een selectieve oxytocine antagonist de vorming ervan na het paren blokkeerde.","kurz_en":"In een prairievole diermodel induceerde centrale toediening van oxytocine partnervoorkeur bij vrouwtjes, terwijl een selectieve oxytocine antagonist de vorming ervan na het paren blokkeerde.","quelle":"Insel TR & Hulihan TJ 1995, Behavioral Neuroscience, 109:782-789"},{"art":"klinisch","kurz":"In een placebo-gecontroleerde gedragsstudie bij gezonde mannelijke deelnemers verhoogde intranasaal toegediend oxytocine de bereidheid om geld aan een vreemdeling te vertrouwen in een vertrouwenspel, zonder het algemene risico nemen te veranderen.","kurz_en":"In een placebo-gecontroleerde gedragsstudie bij gezonde mannelijke deelnemers verhoogde intranasaal toegediend oxytocine de bereidheid om geld aan een vreemdeling te vertrouwen in een vertrouwenspel, zonder het algemene risico nemen te veranderen.","quelle":"Kosfeld M, Heinrichs M, Zak PJ, Fischbacher U, Fehr E 2005, Nature, PMID 15931222"},{"art":"klinisch","kurz":"In een gerandomiseerd, placebo-gecontroleerd onderzoek bij 106 volwassenen met autismespectrumstoornis toonde zes weken intranasaal oxytocine geen statistisch significant verbetering in kernsociale symptomen vergeleken met placebo.","kurz_en":"In een gerandomiseerd, placebo-gecontroleerd onderzoek bij 106 volwassenen met autismespectrumstoornis toonde zes weken intranasaal oxytocine geen statistisch significant verbetering in kernsociale symptomen vergeleken met placebo.","quelle":"Yamasue H et al. 2020, Molecular Psychiatry, PMID 29955161"},{"art":"preklinisch","kurz":"Een review over receptor-farmacologie beschrijft de koppeling van de oxytocine receptor aan Gq/11-eiwitgemedieerde signaalroutes zoals phospholipase C en proteinkinas C in cellulaire en dierlijke modellen.","kurz_en":"Een review over receptor-farmacologie beschrijft de koppeling van de oxytocine receptor aan Gq/11-eiwitgemedieerde signaalroutes zoals phospholipase C en proteinkinas C in cellulaire en dierlijke modellen.","quelle":"Jurek B & Neumann ID 2018, Physiological Reviews, PMID 29897293"}],"sicherheit":["Met intraveneuze toediening gecombineerd met grote volumes elektrolyt-vrije vloeistof is waterintoxicatie met hyponatriëmie gedocumenteerd, gedreven door het antidiuretische effect van oxytocine dat gekoppeld is aan zijn structurele gelijkenis met vasopressine.","Een breed geciteerd studie over de trustverhogende effecten van intranasaal oxytocine kon niet bevestigd worden in een latere replicastudie onder identieke experimentele omstandigheden.","In de grootste gerandomiseerde studie van intranasaal oxytocine bij autismespectrumstoornis tot op heden werd geen significant effect op kernsymptomen waargenomen.","Voor toepassingen buiten de goedgekeurde obstetrische indicatie zijn er geen robuuste langetermijnveiligheidsgegevens beschikbaar."],"sicherheit_en":["Met intraveneuze toediening gecombineerd met grote volumes elektrolyt-vrije vloeistof is waterintoxicatie met hyponatriëmie gedocumenteerd, gedreven door het antidiuretische effect van oxytocine dat gekoppeld is aan zijn structurele gelijkenis met vasopressine.","Een breed geciteerd studie over de trustverhogende effecten van intranasaal oxytocine kon niet bevestigd worden in een latere replicastudie onder identieke experimentele omstandigheden.","In de grootste gerandomiseerde studie van intranasaal oxytocine bij autismespectrumstoornis tot op heden werd geen significant effect op kernsymptomen waargenomen.","Voor toepassingen buiten de goedgekeurde obstetrische indicatie zijn er geen robuuste langetermijnveiligheidsgegevens beschikbaar."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Oxytocine is goedgekeurd als medicijn, zoals Syntocinon of Pitocin, in Duitsland, de EU en de Verenigde Staten voor bevordering van de bevalling en de behandeling van postpartuma bloeding, en is voorschriftplichtig voor dat gebruik. Voor andere, niet goedgekeurde onderzoeksvragen zoals sociaal gedrag of hechting, wordt het apart verkocht als een chemische stof voor onderzoek.","rechtsstatus_en":"Oxytocine is goedgekeurd als medicijn, zoals Syntocinon of Pitocin, in Duitsland, de EU en de Verenigde Staten voor bevordering van de bevalling en de behandeling van postpartuma bloeding, en is voorschriftplichtig voor dat gebruik. Voor andere, niet goedgekeurde onderzoeksvragen zoals sociaal gedrag of hechting, wordt het apart verkocht als een chemische stof voor onderzoek.","typischeMg":[],"faq":[{"q":"Is oxytocine een goedgekeurd medicijn of een chemische stof voor onderzoek","a":"Beide, afhankelijk van het gebruik. Voor bevordering van de bevalling en postpartuma bloeding is oxytocine een voorgeschreven medicijn. Voor andere onderzoeksvragen zoals sociaal gedrag wordt het apart verkocht als een chemische stof voor onderzoek, zonder goedkeuring voor dat doel.","q_en":"Is oxytocine een goedgekeurd medicijn of een chemische stof voor onderzoek","a_en":"Beide, afhankelijk van het gebruik. Voor bevordering van de bevalling en postpartuma bloeding is oxytocine een voorgeschreven medicijn. Voor andere onderzoeksvragen zoals sociaal gedrag wordt het apart verkocht als een chemische stof voor onderzoek, zonder goedkeuring voor dat doel."},{"q":"Waar wordt oxytocine bestudeerd in sociaal gedragonderzoek","a":"Studies onderzoeken intranasaal toegediend oxytocine in relatie tot vertrouwen, hechting en sociale perceptie. Resultaten zijn gemengd, en een breed geciteerd vroeg vertrouwenonderzoek kon niet worden bevestigd in een replicatie.","q_en":"Waar wordt oxytocine bestudeerd in sociaal gedragonderzoek","a_en":"Studies onderzoeken intranasaal toegediend oxytocine in relatie tot vertrouwen, hechting en sociale perceptie. Resultaten zijn gemengd, en een breed geciteerd vroeg vertrouwenonderzoek kon niet worden bevestigd in een replicatie."},{"q":"Werkt oxytocine voor autismespectrumstoornis","a":"De grootste gerandomiseerde studie bij volwassenen met autismespectrumstoornis tot op heden toonde geen significant effect van intranasaal oxytocine op kernsociale symptomen vergeleken met placebo.","q_en":"Werkt oxytocine voor autismespectrumstoornis","a_en":"De grootste gerandomiseerde studie bij volwassenen met autismespectrumstoornis tot op heden toonde geen significant effect van intranasaal oxytocine op kernsociale symptomen vergeleken met placebo."}],"seo":{"title":"Oxytocine: Hormoon, Medicijn en Onderzoekspeptide","title_en":"Oxytocine: Hormoon, Medicijn en Onderzoekspeptide","description":"Oxytocine feitelijk uitgelegd: goedgekeurde indicatie, werkingsmechanisme, onderzoek naar sociaal gedrag en juridische status als chemische stof voor onderzoek.","description_en":"Oxytocine feitelijk uitgelegd: goedgekeurde indicatie, werkingsmechanisme, onderzoek naar sociaal gedrag en juridische status als chemische stof voor onderzoek."},"demo":false,"steckbrief":{"cas":"50-56-6","molekulargewicht":"1007.2 g/mol","aminosaeuren":9,"halbwertszeit":"≈ 1 tot 6 minuten (plasmahalfwaardetijd, voorschrijfinformatie Pitocin)","reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":9,"quellen":["PubChem CID 439302","DailyMed SPL PITOCIN (Oxytocin), Par Health USA","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 1 tot 6 minuten (plasmahalfwaardetijd, voorschrijfinformatie Pitocin)","reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["kisspeptin","pt-141","dsip"]},{"slug":"pt-141","name":"PT-141 (bremelanotide)","synonyme":["Bremelanotide","Vyleesi"],"kategorie":"Sonstige","studienlage":"zugelassenes Arzneimittel","kurz":"Een synthetisch heptapeptide en melanocortine receptor agonist, goedgekeurd in de VS onder de naam Vyleesi voor een specifieke vorm van lage seksuele begeerte bij vrouwen.","kurz_en":"Een synthetisch heptapeptide en melanocortine receptor agonist, goedgekeurd in de VS onder de naam Vyleesi voor een specifieke vorm van lage seksuele begeerte bij vrouwen.","beschreibung":"PT-141 (bremelanotide) is een zeven-aminozuur peptide ontwikkeld bij Palatin Technologies als een vervolgverbinding op melanotan II. In tegenstelling tot melanotan II, die voornamelijk werd onderzocht voor huidpigmentatie, richtte onderzoek naar bremelanotide zich op de centrale regulatie van seksuele begeerte. Sinds 2019 is de stof goedgekeurd in de VS onder de naam Vyleesi voor de indicatie hypoactieve seksuele begeerte stoornis (HSDD) bij premenopauzale vrouwen.","beschreibung_en":"PT-141 (bremelanotide) is een zeven-aminozuur peptide ontwikkeld bij Palatin Technologies als een vervolgverbinding op melanotan II. In tegenstelling tot melanotan II, die voornamelijk werd onderzocht voor huidpigmentatie, richtte onderzoek naar bremelanotide zich op de centrale regulatie van seksuele begeerte. Sinds 2019 is de stof goedgekeurd in de VS onder de naam Vyleesi voor de indicatie hypoactieve seksuele begeerte stoornis (HSDD) bij premenopauzale vrouwen.","mechanismus":"Bremelanotide werkt als agonist op melanocortine receptoren, voornamelijk het MC4R subtype geconcentreerd in het mediaal preoptische gebied van de hypothalamus. Preklinisch onderzoek beschrijft dopamine vrijgave die wordt getriggerd door deze receptor in hersengebieden die betrokken zijn bij seksuele opwinding. Het actiegebied is daarom centraal, in de hersenen, in plaats van vaatachtig zoals bij PDE5-remmers. Volgens de FDA-etiket is het precieze mechanisme achter de verbetering van HSDD symptomen niet volledig vastgesteld.","mechanismus_en":"Bremelanotide werkt als agonist op melanocortine receptoren, voornamelijk het MC4R subtype geconcentreerd in het mediaal preoptische gebied van de hypothalamus. Preklinisch onderzoek beschrijft dopamine vrijgave die wordt getriggerd door deze receptor in hersengebieden die betrokken zijn bij seksuele opwinding. Het actiegebied is daarom centraal, in de hersenen, in plaats van vaatachtig zoals bij PDE5-remmers. Volgens de FDA-etiket is het precieze mechanisme achter de verbetering van HSDD symptomen niet volledig vastgesteld.","evidenz":[{"art":"preklinisch","kurz":"Studies bij vrouwelijke ratten toonden een toename van seksuele sollicitatiegedrag na bremelanotide toediening, gemedieerd door dopamine vrijgave na activatie van MC4 receptoren in het mediaal preoptische gebied van de hypothalamus.","kurz_en":"Studies bij vrouwelijke ratten toonden een toename van seksuele sollicitatiegedrag na bremelanotide toediening, gemedieerd door dopamine vrijgave na activatie van MC4 receptoren in het mediaal preoptische gebied van de hypothalamus.","quelle":"Pfaus JG et al. 2007, The Journal of Sexual Medicine, PMID 17958619"},{"art":"klinisch","kurz":"In twee gerandomiseerde, placebo-gecontroleerde fase 3 proeven (RECONNECT) bij premenopauzale vrouwen met HSDD verbeterde bremelanotide seksuele begeerte en gerelateerde lijdensdruk meer dan placebo.","kurz_en":"In twee gerandomiseerde, placebo-gecontroleerde fase 3 proeven (RECONNECT) bij premenopauzale vrouwen met HSDD verbeterde bremelanotide seksuele begeerte en gerelateerde lijdensdruk meer dan placebo.","quelle":"Kingsberg SA, Clayton AH, Portman D et al. 2019, Obstetrics & Gynecology, PMID 31599840"},{"art":"klinisch","kurz":"Een geaggregeerde analyse van 43 klinische studies met ongeveer 3.500 deelnemers documenteerde misselijkheid, roodheid, hoofdpijn en transiënte stijgingen van de bloeddruk als de meest voorkomende bijwerkingen van bremelanotide.","kurz_en":"Een geaggregeerde analyse van 43 klinische studies met ongeveer 3.500 deelnemers documenteerde misselijkheid, roodheid, hoofdpijn en transiënte stijgingen van de bloeddruk als de meest voorkomende bijwerkingen van bremelanotide.","quelle":"Clayton AH et al. 2022, Journal of Women's Health, PMID 35147466"}],"sicherheit":["In klinische proeven vond misselijkheid plaats bij ongeveer 40 procent van de deelnemers op bremelanotide, vergeleken met ongeveer 1 procent op placebo.","Een transiënte stijging van de bloeddruk en daling van de hartslag werd waargenomen na elke toediening, oplossend binnen ongeveer 12 uur volgens het FDA-etiket.","Volgens het FDA-etiket is Vyleesi contra-indiceerd bij ongecontroleerde hypertensie of bekende cardiovasculaire ziekte.","In de RECONNECT proeven werd focale huidhyperpigmentatie waargenomen bij ongeveer 1 procent van de deelnemers."],"sicherheit_en":["In klinische proeven vond misselijkheid plaats bij ongeveer 40 procent van de deelnemers op bremelanotide, vergeleken met ongeveer 1 procent op placebo.","Een transiënte stijging van de bloeddruk en daling van de hartslag werd waargenomen na elke toediening, oplossend binnen ongeveer 12 uur volgens het FDA-etiket.","Volgens het FDA-etiket is Vyleesi contra-indiceerd bij ongecontroleerde hypertensie of bekende cardiovasculaire ziekte.","In de RECONNECT proeven werd focale huidhyperpigmentatie waargenomen bij ongeveer 1 procent van de deelnemers."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"Bremelanotide is door de FDA goedgekeurd als Vyleesi sinds 2019 voor de indicatie HSDD bij premenopauzale vrouwen. In Duitsland en de EU bestaat er geen medicijngoedkeuring, en de stof wordt daar uitsluitend verkocht als een chemische stof voor onderzoek.","rechtsstatus_en":"Bremelanotide is door de FDA goedgekeurd als Vyleesi sinds 2019 voor de indicatie HSDD bij premenopauzale vrouwen. In Duitsland en de EU bestaat er geen medicijngoedkeuring, en de stof wordt daar uitsluitend verkocht als een chemische stof voor onderzoek.","typischeMg":[10,20],"faq":[{"q":"Is PT-141 hetzelfde als melanotan II","a":"Nee. Beide zijn terug te voeren op gerelateerde melanocortine structuren, maar PT-141 (bremelanotide) werd specifiek bestudeerd voor seksueel verlangen, terwijl melanotan II voornamelijk werd onderzocht voor huidpigmentatie. Alleen bremelanotide bereikte marktgoedkeuring in de VS, als Vyleesi.","q_en":"Is PT-141 hetzelfde als melanotan II","a_en":"Nee. Beide zijn terug te voeren op gerelateerde melanocortine structuren, maar PT-141 (bremelanotide) werd specifiek bestudeerd voor seksueel verlangen, terwijl melanotan II voornamelijk werd onderzocht voor huidpigmentatie. Alleen bremelanotide bereikte marktgoedkeuring in de VS, als Vyleesi."},{"q":"Is bremelanotide een goedgekeurd medicijn","a":"In de VS, ja: sinds 2019 is bremelanotide goedgekeurd onder de naam Vyleesi voor de indicatie HSDD bij premenopauzale vrouwen. In Duitsland en de EU bestaat er geen medicijngoedkeuring, en de stof wordt daar geclassificeerd als een chemische stof voor onderzoek.","q_en":"Is bremelanotide een goedgekeurd medicijn","a_en":"In de VS, ja: sinds 2019 is bremelanotide goedgekeurd onder de naam Vyleesi voor de indicatie HSDD bij premenopauzale vrouwen. In Duitsland en de EU bestaat er geen medicijngoedkeuring, en de stof wordt daar geclassificeerd als een chemische stof voor onderzoek."},{"q":"Welke bijwerkingen zijn in studies waargenomen","a":"De meest frequent gedocumenteerde effecten waren misselijkheid, roodheid, hoofdpijn en transiënte verhogingen van de bloeddruk na toediening. Volgens de FDA-etiket is de stof contra-ïndiceerd bij ongecontroleerde hypertensie of bekende cardiovasculaire ziekte.","q_en":"Welke bijwerkingen zijn in studies waargenomen","a_en":"De meest frequent gedocumenteerde effecten waren misselijkheid, roodheid, hoofdpijn en transiënte verhogingen van de bloeddruk na toediening. Volgens de FDA-etiket is de stof contra-ïndiceerd bij ongecontroleerde hypertensie of bekende cardiovasculaire ziekte."}],"seo":{"title":"Onderzoeksoverzicht van PT-141 (bremelanotide)","title_en":"Onderzoeksoverzicht van PT-141 (bremelanotide)","description":"PT-141 (bremelanotide): mechanisme, studiedata, veiligheidsprofiel en goedkeuringsstatus van deze melanocortine receptor agonist op een rij.","description_en":"PT-141 (bremelanotide): mechanisme, studiedata, veiligheidsprofiel en goedkeuringsstatus van deze melanocortine receptor agonist op een rij."},"demo":false,"steckbrief":{"cas":"189691-06-3","molekulargewicht":"1025.2 g/mol","aminosaeuren":7,"halbwertszeit":"≈ 2,7 uur (terminale halveringstijd, Vyleesi productinformatie)","reinheitsstandard":"≥ 99 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 9941379","DailyMed SPL VYLEESI (Bremelanotid), Cosette Pharmaceuticals","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 2,7 uur (terminale halveringstijd, Vyleesi productinformatie)","reinheitsstandard_en":"≥ 99 % (HPLC, commercieel standaard)"},"verwandt":["melanotan-2","kisspeptin","kpv"]},{"slug":"ss-31","name":"SS-31 (elamipretide)","synonyme":["Elamipretide","MTP-131","Bendavia"],"kategorie":"Sonstige","studienlage":"klinisch untersucht","kurz":"Een mitochondriale gerichte tetrapeptide bestudeerd in verschillende klinische proeven voor hartfalen en mitochondriepathologie, nog niet goedgekeurd.","kurz_en":"Een mitochondriale gerichte tetrapeptide bestudeerd in verschillende klinische proeven voor hartfalen en mitochondriepathologie, nog niet goedgekeurd.","beschreibung":"SS-31, ook bekend onder de generieke naam elamipretide als MTP-131 of Bendavia, is een synthetische tetrapeptide die specifiek bindt aan cardiolipine, een lipide in het mitochondriale membraan. Het is bestudeerd in verschillende fase 1 tot fase 3 klinische proeven voor hartfalen, primaire mitochondriale myopathie en Barth syndroom. Ondanks een relatief brede klinische database heeft geen van deze studies tot op heden geleid tot goedkeuring als medicijn.","beschreibung_en":"SS-31, ook bekend onder de generieke naam elamipretide als MTP-131 of Bendavia, is een synthetische tetrapeptide die specifiek bindt aan cardiolipine, een lipide in het mitochondriale membraan. Het is bestudeerd in verschillende fase 1 tot fase 3 klinische proeven voor hartfalen, primaire mitochondriale myopathie en Barth syndroom. Ondanks een relatief brede klinische database heeft geen van deze studies tot op heden geleid tot goedkeuring als medicijn.","mechanismus":"SS-31 bindt met hoge affiniteit aan cardiolipine op het binnenmitochondriale membraan, een lipide vereist voor de cristae structuur. Dit wordt beschreven als het verminderen van reactieve zuurstofsoorten en het stabiliseren van de mitochondriale membraanstructuur. In preklinische modellen was dit gekoppeld aan bescherming tegen ischemie-reperfusieletsel, bijvoorbeeld in hartspier.","mechanismus_en":"SS-31 bindt met hoge affiniteit aan cardiolipine op het binnenmitochondriale membraan, een lipide vereist voor de cristae structuur. Dit wordt beschreven als het verminderen van reactieve zuurstofsoorten en het stabiliseren van de mitochondriale membraanstructuur. In preklinische modellen was dit gekoppeld aan bescherming tegen ischemie-reperfusieletsel, bijvoorbeeld in hartspier.","evidenz":[{"art":"klinisch","kurz":"Een gerandomiseerd, placebo-gecontroleerd fase 3 proef in mensen met primaire mitochondriale myopathie bereikte zijn vooraf gedefinieerde primaire eindpunten niet op de 6-minutenlooptest of de vermoeidheidsscore, hoewel het studiemiddel als goed verdragen werd beschreven.","kurz_en":"Een gerandomiseerd, placebo-gecontroleerd fase 3 proef in mensen met primaire mitochondriale myopathie bereikte zijn vooraf gedefinieerde primaire eindpunten niet op de 6-minutenlooptest of de vermoeidheidsscore, hoewel het studiemiddel als goed verdragen werd beschreven.","quelle":"Karaa et al. 2023, Neurology, PMID 37268435"},{"art":"klinisch","kurz":"Een placebo-gecontroleerde fase 1 proef met stapsgewijs toenemende infusiehoeveelheden bij mensen met hartfalen en verminderde ejectiefractie beschreef een enkele infusie van elamipretide als veilig en goed verdragen.","kurz_en":"Een placebo-gecontroleerde fase 1 proef met stapsgewijs toenemende infusiehoeveelheden bij mensen met hartfalen en verminderde ejectiefractie beschreef een enkele infusie van elamipretide als veilig en goed verdragen.","quelle":"Daubert et al. 2017, Circulation: Heart Failure, PMID 29217757"},{"art":"preklinisch","kurz":"Een studie bij ratten met cardiale ischemie-reperfusieletsel beschreef een significant kleiner infarctgebied wanneer SS-31 vooraf werd gegeven vergeleken met controlegroepen.","kurz_en":"Een studie bij ratten met cardiale ischemie-reperfusieletsel beschreef een significant kleiner infarctgebied wanneer SS-31 vooraf werd gegeven vergeleken met controlegroepen.","quelle":"Cho et al. 2007, Coronary Artery Disease, PMID 17429296"}],"sicherheit":["In klinische proeven tot op heden is elamipretide voornamelijk beschreven als veilig en goed verdragen, met voornamelijk milde tot matige bijwerkingen.","Diverse proeven, waaronder bij mitochondriale myopathie en Barth syndroom, hebben hun primaire effectiviteitsendpunten gemist, waardoor een US goedkeuringsaanvraag in 2021 niet werd geaccepteerd voor beoordeling door het orgaan.","Lange-termijngegevens buiten gecontroleerde studieprogramma's zijn niet beschikbaar.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"sicherheit_en":["In klinische proeven tot op heden is elamipretide voornamelijk beschreven als veilig en goed verdragen, met voornamelijk milde tot matige bijwerkingen.","Diverse proeven, waaronder bij mitochondriale myopathie en Barth syndroom, hebben hun primaire effectiviteitsendpunten gemist, waardoor een US goedkeuringsaanvraag in 2021 niet werd geaccepteerd voor beoordeling door het orgaan.","Lange-termijngegevens buiten gecontroleerde studieprogramma's zijn niet beschikbaar.","Producten uit ongecontroleerde productie hebben een contaminatiegevaar dat onafhankelijk is van het molecuul zelf."],"hinweise":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"hinweise_en":["Uitsluitend voor onderzoeksdoeleinden, niet voor menselijk gebruik","Een analysecertificaat stelt geen medische geschiktheid vast"],"rekonstitution":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rekonstitution_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","lagerung_en":"Productspecifieke voorwaarden staan in de originele documentatie van de fabrikant. Dit portaal biedt geen instructies voor bereiding of menselijk gebruik.","rechtsstatus":"SS-31 (elamipretide) is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Een US goedkeuringsaanvraag in 2021 werd niet geaccepteerd voor beoordeling vanwege het gebrek aan een enkele adequate goed gecontroleerde effectiestudie. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek.","rechtsstatus_en":"SS-31 (elamipretide) is niet goedgekeurd als medicijn in Duitsland, de EU of de Verenigde Staten. Een US goedkeuringsaanvraag in 2021 werd niet geaccepteerd voor beoordeling vanwege het gebrek aan een enkele adequate goed gecontroleerde effectiestudie. Het wordt uitsluitend verkocht als een chemische stof voor onderzoek.","typischeMg":[],"faq":[{"q":"Is elamipretide een goedgekeurd medicijn?","a":"Nee. Ondanks diverse klinische proeven bij hartfalen, mitochondriale myopathie en Barth syndroom is er geen goedkeuring verleend, een US goedkeuringsaanvraag werd niet geaccepteerd voor beoordeling in 2021.","q_en":"Is elamipretide een goedgekeurd medicijn?","a_en":"Nee. Ondanks diverse klinische proeven bij hartfalen, mitochondriale myopathie en Barth syndroom is er geen goedkeuring verleend, een US goedkeuringsaanvraag werd niet geaccepteerd voor beoordeling in 2021."},{"q":"Waarop is SS-31 in het lichaam gericht?","a":"Het bindt aan cardiolipine in het binnenmitochondriale membraan en is geassocieerd met verminderde reactieve zuurstofsoorten en stabilisatie van de membraanstructuur.","q_en":"Waarop is SS-31 in het lichaam gericht?","a_en":"Het bindt aan cardiolipine in het binnenmitochondriale membraan en is geassocieerd met verminderde reactieve zuurstofsoorten en stabilisatie van de membraanstructuur."},{"q":"Heeft de klinische proeven hun doelen bereikt?","a":"Diverse proeven hebben hun vooraf gedefinieerde primaire effectiviteitsendpunten niet bereikt, bijvoorbeeld bij mitochondriale myopathie en Barth syndroom, terwijl de verdraagbaarheid consequent als goed werd beschreven.","q_en":"Heeft de klinische proeven hun doelen bereikt?","a_en":"Diverse proeven hebben hun vooraf gedefinieerde primaire effectiviteitsendpunten niet bereikt, bijvoorbeeld bij mitochondriale myopathie en Barth syndroom, terwijl de verdraagbaarheid consequent als goed werd beschreven."}],"seo":{"title":"SS-31 (elamipretide): Onderzoeksprofiel & Bewijs","title_en":"SS-31 (elamipretide): Onderzoeksprofiel & Bewijs","description":"SS-31/elamipretide overzicht: mitochondriale mechanisme, klinisch bewijs bij hartfalen en mitochondriale myopathie, en veiligheidsprofiel.","description_en":"SS-31/elamipretide overzicht: mitochondriale mechanisme, klinisch bewijs bij hartfalen en mitochondriale myopathie, en veiligheidsprofiel."},"demo":false,"steckbrief":{"cas":"736992-21-5","molekulargewicht":"639,8 g/mol","aminosaeuren":4,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, commercieel standaard)","loeslichkeit":null,"sequenzLaenge":4,"quellen":["PubChem CID 11764719","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, commercieel standaard)"},"verwandt":["mots-c","epitalon","dihexa"]}];
